	fifo_select_out_pipe <= wire_nllO_dataout;
	n0li <= '1';
	rd_enable_out_pipe <= wire_nlli_dataout;
	tx_div2_sync_out_pipe <= wire_nlOi_dataout;
	wr_enable_out_pipe <= wire_nlll_dataout;
	PROCESS (refclk_b_raw)
	BEGIN
		IF (refclk_b_raw = '1' AND refclk_b_raw'event) THEN n00l11 <= n00l12;
		END IF;
		if (now = 0 ns) then
			n00l11 <= '1' after 1 ps;
		end if;
	END PROCESS;
	PROCESS (refclk_b_raw)
	BEGIN
		IF (refclk_b_raw = '1' AND refclk_b_raw'event) THEN n00l12 <= n00l11;
		END IF;
	END PROCESS;
	PROCESS (refclk_b_raw)
	BEGIN
		IF (refclk_b_raw = '1' AND refclk_b_raw'event) THEN n00O10 <= n00O9;
		END IF;
	END PROCESS;
	PROCESS (refclk_b_raw)
	BEGIN
		IF (refclk_b_raw = '1' AND refclk_b_raw'event) THEN n00O9 <= n00O10;
		END IF;
		if (now = 0 ns) then
			n00O9 <= '1' after 1 ps;
		end if;
	END PROCESS;
	PROCESS (refclk_b_raw)
	BEGIN
