		END IF;
		if (now = 0 ns) then
			n0il7 <= '1' after 1 ps;
		end if;
	END PROCESS;
	PROCESS (refclk_b_raw)
	BEGIN
		IF (refclk_b_raw = '1' AND refclk_b_raw'event) THEN n0il8 <= n0il7;
		END IF;
	END PROCESS;
	PROCESS (refclk_b_raw)
	BEGIN
		IF (refclk_b_raw = '1' AND refclk_b_raw'event) THEN n0iO5 <= n0iO6;
		END IF;
		if (now = 0 ns) then
			n0iO5 <= '1' after 1 ps;
		end if;
	END PROCESS;
	PROCESS (refclk_b_raw)
	BEGIN
		IF (refclk_b_raw = '1' AND refclk_b_raw'event) THEN n0iO6 <= n0iO5;
		END IF;
	END PROCESS;
	PROCESS (refclk_b_raw)
	BEGIN
		IF (refclk_b_raw = '1' AND refclk_b_raw'event) THEN n0lO3 <= n0lO4;
		END IF;
		if (now = 0 ns) then
			n0lO3 <= '1' after 1 ps;
		end if;
	END PROCESS;
	PROCESS (refclk_b_raw)
	BEGIN
		IF (refclk_b_raw = '1' AND refclk_b_raw'event) THEN n0lO4 <= n0lO3;
		END IF;
	END PROCESS;
	PROCESS (refclk_b_raw)
	BEGIN
		IF (refclk_b_raw = '1' AND refclk_b_raw'event) THEN n0Oi1 <= n0Oi2;
		END IF;
		if (now = 0 ns) then
			n0Oi1 <= '1' after 1 ps;
		end if;
	END PROCESS;
	PROCESS (refclk_b_raw)
	BEGIN
		IF (refclk_b_raw = '1' AND refclk_b_raw'event) THEN n0Oi2 <= n0Oi1;
		END IF;
	END PROCESS;
	PROCESS (refclk_b_raw, wire_n1i_PRN)
	BEGIN
		IF (wire_n1i_PRN = '0') THEN
				n1l <= '1';
		ELSIF (refclk_b_raw = '1' AND refclk_b_raw'event) THEN
				n1l <= wire_nli_dataout;
		END IF;
		if (now = 0 ns) then
			n1l <= '1' after 1 ps;
		end if;
	END PROCESS;
	wire_n1i_PRN <= ((n00O10 XOR n00O9) AND wire_n1O_w_lg_dataout11w(0));
	PROCESS (fifo_rd_clk_raw, wire_nl_PRN, wire_nl_CLRN)
	BEGIN
		IF (wire_nl_PRN = '0') THEN
				nO <= '1';
		ELSIF (wire_nl_CLRN = '0') THEN
				nO <= '0';
		ELSIF (fifo_rd_clk_raw = '1' AND fifo_rd_clk_raw'event) THEN
				nO <= wire_n0i_dataout;
		END IF;
	END PROCESS;
	wire_nl_CLRN <= ((n0Oi2 XOR n0Oi1) AND wire_w_lg_soft_reset_rclk12w(0));
	wire_nl_PRN <= (n0lO4 XOR n0lO3);
	PROCESS (refclk_b_raw, wire_nlO_PRN, wire_nlO_CLRN)
	BEGIN
		IF (wire_nlO_PRN = '0') THEN
				ni <= '1';
		ELSIF (wire_nlO_CLRN = '0') THEN
				ni <= '0';
		ELSIF (refclk_b_raw = '1' AND refclk_b_raw'event) THEN
				ni <= wire_nil_dataout;
		END IF;
		if (now = 0 ns) then
			ni <= '1' after 1 ps;
		end if;
	END PROCESS;
	wire_nlO_CLRN <= (n0iO6 XOR n0iO5);
	wire_nlO_PRN <= ((n0il8 XOR n0il7) AND wire_w_lg_txrst7w(0));
	PROCESS (wr_clk_pos_raw, wire_nlOl_PRN, soft_reset_wclk1)
	BEGIN
		IF (wire_nlOl_PRN = '0') THEN
				nlOO <= '1';
		ELSIF (soft_reset_wclk1 = '1') THEN
				nlOO <= '0';
		ELSIF (wr_clk_pos_raw = '1' AND wr_clk_pos_raw'event) THEN
				nlOO <= wire_n0O_dataout;
		END IF;
	END PROCESS;
	wire_nlOl_PRN <= (n00l12 XOR n00l11);
	wire_n0i_dataout <= wire_n0l_dataout WHEN wire_w_lg_rmaster_tx9w(0) = '1'  ELSE rd_enable_in_centrl;
	wire_n0l_dataout <= rd_enable_in_pipe_quad_up WHEN rmaster_up_tx = '1'  ELSE rd_enable_in_pipe_quad_down;
	wire_n0O_dataout <= wire_nii_dataout WHEN wire_w_lg_rmaster_tx9w(0) = '1'  ELSE wr_enable_in_centrl;
	wire_n1O_dataout <= txrst AND NOT(rfreerun_tx);
	wire_n1O_w_lg_dataout11w(0) <= NOT wire_n1O_dataout;
	wire_nii_dataout <= wr_enable_in_pipe_quad_up WHEN rmaster_up_tx = '1'  ELSE wr_enable_in_pipe_quad_down;
	wire_nil_dataout <= wire_niO_dataout WHEN wire_w_lg_rmaster_tx9w(0) = '1'  ELSE fifo_select_in_centrl;
	wire_niO_dataout <= fifo_select_in_pipe_quad_up WHEN rmaster_up_tx = '1'  ELSE fifo_select_in_pipe_quad_down;
	wire_nli_dataout <= wire_nll_dataout WHEN wire_w_lg_rmaster_tx9w(0) = '1'  ELSE tx_div2_sync_in_centrl;
	wire_nll_dataout <= tx_div2_sync_in_pipe_quad_up WHEN rmaster_up_tx = '1'  ELSE tx_div2_sync_in_pipe_quad_down;
	wire_nlli_dataout <= wire_n0i_dataout WHEN rpipeline_bypass_tx = '1'  ELSE nO;
	wire_nlll_dataout <= wire_n0O_dataout WHEN rpipeline_bypass_tx = '1'  ELSE nlOO;
	wire_nllO_dataout <= wire_nil_dataout WHEN rpipeline_bypass_tx = '1'  ELSE ni;
	wire_nlOi_dataout <= wire_nli_dataout WHEN rpipeline_bypass_tx = '1'  ELSE n1l;

