         WHEN "10000000" =>
            wptr_gray0 <= "100";
         WHEN OTHERS =>		-- case(wptr)
            wptr_gray0 <= "000";
      END CASE;
   END PROCESS;
   
   -- always@ (wptr)
   
   PROCESS (wptr1)
   BEGIN
      CASE wptr1 IS
         WHEN "000" =>
            wptr1_onehot <= "00000001";
         WHEN "001" =>
            wptr1_onehot <= "00000010";
         WHEN "011" =>
            wptr1_onehot <= "00000100";
         WHEN "010" =>
            wptr1_onehot <= "00001000";
         WHEN "110" =>
            wptr1_onehot <= "00010000";
         WHEN "111" =>
            wptr1_onehot <= "00100000";
         WHEN "101" =>
            wptr1_onehot <= "01000000";
         WHEN "100" =>
            wptr1_onehot <= "10000000";
         WHEN OTHERS =>		-- case(wptr1)
            wptr1_onehot <= "10000000";
      END CASE;
   END PROCESS;
   
   -- always@ (wptr1)
   
   PROCESS (wptr1)
   BEGIN
      CASE wptr1 IS
         WHEN "000" =>
            wptr1_bin_rclk <= "000";
         WHEN "001" =>
            wptr1_bin_rclk <= "001";
         WHEN "011" =>
            wptr1_bin_rclk <= "010";
         WHEN "010" =>
            wptr1_bin_rclk <= "011";
         WHEN "110" =>
            wptr1_bin_rclk <= "100";
         WHEN "111" =>
