   SIGNAL data_reg_15    : STD_LOGIC_VECTOR(ram_width - 1 DOWNTO 0);
BEGIN
   
   --assignment
   data_reg_0 <= data_in WHEN (addr_wr(0) = '1') ELSE
                 ram_array_q_0;
   data_reg_1 <= data_in WHEN (addr_wr(1) = '1') ELSE
                 ram_array_q_1;
   data_reg_2 <= data_in WHEN (addr_wr(2) = '1') ELSE
