         ram_array_d_6 <=  TRANSPORT data_reg_6 AFTER (write_access_time)*1* 1 ps;
         ram_array_d_7 <=  TRANSPORT data_reg_7 AFTER (write_access_time)*1* 1 ps;
         ram_array_d_8 <=  TRANSPORT data_reg_8 AFTER (write_access_time)*1* 1 ps;
