         -- 03/22/05 VC: LEDA fix: Added default clause to case statement
         WHEN "10000000000000000000" =>
            data_out1_i <= ram_array_q_19;
         WHEN OTHERS =>
            data_out1_i <= ram_array_q_0;
      END CASE;
      
