ENTITY cycloneiv_hssi_rx_digis_rxclk_gating IS
    PORT (
        
        select_n                : IN STD_LOGIC;
        clk1                    : IN STD_LOGIC;
        clk2                    : IN STD_LOGIC;
        clk1out_n               : OUT STD_LOGIC;
        clk2out_n               : OUT STD_LOGIC
    );
END cycloneiv_hssi_rx_digis_rxclk_gating;

ARCHITECTURE trans OF cycloneiv_hssi_rx_digis_rxclk_gating IS
BEGIN
    
    clk1out_n <= NOT((select_n OR clk1));
    clk2out_n <= NOT((NOT(select_n) OR clk2));
    
END ARCHITECTURE trans;



-- rxclk_gating

LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
USE ieee.std_logic_unsigned.all;
LIBRARY STD;
USE STD.textio.ALL;
USE work.cycloneiv_hssi_components.all;

ENTITY cycloneiv_hssi_rx_digi_rxclk_ctl IS
   PORT (
      
      -- Clock Inputs
      pld_rx_clk              : IN STD_LOGIC;		-- PLD clock from PLD clock trees
      rcvd_clk_pma            : IN STD_LOGIC;		-- local recovered clock
      rcvd_clk0_pma           : IN STD_LOGIC;		-- channel zero recovered clock
      tx_pma_clk              : IN STD_LOGIC;		-- local TX PMA clock
      refclk_pma              : IN STD_LOGIC;		-- Quad based clk from TXPLL
      fref                    : IN STD_LOGIC;
      clklow                  : IN STD_LOGIC;
      
      -- Control Inputs
      scan_mode               : IN STD_LOGIC;		-- Scan mode enable signal
      -- This is the soft_reset for the RX_PCS
      
      -- New Control Inputs
      gen2ngen1               : IN STD_LOGIC;		-- from PMA for PCIexp Gen1/Gen2 datawidth scaling
      gen2ngen1_bundle        : IN STD_LOGIC;		-- from PMA for PCIexp Gen1/Gen2 datawidth scaling in x4 and x8 
      rx_div2_sync_centrl     : IN STD_LOGIC;		-- divided clock from the central channel (x2, x4 mode)
      rx_div2_sync_quad_up    : IN STD_LOGIC;		-- divided clock from quad above (> x4 mode)
      rx_div2_sync_quad_down  : IN STD_LOGIC;		-- divided clock from quad below (> x4 mode)
      
      -- MDIO Inputs
      rrcvd_clk_sel           : IN STD_LOGIC_VECTOR(1 DOWNTO 0);
      rclk_1_sel              : IN STD_LOGIC_VECTOR(1 DOWNTO 0);
      rclk_2_sel              : IN STD_LOGIC_VECTOR(1 DOWNTO 0);
      rrx_rd_clk_sel          : IN STD_LOGIC;		-- Select clock for rx ph comp fifo read side
      rxrst                   : IN STD_LOGIC;
      rindv_rx                : IN STD_LOGIC;		-- Select between XAUI mode or indiv  channel mode
      rdwidth_rx              : IN STD_LOGIC;		-- divide by 1 or 2 before feeding to FIFO write clock
      rfreerun_rx             : IN STD_LOGIC;		-- Select whether divider is permamently enabled (free -running) or divider should be enabled / reset by RX PCS reset
      
      -- New MDIO Inputs
      rauto_speed_ena         : IN STD_LOGIC;		-- auto speed negotiation enable
      rfreq_sel               : IN STD_LOGIC;		-- freq scaling or data width scaling
      rrxpcsclkpwdn           : IN STD_LOGIC;		-- RX clocking power down enable
      rmaster_rx              : IN STD_LOGIC;		-- New bundle mode MDIO, selects master quad
      rmaster_up_rx           : IN STD_LOGIC;		-- New bundle mode MDIO, selects master quad
      rself_sw_en_rx          : IN STD_LOGIC;		-- enables self-switch to have correct /2 clock in all quads in bundle mode
      
      -- Removed Inputs
      --    input          rphfifo_master_sel_rx;  // RX Phase comp. FIFO rx_div2_sync selection CRAM
      --    input          rx_div2_sync_in_ch0;    // Connect from channel zero rx_div2_sync_out
      --    input          rx_div2_sync_in_q0_ch0; // Connect from channel zero rx_div2_sync_out of Master Quad
      
      -- Clock Outputs with CTS
      fref_muxed              : OUT STD_LOGIC;
      clklow_muxed            : OUT STD_LOGIC;
      rcvd_clk                : OUT STD_LOGIC;
      clk_1_b                 : OUT STD_LOGIC;
      clk_2_b                 : OUT STD_LOGIC;
      rx_wr_clk               : OUT STD_LOGIC;		-- drives the rx ph comp fifo write clock tree
      rx_rd_clk               : OUT STD_LOGIC;		-- drives the rx ph comp fifo read clock tree
      
      -- Clock Outputs to PLD, no CTS
      rx_clk                  : OUT STD_LOGIC;		-- drives the PLD clock tree in x1 mode, logically same as rx_wr_clk
      rcvd_clk_pma_b          : OUT STD_LOGIC;		-- debug output clock to PLD
      
      -- New Clock Outputs with CTS
      clk_2_b_raw             : OUT STD_LOGIC;		-- same as clk_2_b, but with no clock gating
      rx_wr_clk_raw           : OUT STD_LOGIC;		-- same as rx_wr_clk, but with no clock gating
      rx_rd_clk_raw           : OUT STD_LOGIC;		-- same as rx_rd_clk, but with no clock gating
      
      -- Control Outputs
      rx_div2_sync_out        : OUT STD_LOGIC		-- inverted /2 clock.  not used w/new bundling scheme. (left for safety)
   );
END cycloneiv_hssi_rx_digi_rxclk_ctl;

ARCHITECTURE trans OF cycloneiv_hssi_rx_digi_rxclk_ctl IS
   COMPONENT cycloneiv_hssi_rx_digis_rxclk_gating
        PORT (
            select_n                : IN STD_LOGIC;
            clk1                    : IN STD_LOGIC;
            clk2                    : IN STD_LOGIC;
            clk1out_n               : OUT STD_LOGIC;
            clk2out_n               : OUT STD_LOGIC
        );
    END COMPONENT;
      
   SIGNAL rx_clk_2_by2           : STD_LOGIC := '1';
   SIGNAL gen2ngen1_local_sync   : STD_LOGIC;
   SIGNAL counter                : STD_LOGIC_VECTOR(1 DOWNTO 0);
   
   SIGNAL rx_div2_sync           : STD_LOGIC;
   SIGNAL rx_rst_n               : STD_LOGIC;
   SIGNAL rrcvd_clk_sel_int      : STD_LOGIC_VECTOR(1 DOWNTO 0);
   SIGNAL rclk_1_sel_int         : STD_LOGIC_VECTOR(1 DOWNTO 0);
   SIGNAL rclk_2_sel_int         : STD_LOGIC_VECTOR(1 DOWNTO 0);
   SIGNAL dynamic_div2ndiv1      : STD_LOGIC;
   SIGNAL gen2ngen1_local        : STD_LOGIC;
   SIGNAL rrxpcsclkpwdn_nscan    : STD_LOGIC;
   SIGNAL rx_div2_this_quad      : STD_LOGIC;
   SIGNAL rx_div2_this_channel   : STD_LOGIC;
   SIGNAL rx_div2_other_quad     : STD_LOGIC;
   SIGNAL force_master           : STD_LOGIC;
    
    SIGNAL select_div1_n          : STD_LOGIC;
    SIGNAL clk1out_n              : STD_LOGIC;
    SIGNAL clk2out_n              : STD_LOGIC;
   
   -- Declare intermediate signals for referenced outputs
   SIGNAL rx_wr_clk_xhdl3        : STD_LOGIC;
   SIGNAL clk_2_b_raw_xhdl0      : STD_LOGIC;
   SIGNAL rx_wr_clk_raw_xhdl4    : STD_LOGIC;
   SIGNAL rx_rd_clk_raw_xhdl2    : STD_LOGIC;
   SIGNAL rx_div2_sync_out_xhdl1 : STD_LOGIC;
BEGIN
   -- Drive referenced outputs
   rx_wr_clk <= rx_wr_clk_xhdl3;
   clk_2_b_raw <= clk_2_b_raw_xhdl0;
   rx_wr_clk_raw <= rx_wr_clk_raw_xhdl4;
   rx_rd_clk_raw <= rx_rd_clk_raw_xhdl2;
   rx_div2_sync_out <= rx_div2_sync_out_xhdl1;
   
   
   -- Old bundle logic:
   -- Select between the local synchronization signal or the global synchronization signal
   --assign rx_div2_sync = rindv_rx ? rx_div2_sync_out : rx_div2_sync_in;
   -- assign 	  rx_div2_sync = (rphfifo_master_sel_rx == 1'b0) ? rx_div2_sync_in_q0_ch0 :
   -- 				 (rindv_rx == 1'b0) ? rx_div2_sync_in_ch0 : 
   -- 				 (rauto_speed_ena & ~rfreq_sel) ? (rx_div2_sync_out | ~gen2ngen1_local_sync) : rx_div2_sync_out;
   
   PROCESS (rxrst, clk_2_b_raw_xhdl0)
VARIABLE  txt : LINE;
   BEGIN
      IF (rxrst = '1') THEN
         counter <=  TRANSPORT "00" AFTER 1* 1 ps;
      ELSIF (clk_2_b_raw_xhdl0'EVENT AND clk_2_b_raw_xhdl0 = '1') THEN
         IF (((rauto_speed_ena AND NOT(rfreq_sel) AND rself_sw_en_rx) AND NOT(force_master)) = '1') THEN
            counter <=  TRANSPORT counter + "01" AFTER 1* 1 ps;
         END IF;
      END IF;
   END PROCESS;
   
   force_master <= '1' WHEN ((counter = "11") AND ((rauto_speed_ena AND NOT(rfreq_sel) AND rself_sw_en_rx) = '1')) ELSE
                   '0';
   
   rx_div2_sync <= rx_div2_this_quad WHEN ((rmaster_rx OR force_master) = '1') ELSE
                   rx_div2_other_quad;
   rx_div2_this_quad <= rx_div2_this_channel WHEN ((rindv_rx OR force_master) = '1') ELSE
                        rx_div2_sync_centrl;
   rx_div2_this_channel <= (rx_div2_sync_out_xhdl1 OR NOT(gen2ngen1_local_sync)) WHEN ((rauto_speed_ena AND NOT(rfreq_sel)) = '1') ELSE
                           rx_div2_sync_out_xhdl1;
   rx_div2_other_quad <= rx_div2_sync_quad_up WHEN (rmaster_up_rx = '1') ELSE
                         rx_div2_sync_quad_down;
   
   gen2ngen1_local <= gen2ngen1_bundle WHEN (rindv_rx = '0') ELSE
                      gen2ngen1;
   
   PROCESS (rxrst, clk_2_b_raw_xhdl0)
VARIABLE  txt : LINE;
   BEGIN
      IF (rxrst = '1') THEN
         gen2ngen1_local_sync <=  TRANSPORT '0' AFTER 1* 1 ps;
      ELSIF (clk_2_b_raw_xhdl0'EVENT AND clk_2_b_raw_xhdl0 = '1') THEN
         gen2ngen1_local_sync <=  TRANSPORT gen2ngen1_local AFTER 1* 1 ps;
      END IF;
   END PROCESS;
   
   dynamic_div2ndiv1 <= rdwidth_rx OR (gen2ngen1_local_sync AND rauto_speed_ena AND NOT(rfreq_sel));
   
   -- Reset for Divide-by-2 FF and synchronization FF's for clock gating
   rx_rst_n <= '1' WHEN (rfreerun_rx = '1') ELSE
               NOT(rxrst);
   
   rrxpcsclkpwdn_nscan <= rrxpcsclkpwdn AND NOT(scan_mode);
   
   -- clocks are assigned below in the order in which they appear in the out flowing data path
   -- RCVD_CLK selection
   rrcvd_clk_sel_int <= "01" WHEN (scan_mode = '1') ELSE
                        rrcvd_clk_sel;
   rcvd_clk <= '1' WHEN (rrxpcsclkpwdn_nscan = '1') ELSE
               rcvd_clk_pma WHEN (rrcvd_clk_sel_int = "00") ELSE
               refclk_pma WHEN (rrcvd_clk_sel_int = "01") ELSE
               tx_pma_clk WHEN (rrcvd_clk_sel_int = "10") ELSE
               rcvd_clk_pma WHEN (rrcvd_clk_sel_int = "11") ELSE
               rcvd_clk_pma;
   
   -- CLK_1 seleciton
   rclk_1_sel_int <= "01" WHEN (scan_mode = '1') ELSE
                     rclk_1_sel;
   clk_1_b <= '1' WHEN (rrxpcsclkpwdn_nscan = '1') ELSE
              rcvd_clk_pma WHEN (rclk_1_sel_int = "00") ELSE
              refclk_pma WHEN (rclk_1_sel_int = "01") ELSE
              tx_pma_clk WHEN (rclk_1_sel_int = "10") ELSE
              rcvd_clk0_pma WHEN (rclk_1_sel_int = "11") ELSE
              rcvd_clk_pma;
   
   -- CLK_2 selection
   rclk_2_sel_int <= "10" WHEN (scan_mode = '1') ELSE
                     rclk_2_sel;
   clk_2_b_raw_xhdl0 <= rcvd_clk_pma WHEN (rclk_2_sel_int = "00") ELSE
                        tx_pma_clk WHEN (rclk_2_sel_int = "01") ELSE
                        refclk_pma WHEN (rclk_2_sel_int = "10") ELSE
                        rcvd_clk_pma;
   --change made for S3GX to remove pld_rx_clk from mux input 
   --(rclk_2_sel_int == 2'b10) ? refclk_pma : 
   --(rclk_2_sel_int == 2'b11) ? pld_rx_clk : rcvd_clk_pma;
   
   clk_2_b <= '1' WHEN (rrxpcsclkpwdn_nscan = '1') ELSE
              clk_2_b_raw_xhdl0;
   
   -- This register is used to generate divided by two clock. Div by 2 clock starts off high after reset
   -- No #1 on this FF as it generates a clock
   PROCESS (rx_rst_n, clk_2_b_raw_xhdl0)
VARIABLE  txt : LINE;
   BEGIN
      IF ((NOT(rx_rst_n)) = '1') THEN
         rx_clk_2_by2 <= '1';
      ELSIF (clk_2_b_raw_xhdl0'EVENT AND clk_2_b_raw_xhdl0 = '1') THEN
         rx_clk_2_by2 <= rx_div2_sync;
      END IF;
   END PROCESS;
   
   rx_div2_sync_out_xhdl1 <= NOT(rx_clk_2_by2);
   
   -- RX FIFO write clock: could be fast or divided by 2
   -- old code:
   -- assign rx_wr_clk = ((rdwidth_rx == 1'b0) || scan_mode) ? clk_2_b_raw : rx_clk_2_by2;
   
    select_div1_n <= NOT((scan_mode OR NOT(dynamic_div2ndiv1)));
        
    rxclk_gating : cycloneiv_hssi_rx_digis_rxclk_gating
        PORT MAP (
            select_n   => select_div1_n,
            clk1       => clk_2_b_raw_xhdl0,
            clk2       => rx_clk_2_by2,
            clk1out_n  => clk1out_n,
            clk2out_n  => clk2out_n
        );
    
    rx_wr_clk_raw_xhdl4 <= NOT((clk1out_n OR clk2out_n));
   
   
   rx_wr_clk_xhdl3 <= '1' WHEN (rrxpcsclkpwdn_nscan = '1') ELSE
                      rx_wr_clk_raw_xhdl4;
   
   -- RX FIFO read clock
   rx_rd_clk_raw_xhdl2 <= rx_wr_clk_raw_xhdl4 WHEN ((scan_mode OR int2bit((rrx_rd_clk_sel = '0'))) = '1') ELSE
                          pld_rx_clk;
   rx_rd_clk <= '1' WHEN (rrxpcsclkpwdn_nscan = '1') ELSE
                rx_rd_clk_raw_xhdl2;
   
   -- RX clock out
   rx_clk <= rx_wr_clk_xhdl3;		-- drives PLD clock tree
   
   -- Recovered clock for debugging
   rcvd_clk_pma_b <= rcvd_clk_pma;		-- Goes out to PLD as debug clock. This clock may or may not be routed out to PLD fabric. TBD
   
   fref_muxed <= refclk_pma WHEN (scan_mode = '1') ELSE
                 '1' WHEN (rrxpcsclkpwdn = '1') ELSE
                 fref;
   clklow_muxed <= refclk_pma WHEN (scan_mode = '1') ELSE
                   '1' WHEN (rrxpcsclkpwdn = '1') ELSE
                   clklow;
   
END trans;




