USE work.cycloneiv_hssi_components.all;

ENTITY cycloneiv_hssi_rx_digi IS
   PORT (
      -- S. Park 3/21/08 - Removed following ports
      -- disable_fifo_rd_0,
      -- disable_fifo_wr_0,
      -- disable_fifo_rd, 
      -- disable_fifo_wr,
      --new for auto-nego
      -- new MDIO inputs for bundling and auto speed
      -- new outputs for bundling and auto speed
      --new for Eidle inference
      -- CDR control
      -- S. Park 3/13/08 - Added for XAUI compliance
      -- S. Park 3/21/08 - Added for XAUI compliance
      
      -- Reset inputs
      hard_reset                       : IN STD_LOGIC;		-- From MDIO_REG.V Complex function of NPOR, ENTEST etc.,
      rxpcs_rst                        : IN STD_LOGIC;		-- RX PCS resets
      rxpma_rst                        : IN STD_LOGIC;		-- RX PMA reset for PPM Detect
      cmpfifourst                      : IN STD_LOGIC;		-- User reset exclusive to comp_chnl_top & below
      phfifourst_rx                    : IN STD_LOGIC;		-- User reset exclusive to rx_ctrl & below
      
      -- Scan inputs
      scan_mode                        : IN STD_LOGIC;		-- 1'b1 = scan mode active; 
      -- 1'b0 = normal mode
      -- RX PCS channel inputs/outputs
      encdt                            : IN STD_LOGIC;		-- Comma Detect enable control signal from PLD
      a1a2_size                        : IN STD_LOGIC;		-- A1A2 size control signal for byte sync block
      bitslip                          : IN STD_LOGIC;		-- Bitslip control signal from PLD
      rdenable_rmf                     : IN STD_LOGIC;		-- Read enable control signal for CompFIFO
      wrenable_rmf                     : IN STD_LOGIC;		-- Write enable control signal for CompFIFO
      pld_rx_clk                       : IN STD_LOGIC;		-- Parallel receive clock from PLD
      soft_reset_rclk1                 : OUT STD_LOGIC;		-- Synchronized reset
      polinv_rx                        : IN STD_LOGIC;		-- RX polarity inversion dynamic control signal
      bitloc_rev_en                    : IN STD_LOGIC;		-- RX bit reversal dynamic control signal
      byte_rev_en                      : IN STD_LOGIC;		-- RX byte swap dynamic control signal
      rcvd_clk_pma                     : IN STD_LOGIC;
      pudi                             : IN STD_LOGIC_VECTOR(19 DOWNTO 0);		-- RX 10-bit code group bus from RX PMA
      sigdetni                         : IN STD_LOGIC;		-- rx signal detected from PMA
      fifo_rst_rd_qd                   : IN STD_LOGIC;		-- from master deskew sm
      fifo_rst_rd_gp                   : IN STD_LOGIC;		-- from grouping deskew sm
      en_dskw_qd                       : IN STD_LOGIC;		-- from master deskew sm
      en_dskw_gp                       : IN STD_LOGIC;		-- from grouping deskew sm
      is_lane0                         : IN STD_LOGIC;		-- This is lane 0 if 1'b1. Hard-wired
      -- when chnl_top is instantiated
      align_status                     : IN STD_LOGIC;		-- Indicate that four lanes are now 
      -- aligned in dskw_top
      align_status_sync_0              : IN STD_LOGIC;		-- Synced to clk_2 from channel 0
      align_status_sync_2              : IN STD_LOGIC;		-- Synced to clk_2 from channel 2
      -- S. Park 3/21/08 - Removed below two ports
      -- input          disable_fifo_rd_0;     // disable_fifo_rd from channel 0
      -- input          disable_fifo_wr_0;     // disable_fifo_wr from channel 0
      rx_data_rs                       : IN STD_LOGIC_VECTOR(7 DOWNTO 0);		-- rx data from 10G ethernet rx state machine
      rx_control_rs                    : IN STD_LOGIC;		-- rx control from 10G ethernet rx state machine
      rcvd_clk0_pma                    : IN STD_LOGIC;		-- Recovered clock from PMA channel0
      fifo_rd_in_comp_0                : IN STD_LOGIC;		-- fifo_rd_in_comp from channel 0
      fifo_rd_in_comp_2                : IN STD_LOGIC;		-- fifo_rd_in_comp from channel 2
      txlp20b                          : IN STD_LOGIC_VECTOR(19 DOWNTO 0);		-- tx 20-bit code group bus to PMA
      refclk_pma                       : IN STD_LOGIC;		-- Global parallel TX PLL clock
      tx_pma_clk                       : IN STD_LOGIC;		-- Per channel TX PMA clock
      fref                             : IN STD_LOGIC;		-- Reference clock for FREQDET module
      clklow                           : IN STD_LOGIC;		-- Divided clock for FREQDET module
      bytordpld                        : IN STD_LOGIC;		-- Byte ordering dynamic control signal from PLD
      wrdisable_rx                     : IN STD_LOGIC;		-- RX phase comp. FIFO write disable control signal
      rdenable_rx                      : IN STD_LOGIC;		-- RX phase comp. FIFO read enable control signal
