     BEGIN
         VitalWireDelay (coreclk_ipd,coreclk, tipd_coreclk);   -- kept for TCO
         VitalWireDelay (xgmctrlin_ipd,xgmctrlin, tipd_xgmctrlin);
       bits_pipepowerdown : FOR i in pipepowerdown'RANGE GENERATE
           VitalWireDelay (pipepowerdown_ipd(i),pipepowerdown(i), tipd_pipepowerdown(i));
       END GENERATE;
       bits_parallelfdbk : FOR i in parallelfdbk'RANGE GENERATE
           VitalWireDelay (parallelfdbk_ipd(i),parallelfdbk(i), tipd_parallelfdbk(i));
       END GENERATE;
           VitalWireDelay (masterclk_ipd,masterclk, tipd_masterclk);
       bits_pipepowerstate : FOR i in pipepowerstate'RANGE GENERATE
           VitalWireDelay (pipepowerstate_ipd(i),pipepowerstate(i), tipd_pipepowerstate(i));
       END GENERATE;
           VitalWireDelay (alignstatussync_ipd,alignstatussync, tipd_alignstatussync);
       bits_powerdn : FOR i in powerdn'RANGE GENERATE
           VitalWireDelay (powerdn_ipd(i),powerdn(i), tipd_powerdn(i));
       END GENERATE;
           VitalWireDelay (refclk_ipd,refclk, tipd_refclk);
           VitalWireDelay (phfifox4bytesel_ipd,phfifox4bytesel, tipd_phfifox4bytesel);
           VitalWireDelay (bitslip_ipd,bitslip, tipd_bitslip);
           VitalWireDelay (phfiforeset_ipd,phfiforeset, tipd_phfiforeset);
       bits_dprioin : FOR i in dprioin'RANGE GENERATE
           VitalWireDelay (dprioin_ipd(i),dprioin(i), tipd_dprioin(i));
       END GENERATE;
       bits_datain : FOR i in datain'RANGE GENERATE
           VitalWireDelay (datain_ipd(i),datain(i), tipd_datain(i));
       END GENERATE;
           VitalWireDelay (enabledeskew_ipd,enabledeskew, tipd_enabledeskew);
       bits_hippowerdown : FOR i in hippowerdown'RANGE GENERATE
           VitalWireDelay (hippowerdown_ipd(i),hippowerdown(i), tipd_hippowerdown(i));
       END GENERATE;
           VitalWireDelay (revbyteorderwa_ipd,revbyteorderwa, tipd_revbyteorderwa);
           VitalWireDelay (phfifox4wrenable_ipd,phfifox4wrenable, tipd_phfifox4wrenable);
           VitalWireDelay (dpriodisable_ipd,dpriodisable, tipd_dpriodisable);
           VitalWireDelay (enabyteord_ipd,enabyteord, tipd_enabyteord);
           VitalWireDelay (invpol_ipd,invpol, tipd_invpol);
           VitalWireDelay (revbitorderwa_ipd,revbitorderwa, tipd_revbitorderwa);
           VitalWireDelay (localrefclk_ipd,localrefclk, tipd_localrefclk);
           VitalWireDelay (enapatternalign_ipd,enapatternalign, tipd_enapatternalign);
           VitalWireDelay (phfifowrdisable_ipd,phfifowrdisable, tipd_phfifowrdisable);
           VitalWireDelay (signaldetected_ipd,signaldetected, tipd_signaldetected);
           VitalWireDelay (alignstatus_ipd,alignstatus, tipd_alignstatus);
           VitalWireDelay (quadreset_ipd,quadreset, tipd_quadreset);
           VitalWireDelay (rxdetectvalid_ipd,rxdetectvalid, tipd_rxdetectvalid);
           VitalWireDelay (recoveredclk_ipd,recoveredclk, tipd_recoveredclk);
           VitalWireDelay (phfifordenable_ipd,phfifordenable, tipd_phfifordenable);
           VitalWireDelay (phfifox4wrclk_ipd,phfifox4wrclk, tipd_phfifox4wrclk);
           VitalWireDelay (rmfifowrena_ipd,rmfifowrena, tipd_rmfifowrena);
           VitalWireDelay (a1a2size_ipd,a1a2size, tipd_a1a2size);
       bits_elecidleinfersel : FOR i in elecidleinfersel'RANGE GENERATE
           VitalWireDelay (elecidleinfersel_ipd(i),elecidleinfersel(i), tipd_elecidleinfersel(i));
       END GENERATE;
           VitalWireDelay (hip8b10binvpolarity_ipd,hip8b10binvpolarity, tipd_hip8b10binvpolarity);
           VitalWireDelay (rmfiforeset_ipd,rmfiforeset, tipd_rmfiforeset);
           VitalWireDelay (coreclk_ipd,coreclk, tipd_coreclk);
           VitalWireDelay (rmfifordena_ipd,rmfifordena, tipd_rmfifordena);
       bits_hipelecidleinfersel : FOR i in hipelecidleinfersel'RANGE GENERATE
           VitalWireDelay (hipelecidleinfersel_ipd(i),hipelecidleinfersel(i), tipd_hipelecidleinfersel(i));
       END GENERATE;
           VitalWireDelay (phfifox4rdenable_ipd,phfifox4rdenable, tipd_phfifox4rdenable);
           VitalWireDelay (pipe8b10binvpolarity_ipd,pipe8b10binvpolarity, tipd_pipe8b10binvpolarity);
           VitalWireDelay (fifordin_ipd,fifordin, tipd_fifordin);
           VitalWireDelay (prbscidenable_ipd,prbscidenable, tipd_prbscidenable);
           VitalWireDelay (digitalreset_ipd,digitalreset, tipd_digitalreset);
       bits_rxfound : FOR i in rxfound'RANGE GENERATE
           VitalWireDelay (rxfound_ipd(i),rxfound(i), tipd_rxfound(i));
       END GENERATE;
           VitalWireDelay (cdrctrllocktorefcl_ipd,cdrctrllocktorefcl, tipd_cdrctrllocktorefcl);
           VitalWireDelay (fiforesetrd_ipd,fiforesetrd, tipd_fiforesetrd);
       bits_xgmdatain : FOR i in xgmdatain'RANGE GENERATE
           VitalWireDelay (xgmdatain_ipd(i),xgmdatain(i), tipd_xgmdatain(i));
       END GENERATE;
     END BLOCK;
           
                  
