    --- cycloneiv_modify begin DOWNTO  cycloneiv output layer to adjust width change ----
    a1a2sizeout_reg_sr        <= a1a2sizeout_reg(1 DOWNTO 0);
    a1detect_reg_sr           <= a1detect_reg(0);
    a2detect_reg_sr           <= a2detect_reg(0);
    ctrldetect_reg_sr         <= ctrldetect_reg(1 DOWNTO 0);
    dataout_reg_sr            <= dataout_reg(19 DOWNTO 0);
    dataoutfull_sr(15 DOWNTO 0) <= rd_out_rxd(15 DOWNTO 0);
    dataoutfull_sr(31 DOWNTO 16) <= rd_out_rxd(47 DOWNTO 32);
    disperr_reg_sr            <= disperr_reg(1 DOWNTO 0);
    errdetect_reg_sr          <= errdetect_reg(1 DOWNTO 0);
    k1detect_reg_sr           <= k1detect_reg(0);
    k2detect_reg_sr           <= k2detect_reg(0);
    patterndetect_reg_sr      <= patterndetect_reg(1 DOWNTO 0);
    rmfifodatadeleted_reg_sr  <= rmfifodatadeleted_reg(1 DOWNTO 0);        
    rmfifodatainserted_reg_sr <= rmfifodatainserted_reg(1 DOWNTO 0);
    runningdisp_reg_sr        <= runningdisp_reg(1 DOWNTO 0);
    syncstatus_reg_sr         <= syncstatus_reg(1 DOWNTO 0);
    --- cycloneiv_modify end: cycloneiv output layer to adjust width change ------
      
    VITAL: PROCESS (coreclk_ipd, a1a2sizeout_reg_sr, ctrldetect_reg_sr, dataout_reg_sr, disperr_reg_sr, errdetect_reg_sr, patterndetect_reg_sr, rmfifodatadeleted_reg_sr, rmfifodatainserted_reg_sr, runningdisp_reg_sr, syncstatus_reg_sr, pi_out_rxd_ch, rd_out_byteord_flag, rd_out_full_rx, rd_out_empty_rx, hs_out_rxstatus_ch, hs_out_phystatus, hs_out_rxvalid, rd_out_rxd(13), rd_out_rxd(14), rd_out_rxd(45), rd_out_rxd(46))
    variable Tviol_phfifordenable_coreclk : std_ulogic := '0';
    variable TimingData_phfifordenable_coreclk : VitalTimingDataType := VitalTimingDataInit;

    variable pipebufferstat0_VitalGlitchData: VitalGlitchDataType;
    variable pipebufferstat1_VitalGlitchData: VitalGlitchDataType;
    variable pipebufferstat2_VitalGlitchData: VitalGlitchDataType;
    variable pipebufferstat3_VitalGlitchData: VitalGlitchDataType;
    variable byteorderalignstatus_VitalGlitchData: VitalGlitchDataType;
    variable phfifooverflow_VitalGlitchData: VitalGlitchDataType;
    variable phfifounderflow_VitalGlitchData: VitalGlitchDataType;
    variable pipephydonestatus_VitalGlitchData: VitalGlitchDataType;
    variable pipedatavalid_VitalGlitchData: VitalGlitchDataType;
    variable CQDelayA1a2sizeout: TIME := 0 ns;
    variable CQDelayCtrldetect: TIME := 0 ns;
    variable CQDelayDataout: TIME := 0 ns;
    variable CQDelayDataoutfull: TIME := 0 ns;
    variable CQDelayDisperr: TIME := 0 ns;
    variable CQDelayErrdetect: TIME := 0 ns;
    variable CQDelayPatterndetect: TIME := 0 ns;
    variable CQDelayRmfifodatadeleted: TIME := 0 ns;
    variable CQDelayRmfifodatainserted: TIME := 0 ns;
    variable CQDelayRunningdisp: TIME := 0 ns;
    variable CQDelaySyncstatus: TIME := 0 ns;
    variable CQDelayPipestatus: TIME := 0 ns;

    BEGIN

        ------------------------
        --  Timing Check Section
        ------------------------

        if (TimingChecksOn) then

            VitalSetupHoldCheck (
                Violation       => Tviol_phfifordenable_coreclk,
                TimingData      => TimingData_phfifordenable_coreclk,
                TestSignal      => phfifordenable_ipd,
                TestSignalName  => "PHFIFORDENABLE",
                RefSignal       => coreclk_ipd,
                RefSignalName   => "CORECLK",
                SetupHigh       => tsetup_phfifordenable_coreclk_noedge_posedge,
                SetupLow        => tsetup_phfifordenable_coreclk_noedge_posedge,
                HoldHigh        => thold_phfifordenable_coreclk_noedge_posedge,
                HoldLow         => thold_phfifordenable_coreclk_noedge_posedge,
                RefTransition   => '/',
                HeaderMsg       => InstancePath & "/CYCLONEIV_HSSI_RX_PCS",
                XOn             => XOnChecks,
                MsgOn           => MsgOnChecks );
        end if;

        ----------------------
        --  Path Delay Section
        ----------------------

        CQDelayA1a2sizeout := hssiSelectDelay (
            Paths => (0 => (coreclk_ipd'last_event, tpd_coreclk_a1a2sizeout_posedge, TRUE)));
        a1a2sizeout <= TRANSPORT a1a2sizeout_reg_sr AFTER CQDelayA1a2sizeout;

        CQDelayCtrldetect := hssiSelectDelay (
            Paths => (0 => (coreclk_ipd'last_event, tpd_coreclk_ctrldetect_posedge, TRUE)));
        ctrldetect <= TRANSPORT ctrldetect_reg_sr AFTER CQDelayCtrldetect;

        CQDelayDataout := hssiSelectDelay (
            Paths => (0 => (coreclk_ipd'last_event, tpd_coreclk_dataout_posedge, TRUE)));
        dataout <= TRANSPORT dataout_reg_sr AFTER CQDelayDataout;

        CQDelayDataoutfull := hssiSelectDelay (
            Paths => (0 => (coreclk_ipd'last_event, tpd_coreclk_dataoutfull_posedge, TRUE)));
        dataoutfull <= TRANSPORT dataoutfull_sr AFTER CQDelayDataoutfull;

        CQDelayDisperr := hssiSelectDelay (
            Paths => (0 => (coreclk_ipd'last_event, tpd_coreclk_disperr_posedge, TRUE)));
        disperr <= TRANSPORT disperr_reg_sr AFTER CQDelayDisperr;

        CQDelayErrdetect := hssiSelectDelay (
            Paths => (0 => (coreclk_ipd'last_event, tpd_coreclk_errdetect_posedge, TRUE)));
        errdetect <= TRANSPORT errdetect_reg_sr AFTER CQDelayErrdetect;

        CQDelayPatterndetect := hssiSelectDelay (
            Paths => (0 => (coreclk_ipd'last_event, tpd_coreclk_patterndetect_posedge, TRUE)));
        patterndetect <= TRANSPORT patterndetect_reg_sr AFTER CQDelayPatterndetect;

        CQDelayRmfifodatadeleted := hssiSelectDelay (
            Paths => (0 => (coreclk_ipd'last_event, tpd_coreclk_rmfifodatadeleted_posedge, TRUE)));
        rmfifodatadeleted <= TRANSPORT rmfifodatadeleted_reg_sr AFTER CQDelayRmfifodatadeleted;

        CQDelayRmfifodatainserted := hssiSelectDelay (
            Paths => (0 => (coreclk_ipd'last_event, tpd_coreclk_rmfifodatainserted_posedge, TRUE)));
        rmfifodatainserted <= TRANSPORT rmfifodatainserted_reg_sr AFTER CQDelayRmfifodatainserted;

        CQDelayRunningdisp := hssiSelectDelay (
            Paths => (0 => (coreclk_ipd'last_event, tpd_coreclk_runningdisp_posedge, TRUE)));
        runningdisp <= TRANSPORT runningdisp_reg_sr AFTER CQDelayRunningdisp;

        CQDelaySyncstatus := hssiSelectDelay (
             Paths => (0 => (coreclk_ipd'last_event, tpd_coreclk_syncstatus_posedge, TRUE)));
        syncstatus <= TRANSPORT syncstatus_reg_sr AFTER CQDelaySyncstatus;

         VitalPathDelay01 (
             OutSignal => pipebufferstat(0),
             OutSignalName => "PIPEBUFFERSTAT",
             OutTemp => rd_out_rxd(13),
             Paths => (1 => (coreclk_ipd'last_event, tpd_coreclk_pipebufferstat_posedge(0), TRUE)),
             GlitchData => pipebufferstat0_VitalGlitchData,
             Mode => DefGlitchMode,
             XOn  => XOn,
             MsgOn  => MsgOn );

         VitalPathDelay01 (
             OutSignal => pipebufferstat(1),
             OutSignalName => "PIPEBUFFERSTAT",
             OutTemp => rd_out_rxd(14),
             Paths => (1 => (coreclk_ipd'last_event, tpd_coreclk_pipebufferstat_posedge(1), TRUE)),
             GlitchData => pipebufferstat1_VitalGlitchData,
             Mode => DefGlitchMode,
             XOn  => XOn,
             MsgOn  => MsgOn );

         VitalPathDelay01 (
             OutSignal => pipebufferstat(2),
             OutSignalName => "PIPEBUFFERSTAT",
             OutTemp => rd_out_rxd(45),
             Paths => (1 => (coreclk_ipd'last_event, tpd_coreclk_pipebufferstat_posedge(2), TRUE)),
             GlitchData => pipebufferstat2_VitalGlitchData,
             Mode => DefGlitchMode,
             XOn  => XOn,
             MsgOn  => MsgOn );

         VitalPathDelay01 (
             OutSignal => pipebufferstat(3),
             OutSignalName => "PIPEBUFFERSTAT",
             OutTemp => rd_out_rxd(46),
             Paths => (1 => (coreclk_ipd'last_event, tpd_coreclk_pipebufferstat_posedge(3), TRUE)),
             GlitchData => pipebufferstat3_VitalGlitchData,
             Mode => DefGlitchMode,
             XOn  => XOn,
             MsgOn  => MsgOn );

        VitalPathDelay01 (
            OutSignal => byteorderalignstatus,
            OutSignalName => "BYTEORDERALIGNSTATUS",
            OutTemp => rd_out_byteord_flag,
            Paths => (1 => (coreclk_ipd'last_event, tpd_coreclk_byteorderalignstatus_posedge, TRUE)),
            GlitchData => byteorderalignstatus_VitalGlitchData,
            Mode => DefGlitchMode,
            XOn  => XOn,
            MsgOn  => MsgOn );

        VitalPathDelay01 (
            OutSignal => phfifooverflow,
            OutSignalName => "PHFIFOOVERFLOW",
            OutTemp => rd_out_full_rx,
            Paths => (1 => (coreclk_ipd'last_event, tpd_coreclk_phfifooverflow_posedge, TRUE)),
            GlitchData => phfifooverflow_VitalGlitchData,
            Mode => DefGlitchMode,
            XOn  => XOn,
            MsgOn  => MsgOn );

        VitalPathDelay01 (
            OutSignal => phfifounderflow,
            OutSignalName => "PHFIFOUNDERFLOW",
            OutTemp => rd_out_empty_rx,
            Paths => (1 => (coreclk_ipd'last_event, tpd_coreclk_phfifounderflow_posedge, TRUE)),
            GlitchData => phfifounderflow_VitalGlitchData,
            Mode => DefGlitchMode,
            XOn  => XOn,
            MsgOn  => MsgOn );

         CQDelayPipestatus := hssiSelectDelay (
             Paths => (0 => (coreclk_ipd'last_event, tpd_coreclk_pipestatus_posedge, TRUE)));
         pipestatus <= TRANSPORT hs_out_rxstatus_ch AFTER CQDelayPipestatus;

         VitalPathDelay01 (
             OutSignal => pipephydonestatus,
             OutSignalName => "PIPEPHYDONESTATUS",
             OutTemp => hs_out_phystatus,
             Paths => (1 => (coreclk_ipd'last_event, tpd_coreclk_pipephydonestatus_posedge, TRUE)),
             GlitchData => pipephydonestatus_VitalGlitchData,
             Mode => DefGlitchMode,
             XOn  => XOn,
             MsgOn  => MsgOn );

         VitalPathDelay01 (
             OutSignal => pipedatavalid,
             OutSignalName => "pipedatavalid",
             OutTemp => hs_out_rxvalid,
             Paths => (1 => (coreclk_ipd'last_event, tpd_coreclk_pipedatavalid_posedge, TRUE)),
             GlitchData => pipedatavalid_VitalGlitchData,
             Mode => DefGlitchMode,
             XOn  => XOn,
             MsgOn  => MsgOn );

    END PROCESS;


   a1a2size_in <= '1' WHEN (a1a2size = '1') ELSE
