   PROCESS 
      
       FUNCTION compute_rrundisp (                                                           
       pma_doublewidth         : IN std_logic;                                                
       pma_width               : IN std_logic;                                                
       run_length              : IN integer) RETURN STD_LOGIC_VECTOR IS                       
                                                          
                                                                                              
       VARIABLE res                    :  std_logic_vector(5 DOWNTO 0);                       
       VARIABLE compute_rrundisp       :  std_logic_vector(5 DOWNTO 0);                       
       VARIABLE run_len_stepped        :  integer;                                            
       VARIABLE temp_xhdl56 : STD_LOGIC_VECTOR(1 DOWNTO 0);                                   
       VARIABLE txt : LINE;                                                                   
   BEGIN                                                                                      
       temp_xhdl56 := pma_doublewidth & pma_width;                                            
       CASE temp_xhdl56 IS                                                                    
           WHEN "00" =>                                                                       
                       run_len_stepped := run_length / 4;                                     
                       IF (run_len_stepped = 32) THEN                                         
                           res := "000000";                                                   
                       ELSE                                                                   
                           res := int2bin(run_len_stepped, 6);                                
                       END IF;                                                                
           WHEN "01" =>                                                                       
                       run_len_stepped := run_length / 5;                                     
                       IF (run_len_stepped = 32) THEN                                         
                           res := "000000";                                                   
                       ELSE                                                                   
                           res := int2bin(run_len_stepped, 6);                                
                       END IF;                                                                
           WHEN "10" =>                                                                       
                       run_len_stepped := run_length / 8;                                     
                       IF (run_len_stepped = 64) THEN                                         
                           res := "000000";                                                   
                       ELSE                                                                   
                           res := int2bin(run_len_stepped, 6);                                
                       END IF;                                                                
           WHEN "11" =>                                                                       
                       run_len_stepped := run_length / 10;                                    
                       IF (run_len_stepped = 64) THEN                                         
                           res := "000000";                                                   
                       ELSE                                                                   
                           res := int2bin(run_len_stepped, 6);                                
                       END IF;                                                                
           WHEN OTHERS  =>                                                                    
                       --WRITE(TXT,STRING'("Invalid pma_doublewidth and pma_width selection")); 
                      -- WRITELINE(OUTPUT,TXT);                                                 
       END CASE;                                                                              
       RETURN res;                                                                        
   END compute_rrundisp;                                                                      
      
   FUNCTION compute_rprbs_sel_rx (                                                                                  
           pma_doublewidth         : IN std_logic;                                                                   
           pma_width               : IN std_logic;                                                                   
           test_mode                          : IN STRING) RETURN STD_LOGIC_VECTOR IS                       
                                                                                   
                                                                                                                     
           VARIABLE res                    :  std_logic_vector(2 DOWNTO 0);                                          
           VARIABLE compute_rprbs_sel_rx        : std_logic_vector(2 DOWNTO 0);                                      
           VARIABLE temp_xhdl56 : STD_LOGIC_VECTOR(1 DOWNTO 0);                                                      
           VARIABLE txt : LINE;                                                                                      
       BEGIN                                                                                                         
           temp_xhdl56 := pma_doublewidth & pma_width;                                                               
           CASE temp_xhdl56 IS                                                                                       
               WHEN "00" =>                                                                                          
                           IF ((test_mode = "prbs_8") OR (test_mode = "prbs8")) THEN       
                               res := "000";                                                                         
                           ELSIF (test_mode = "prbs7") THEN
                               res := "010";                     
                           ELSIF (test_mode = "prbs23") THEN
                               res := "100";
                           ELSIF (test_mode = "high frequency") THEN
                               res := "001";
                           ELSE                        
                               res := "000";     -- default
                           END IF;                                                                                   
               WHEN "01" =>                                                                                          
                           IF ((test_mode = "prbs_10") OR (test_mode = "prbs10")) THEN    
                               res := "000";                                                                         
                           ELSIF (test_mode = "high frequency") THEN
                               res := "001";
                           ELSIF (test_mode = "low frequency") THEN
                               res := "010";
                           ELSIF (test_mode = "mixed frequency") THEN
                               res := "011";
                           ELSE
                               res := "000";     -- default
                           END IF;                                                                                   
               WHEN "10" =>                                                                                          
                           IF ((test_mode = "prbs_7") OR (test_mode = "prbs7")) THEN       
                               res := "000";                                                                         
                           ELSIF (test_mode = "prbs_23" OR test_mode = "prbs23")  THEN
                               res := "001";
                           ELSIF (test_mode = "high frequency")  THEN
                               res := "010";
                           ELSE
                               res := "000";     -- default
                           END IF;                                                                                   
               WHEN "11" =>                                                                                          
                           IF ((test_mode = "prbs_7") OR (test_mode = "prbs7")) THEN       
                               res := "000";                                                                         
                           ELSIF ((test_mode = "prbs_23") OR (test_mode = "prbs23")) THEN
                               res := "001";                     
                           ELSIF (test_mode = "high frequency") THEN
                               res := "010";
                           ELSIF (test_mode = "low frequency") THEN
                               res := "011";
                           ELSIF (test_mode = "mixed frequency") THEN
                               res := "100";
                           ELSE
                               res := "000";     -- default
                           END IF;                                                                                   
               WHEN OTHERS  =>                                                                                       
                          -- WRITE(TXT,STRING'("Invalid pma_doublewidth and pma_width selection"));                    
                          -- WRITELINE(OUTPUT,TXT);                                                                    
                                                                                                                     
           END CASE;                                                                                                 
           RETURN res;                                                                                           
       END compute_rprbs_sel_rx;                                                                                     
      
  variable init_rpma_doublewidth_rx_var : std_logic;
  variable init_rpmadwidth_rx_var : std_logic;
  VARIABLE tmp_rcomp_size           :  std_logic_vector(2 DOWNTO 0);
