      init_rclk_2_sel <= mux_select((clk2_mux_select = ("recvd_clk") OR clk2_mux_select = ("recovered clock")), "00", mux_select((clk2_mux_select = ("digital_refclk") OR clk2_mux_select = ("digital reference clock")), "10", mux_select((clk2_mux_select = ("local_refclk") OR clk2_mux_select = ("local reference clock")), "01", mux_select((clk2_mux_select = ("core_clk") OR clk2_mux_select = ("core clk") OR clk2_mux_select = ("core clock")), "11", "ZZ"))));
      init_rclkcmpinsertpad <= mux_select((insert_pad_on_underflow = ("true")), '1', '0');
