      init_rprbsen_rx <= mux_select(((enable_self_test_mode = ("true")) AND (self_test_mode /= ("incremental")) AND (self_test_mode /= ("cjpat")) AND (self_test_mode /= ("crpat"))), '1', '0');
      init_rrcvd_clk_sel <= mux_select((recovered_clk_mux_select = ("recvd_clk") OR recovered_clk_mux_select = ("recovered clock")), "00", mux_select((recovered_clk_mux_select = ("digital_refclk") OR recovered_clk_mux_select = ("digital reference clock")), "01", mux_select((recovered_clk_mux_select = ("local_refclk") OR recovered_clk_mux_select = ("local reference clock")), "10", "ZZ")));
