   -- a1a2sizeout; - used in SONET mode
   PROCESS (rd_out_rxd(8), rd_out_rxd(24), rd_out_rxd(40), rd_out_rxd(56))
VARIABLE  txt : LINE;
 variable i : integer;
   BEGIN
      IF (cram_rpma_doublewidth_rx = '0' AND cram_rdwidth_rx = '1') THEN
 i := 0;
         while ((i <  4) AND (i < 2) ) LOOP
            a1a2sizeout_reg(i) <= rd_out_rxd(8 + 32 * i);
 i := i + 1;
         END LOOP;
      ELSE
         FOR i IN 0 TO 3 LOOP
            a1a2sizeout_reg(i) <= rd_out_rxd(8 + 16 * i);
         END LOOP;
      END IF;
   END PROCESS;
   
   
   -- a1detect; [1:0] - Async from Word align, not going BYTE SERDES
   PROCESS (rd_out_a1a2_k1k2_flag(0), rd_out_a1a2_k1k2_flag(2))
VARIABLE  txt : LINE;
   BEGIN
      FOR i IN 0 TO 1 LOOP
         
         -- a2detect; [0] = detecting A2 on datain[7:0]; [1] = on datain[15:8]
         a1detect_reg(i) <= rd_out_a1a2_k1k2_flag(2 * i);
      END LOOP;
   END PROCESS;
   
   PROCESS (rd_out_a1a2_k1k2_flag(1), rd_out_a1a2_k1k2_flag(3))
VARIABLE  txt : LINE;
   BEGIN
      FOR i IN 0 TO 1 LOOP
         
         -- adetectdeskew;
         a2detect_reg(i) <= rd_out_a1a2_k1k2_flag(1 + 2 * i);
      END LOOP;
   END PROCESS;
   
