   -- ctrldetect; - 8b10b used 
   PROCESS (rd_out_rxd(8), rd_out_rxd(24), rd_out_rxd(40), rd_out_rxd(56))
VARIABLE  txt : LINE;
 variable i : integer;
   BEGIN
      IF (cram_rpma_doublewidth_rx = '0' AND cram_rdwidth_rx = '1') THEN
 i := 0;
         while ((i <  4) AND (i < 2) ) LOOP
            ctrldetect_reg(i) <= rd_out_rxd(8 + 32 * i);
 i := i + 1;
         END LOOP;
      ELSE
         FOR i IN 0 TO 3 LOOP
            ctrldetect_reg(i) <= rd_out_rxd(8 + 16 * i);
         END LOOP;
      END IF;
   END PROCESS;
   
   
   -- dataout; - 40 => [7:0]/[9:0], [23:16]/[25:16], [39:32]/[41:32], [55:48]/[57:48]
         PROCESS                                                             
 VARIABLE BASIC_WIDTH :  integer;                                            
 VARIABLE NUM_OF_BASIC : integer;                                            
 VARIABLE i : integer := 0;                                                  
 VARIABLE j : integer := 0;                                                  
 BEGIN                                                                       
     IF (channel_width mod 10 = 0) THEN                                      
         BASIC_WIDTH := 10;                                                  
     ELSE                                                                    
         BASIC_WIDTH := 8;                                                   
     END IF;                                                                 
                                                                             
     NUM_OF_BASIC := channel_width/BASIC_WIDTH;                              
                                                                             
     WAIT UNTIL rd_out_rxd'EVENT;                                            
     IF (cram_rpma_doublewidth_rx = '0' AND cram_rdwidth_rx = '1') THEN      
         i := 0;                                                             
         WHILE ((i < NUM_OF_BASIC) AND (i < 2)) LOOP                         
             j := 0;                                                         
             WHILE (j < BASIC_WIDTH) LOOP                                    
                 dataout_reg(i * BASIC_WIDTH + j) <= rd_out_rxd(i * 32 + j); 
                 j := j + 1;                                                 
             END LOOP;                                                       
             i := i + 1;                                                     
         END LOOP;                                                           
     ELSE                                                                    
         i := 0;                                                             
         WHILE (i < NUM_OF_BASIC) LOOP                                       
             j := 0;                                                         
             WHILE (j < BASIC_WIDTH) LOOP                                    
                 dataout_reg(i * BASIC_WIDTH + j) <= rd_out_rxd(i * 16 + j); 
                 j := j + 1;                                                 
             END LOOP;                                                       
             i := i + 1;                                                     
         END LOOP;                                                           
     END IF;                                                                 
 END PROCESS;                                                                
   
