LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
USE ieee.std_logic_unsigned.all;
LIBRARY STD;
USE STD.textio.ALL;
USE work.cycloneiv_hssi_components.all;

ENTITY cycloneiv_hssi_cmu_quad_reset IS
   PORT (
      -- Common reset inputs
      -- Common reset CRAMs
      -- CMU reset inputs
      -- CMU reset CRAMs
      -- CMU powerdown inputs
      -- CMU powerdown CRAMs
      -- CMU reset outputs
      -- CMU powerdown outputs
      -- Other outputs
      
      -- Common reset inputs
      entest               : IN STD_LOGIC;		-- Test mode control from Control block
      plniotri             : IN STD_LOGIC;		-- PLL output enable
      npor                 : IN STD_LOGIC;		-- Power on reset
      frzreg               : IN STD_LOGIC;		-- Freeze register during power-up
      pllurst              : IN STD_LOGIC;		-- PLL user reset
      
      -- Common reset CRAMs
      rpllurst             : IN STD_LOGIC;		-- Gating CRAM for PLLURST
      rpowerdown           : IN STD_LOGIC;		-- Quad power down CRAM
      rreset               : IN STD_LOGIC;		-- Quad reset CRAM
      
      -- CMU reset inputs
      rxurstcmu            : IN STD_LOGIC_VECTOR(1 DOWNTO 0);		-- Dynamic signal for CMU[1:0]_RXPMA_RSTB
      
      -- CMU reset CRAMs
      rrxurstcmu           : IN STD_LOGIC_VECTOR(1 DOWNTO 0);		-- Gating CRAM for dynamic signal rxurstcmu
      rrx_cmu_rst          : IN STD_LOGIC_VECTOR(1 DOWNTO 0);		-- TXPLL / RXPLL reset
      
      -- CMU powerdown inputs
      ucmurx_pdb           : IN STD_LOGIC_VECTOR(1 DOWNTO 0);		-- Dynamic signal for CMU[1:0]_RX_PDB
      
      -- CMU powerdown CRAMs
      rclk_pdb             : IN STD_LOGIC_VECTOR(1 DOWNTO 0);
      rcmu_powdnr          : IN STD_LOGIC_VECTOR(1 DOWNTO 0);
      rcmu_cru_pdb         : IN STD_LOGIC_VECTOR(1 DOWNTO 0);
      rcmu_urx_pdb         : IN STD_LOGIC_VECTOR(1 DOWNTO 0);
      rcmu_rx_ib_pdb       : IN STD_LOGIC_VECTOR(1 DOWNTO 0);
      rcmu_powdnt          : IN STD_LOGIC_VECTOR(1 DOWNTO 0);
      rcmu_tx_ob_pdb       : IN STD_LOGIC_VECTOR(1 DOWNTO 0);
      rcmu_tx_cgb_pdb      : IN STD_LOGIC_VECTOR(1 DOWNTO 0);
      rcmu_rx_det_pdb      : IN STD_LOGIC_VECTOR(1 DOWNTO 0);
      
      -- CMU reset outputs
      cmu0_rxpma_rstb      : OUT STD_LOGIC;
      cmu0_txpma_rstb      : OUT STD_LOGIC;
      cmu0_cru_rstb        : OUT STD_LOGIC;
      
      cmu1_rxpma_rstb      : OUT STD_LOGIC;
      cmu1_txpma_rstb      : OUT STD_LOGIC;
      cmu1_cru_rstb        : OUT STD_LOGIC;
      
      -- CMU powerdown outputs
      cmu0_rx_pdb          : OUT STD_LOGIC;
      cmu0_cru_pdb         : OUT STD_LOGIC;
      cmu0_clk_pdb         : OUT STD_LOGIC;
      cmu0_tx_pdb          : OUT STD_LOGIC;
      cmu0_cgb_pdb         : OUT STD_LOGIC;
      cmu0_rx_det_pdb      : OUT STD_LOGIC;
      
      cmu1_rx_pdb          : OUT STD_LOGIC;
      cmu1_cru_pdb         : OUT STD_LOGIC;
      cmu1_clk_pdb         : OUT STD_LOGIC;
      cmu1_tx_pdb          : OUT STD_LOGIC;
      cmu1_cgb_pdb         : OUT STD_LOGIC;
      cmu1_rx_det_pdb      : OUT STD_LOGIC;
      
      -- Other outputs
      mdio_rst             : OUT STD_LOGIC;		-- MDIO reset
      hard_reset           : OUT STD_LOGIC;		-- Output HARD_RESET signal for other MDIO modules
      soft_reset_all_hssi  : OUT STD_LOGIC		-- Quad soft reset output
   );
END cycloneiv_hssi_cmu_quad_reset;

ARCHITECTURE trans OF cycloneiv_hssi_cmu_quad_reset IS
   
   ------------------------------------
   -- Wiring section for Resets
   ------------------------------------
   SIGNAL cmu0_rxpma_rst_hssi : STD_LOGIC;
   SIGNAL cmu1_rxpma_rst_hssi : STD_LOGIC;
   
   ------------------------------------
   -- Wiring section for Powerdowns
   ------------------------------------
   SIGNAL cmu0_cru_pd_hssi    : STD_LOGIC;
   SIGNAL cmu0_rx_pd_hssi     : STD_LOGIC;
   SIGNAL cmu0_tx_pd_hssi     : STD_LOGIC;
   SIGNAL cmu0_cgb_pd_hssi    : STD_LOGIC;
   SIGNAL cmu0_rx_det_pd_hssi : STD_LOGIC;
   
   SIGNAL cmu1_cru_pd_hssi    : STD_LOGIC;
   SIGNAL cmu1_rx_pd_hssi     : STD_LOGIC;
   SIGNAL cmu1_tx_pd_hssi     : STD_LOGIC;
   SIGNAL cmu1_cgb_pd_hssi    : STD_LOGIC;
   SIGNAL cmu1_rx_det_pd_hssi : STD_LOGIC;
   
   -- Declare intermediate signals for referenced outputs
   SIGNAL hard_reset_xhdl0    : STD_LOGIC;
BEGIN
   -- Drive referenced outputs
   hard_reset <= hard_reset_xhdl0;
   
   ------------------------------------
   -- Other reset outputs
   ------------------------------------
   -- SP update 10/17/07 - enpll term removed from hard_reset
   -- assign hard_reset = ~(plniotri & ~entest & npor & (enpll | rnenbpin) & (~pllurst | ~rpllurst));
   hard_reset_xhdl0 <= NOT((plniotri AND NOT(entest) AND npor AND (NOT(pllurst) OR NOT(rpllurst))));
   soft_reset_all_hssi <= frzreg OR rpowerdown OR rreset;
   mdio_rst <= NOT((plniotri AND NOT(entest) AND npor));
   
   ------------------------------------
   -- CMU reset internal signals
   ------------------------------------
   cmu0_rxpma_rst_hssi <= (rxurstcmu(0) AND rrxurstcmu(0)) OR rreset;
   cmu1_rxpma_rst_hssi <= (rxurstcmu(1) AND rrxurstcmu(1)) OR rreset;
   
   ------------------------------------
   -- CMU reset outputs
   ------------------------------------
   cmu0_rxpma_rstb <= NOT((cmu0_rxpma_rst_hssi OR hard_reset_xhdl0));
   cmu0_txpma_rstb <= NOT((hard_reset_xhdl0 OR rreset));
   cmu0_cru_rstb <= NOT((hard_reset_xhdl0 OR rreset OR rrx_cmu_rst(0)));
   
   cmu1_rxpma_rstb <= NOT((cmu1_rxpma_rst_hssi OR hard_reset_xhdl0));
   cmu1_txpma_rstb <= NOT((hard_reset_xhdl0 OR rreset));
   cmu1_cru_rstb <= NOT((hard_reset_xhdl0 OR rreset OR rrx_cmu_rst(1)));
   
   ------------------------------------
   -- powerdown internal signals
   ------------------------------------
   cmu0_cru_pd_hssi <= rpowerdown OR rcmu_powdnr(0) OR NOT((rcmu_cru_pdb(0)));
   cmu0_rx_pd_hssi <= rpowerdown OR rcmu_powdnr(0) OR NOT((ucmurx_pdb(0) OR NOT((rcmu_urx_pdb(0))))) OR NOT((rcmu_rx_ib_pdb(0)));
   cmu0_tx_pd_hssi <= rpowerdown OR rcmu_powdnt(0) OR NOT((rcmu_tx_ob_pdb(0)));
   cmu0_cgb_pd_hssi <= rpowerdown OR rcmu_powdnt(0) OR NOT((rcmu_tx_cgb_pdb(0)));
   cmu0_rx_det_pd_hssi <= rpowerdown OR rcmu_powdnt(0) OR NOT((rcmu_rx_det_pdb(0)));
   
   cmu1_cru_pd_hssi <= rpowerdown OR rcmu_powdnr(1) OR NOT((rcmu_cru_pdb(1)));
   cmu1_rx_pd_hssi <= rpowerdown OR rcmu_powdnr(1) OR NOT((ucmurx_pdb(1) OR NOT((rcmu_urx_pdb(1))))) OR NOT((rcmu_rx_ib_pdb(1)));
   cmu1_tx_pd_hssi <= rpowerdown OR rcmu_powdnt(1) OR NOT((rcmu_tx_ob_pdb(1)));
   cmu1_cgb_pd_hssi <= rpowerdown OR rcmu_powdnt(1) OR NOT((rcmu_tx_cgb_pdb(1)));
   cmu1_rx_det_pd_hssi <= rpowerdown OR rcmu_powdnt(1) OR NOT((rcmu_rx_det_pdb(1)));
   
   ------------------------------------
   -- powerdown outputs
   ------------------------------------
   cmu0_clk_pdb <= rclk_pdb(0);
   cmu0_cru_pdb <= NOT((hard_reset_xhdl0 OR cmu0_cru_pd_hssi));
   cmu0_rx_pdb <= NOT((hard_reset_xhdl0 OR cmu0_rx_pd_hssi));
   cmu0_tx_pdb <= NOT((hard_reset_xhdl0 OR cmu0_tx_pd_hssi));
   cmu0_cgb_pdb <= NOT((hard_reset_xhdl0 OR cmu0_cgb_pd_hssi));
   cmu0_rx_det_pdb <= NOT((hard_reset_xhdl0 OR cmu0_rx_det_pd_hssi));
   
   cmu1_clk_pdb <= rclk_pdb(1);
   cmu1_cru_pdb <= NOT((hard_reset_xhdl0 OR cmu1_cru_pd_hssi));
   cmu1_rx_pdb <= NOT((hard_reset_xhdl0 OR cmu1_rx_pd_hssi));
   cmu1_tx_pdb <= NOT((hard_reset_xhdl0 OR cmu1_tx_pd_hssi));
   cmu1_cgb_pdb <= NOT((hard_reset_xhdl0 OR cmu1_cgb_pd_hssi));
   cmu1_rx_det_pdb <= NOT((hard_reset_xhdl0 OR cmu1_rx_det_pd_hssi));
   
END trans;



LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
USE ieee.std_logic_unsigned.all;
LIBRARY STD;
USE STD.textio.ALL;
USE work.cycloneiv_hssi_components.all;

ENTITY cycloneiv_hssi_cmu_chnl_reset IS
   PORT (
      
      -- Inputs from QUAD reset module		  
      hard_reset           : IN STD_LOGIC;		-- hardreset signal
      soft_reset_all_hssi  : IN STD_LOGIC;		-- soft reset for all channel
      rreset               : IN STD_LOGIC;		-- Quad reset CRAM
      rpowerdown           : IN STD_LOGIC;		-- Quad power down CRAM
      
      -- Channel Reset inputs
      rxurstpma            : IN STD_LOGIC;		-- RX PMA user reset
      rxurstpcs            : IN STD_LOGIC;		-- RX PCS user reset
      txurstpcs            : IN STD_LOGIC;		-- TX PCS user reset
      
      -- Channel Reset CRAMs
      rpowdnr              : IN STD_LOGIC;		-- RX channel power down CRAM
      rpowdnt              : IN STD_LOGIC;		-- TX channel power down CRAM
      rrxurstpcs           : IN STD_LOGIC;		-- Gating CRAM for RXURSTPCS
      rtxurstpcs           : IN STD_LOGIC;		-- Gating CRAM for TXURSTPCS
      rrxurstpma           : IN STD_LOGIC;		-- Gating CRAM for RXURSTPMA
      rrx_cru_rst          : IN STD_LOGIC;		-- Channel RX PLL reset CRAMs
      radce_rst            : IN STD_LOGIC;		-- Channel Adaptive block reset CRAMs
      
      -- Powerdown inputs
      urx_pdb              : IN STD_LOGIC;		-- RX user powerdown signal
      
      -- Powerdown CRAMs
      rurx_pdb             : IN STD_LOGIC;		-- Gating CRAM for urx_pdb signals
      radce_pdb            : IN STD_LOGIC;		-- Adaptive block powerdown CRAMs
      rrx_ib_pdb           : IN STD_LOGIC;		-- RX Input buffer and PLL powerdown CRAMs
      rtx_ob_pdb           : IN STD_LOGIC;		-- TX Output buffer powerdown CRAMs
      rtx_cgb_pdb          : IN STD_LOGIC;		-- TX clock generator powerdown CRAMs
      rrx_cru_pdb          : IN STD_LOGIC;		-- RX PLL powerdown CRAMs
      
      -- PIPE Inputs
      rtx_pipe_en          : IN STD_LOGIC;		-- PIPE enable CRAMs
      p0_state             : IN STD_LOGIC;		-- PIPE P0 state indicators
      p0s_state            : IN STD_LOGIC;		-- PIPE P0S state indicators
      p2_state             : IN STD_LOGIC;		-- PIPE P2 state indicators
      
      -- Channel Reset outputs
      rxpma_rstb           : OUT STD_LOGIC;		-- RX PMA resets (powerdown)
      txpma_rstb           : OUT STD_LOGIC;		-- TX PMA resets (powerdown)
      rxpcs_rst            : OUT STD_LOGIC;		-- RX PCS resets 
      txpcs_rst            : OUT STD_LOGIC;		-- TX PCS resets
      cru_rstb             : OUT STD_LOGIC;		-- RX PLL resets
      adce_rstb            : OUT STD_LOGIC;		-- Adaptive block resets
      
      -- Channel Powerdown outputs
      adce_pdb             : OUT STD_LOGIC;		-- Adaptive block powerdown
      cru_pdb              : OUT STD_LOGIC;		-- RX PLL powerdown
      rx_pdb               : OUT STD_LOGIC;		-- RX powerdown
      tx_pdb               : OUT STD_LOGIC;		-- TX driver powerdown
      cgb_pdb              : OUT STD_LOGIC;		-- Clock generator powerdown
      rx_det_pdb           : OUT STD_LOGIC		-- Receiver detector powerdown
   );
END cycloneiv_hssi_cmu_chnl_reset;

ARCHITECTURE trans OF cycloneiv_hssi_cmu_chnl_reset IS
   
   -- Wiring section for Resets
   SIGNAL rxpcsrst_hssi    : STD_LOGIC;
   SIGNAL txpcsrst_hssi    : STD_LOGIC;
   SIGNAL rxpmarst_hssi    : STD_LOGIC;
   
   -- Wiring section for Powerdowns
   SIGNAL adce_pd_hssi     : STD_LOGIC;
   SIGNAL cru_pd_hssi      : STD_LOGIC;
   SIGNAL rx_pd_hssi       : STD_LOGIC;
   SIGNAL tx_pd_hssi       : STD_LOGIC;
   SIGNAL cgb_pd_hssi      : STD_LOGIC;
   SIGNAL rx_det_pd_hssi   : STD_LOGIC;
   
   -- Declare intermediate signals for referenced outputs
   SIGNAL rxpma_rstb_xhdl0 : STD_LOGIC;
BEGIN
   -- Drive referenced outputs
   rxpma_rstb <= rxpma_rstb_xhdl0;
   
   -- reset internal signals
   rxpcsrst_hssi <= (rxurstpcs AND rrxurstpcs) OR rpowdnr;
   txpcsrst_hssi <= (txurstpcs AND rtxurstpcs) OR rpowdnt;
   rxpmarst_hssi <= (rxurstpma AND rrxurstpma) OR rreset;
   
   -- reset outputs
   rxpma_rstb_xhdl0 <= NOT((rxpmarst_hssi OR hard_reset));
   txpma_rstb <= NOT((rreset OR hard_reset));
   cru_rstb <= NOT((hard_reset OR rreset OR rrx_cru_rst));
   adce_rstb <= rxpma_rstb_xhdl0 AND NOT((radce_rst));
   
   rxpcs_rst <= rxpcsrst_hssi OR hard_reset OR soft_reset_all_hssi;
   txpcs_rst <= txpcsrst_hssi OR hard_reset OR soft_reset_all_hssi;
   
   -- powerdown internal signals
   adce_pd_hssi <= NOT((radce_pdb)) OR rpowdnr OR rpowerdown;
   cru_pd_hssi <= NOT((rrx_cru_pdb)) OR rpowdnr OR rpowerdown;
   rx_pd_hssi <= NOT((urx_pdb OR NOT((rurx_pdb)))) OR NOT((rrx_ib_pdb)) OR rpowdnr OR rpowerdown;
   tx_pd_hssi <= NOT((rtx_ob_pdb)) OR rpowdnt OR rpowerdown;
   cgb_pd_hssi <= NOT((rtx_cgb_pdb)) OR rpowdnt OR rpowerdown;
   rx_det_pd_hssi <= (rtx_pipe_en AND (p0_state OR p0s_state OR p2_state)) OR rpowdnt OR rpowerdown;
   
   -- powerdown outputs
   adce_pdb <= NOT((adce_pd_hssi OR hard_reset));
   cru_pdb <= NOT((cru_pd_hssi OR hard_reset));
   rx_pdb <= NOT((rx_pd_hssi OR hard_reset));
   tx_pdb <= NOT((tx_pd_hssi OR hard_reset));
   cgb_pdb <= NOT((cgb_pd_hssi OR hard_reset));
   rx_det_pdb <= NOT((rx_det_pd_hssi OR hard_reset));
   
END trans;




LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
USE ieee.std_logic_unsigned.all;
LIBRARY STD;
USE STD.textio.ALL;
USE work.cycloneiv_hssi_components.all;

ENTITY cycloneiv_hssi_cmu_auto_speed_neg IS
   GENERIC (
      
      -- Clocks and Resets
      WAIT_RATE_CHANGE           : INTEGER := 0;
      WAIT_FOR_PHFIFO            : INTEGER := 1;
      DISABLE_PC_BYTE            : INTEGER := 2;
      SET_CONFIG_SEL             : INTEGER := 3;
      WAIT_GEN2NGEN1_CHANGE      : INTEGER := 4;
      WAIT_PMA_DONE_CNTR         : INTEGER := 5;
      DEASSERT_PC_PTR_RESET      : INTEGER := 6;
      WAIT_DEASSERT_RST_CNTR     : INTEGER := 7;
      ENABLE_PC_BYTE             : INTEGER := 8;
      WAIT_ENABLE_CNTR           : INTEGER := 9;
      SPEED_CHANGE_DONE          : INTEGER := 10
   );
   PORT (
      refclk                     : IN STD_LOGIC;
      rxpcs_rst_int              : IN STD_LOGIC;
      
      -- Input from LTSSM (sideband).  high is gen2, low is gen1.
      rate                       : IN STD_LOGIC;
      -- Input from PMA
      -- PMA indication for change in frequency.  transistions one cycle before actually frequency change.  high is gen2, low is gen1.
      gen2ngen1                  : IN STD_LOGIC;
      
      -- Bundle Mode Inputs for config_sel
      config_sel_centrl          : IN STD_LOGIC;
      config_sel_quad_up         : IN STD_LOGIC;
      config_sel_quad_down       : IN STD_LOGIC;
      
      -- MDIO
      rindv_rx                   : IN STD_LOGIC;
      rmaster_rx                 : IN STD_LOGIC;
      rmaster_up_rx              : IN STD_LOGIC;
      rauto_speed_ena            : IN STD_LOGIC;
      singleorbundle             : IN STD_LOGIC;
      rphfifo_regmode_rx         : IN STD_LOGIC;
      rpma_done_count            : IN STD_LOGIC_VECTOR(17 DOWNTO 0);
      rauto_deassert_pc_rst_cnt  : IN STD_LOGIC_VECTOR(3 DOWNTO 0);
      rauto_pc_en_cnt            : IN STD_LOGIC_VECTOR(4 DOWNTO 0);
      rwait_for_phfifo_cnt       : IN STD_LOGIC_VECTOR(5 DOWNTO 0);
      
      -- control signal output for bundle mode  high is gen2, low is gen1.
      config_sel                 : OUT STD_LOGIC;
      
      -- PMA rate change control
      pcie_switch                : OUT STD_LOGIC;
      
      -- RX Phase Comp
      -- Handshake signal to PIPE interface to assert PhyStatus
      speed_change               : OUT STD_LOGIC;
      
      -- Phase Comp and byte ser/deser control signals
      dis_pc_byte                : OUT STD_LOGIC;
      reset_pc_ptrs              : OUT STD_LOGIC;
      cs                         : OUT STD_LOGIC_VECTOR(3 DOWNTO 0)
   );
END cycloneiv_hssi_cmu_auto_speed_neg;

ARCHITECTURE trans OF cycloneiv_hssi_cmu_auto_speed_neg IS
   
   SIGNAL set_config_sel_reg : STD_LOGIC;
   SIGNAL next_state         : STD_LOGIC_VECTOR(3 DOWNTO 0);
   SIGNAL rate_int_reg       : STD_LOGIC;
   SIGNAL gen2ngen1_del      : STD_LOGIC;
   SIGNAL freq_switch        : STD_LOGIC;
   SIGNAL reset_count        : STD_LOGIC;
   SIGNAL count_pma_done     : STD_LOGIC;
   SIGNAL count_deassert_rst : STD_LOGIC;
   SIGNAL count_enable_pc    : STD_LOGIC;
   SIGNAL rate_sync1_reg     : STD_LOGIC;
   SIGNAL rate_sync2_reg     : STD_LOGIC;
   SIGNAL counter            : STD_LOGIC_VECTOR(18 DOWNTO 0);
   SIGNAL counter_done       : STD_LOGIC;
   SIGNAL count_phfifo       : STD_LOGIC;
   
   SIGNAL rate_edge          : STD_LOGIC;
   -- X-HDL generated signals

   SIGNAL xhdl2 : STD_LOGIC;
   SIGNAL xhdl3 : STD_LOGIC;
   SIGNAL xhdl4 : STD_LOGIC;
   SIGNAL xhdl5 : STD_LOGIC;
   SIGNAL xhdl6 : STD_LOGIC;
   
   -- Declare intermediate signals for referenced outputs
   SIGNAL config_sel_xhdl0   : STD_LOGIC;
   SIGNAL cs_xhdl1           : STD_LOGIC_VECTOR(3 DOWNTO 0);
BEGIN
   -- Drive referenced outputs
   config_sel <= config_sel_xhdl0;
   cs <= cs_xhdl1;
   
   --============================================================================
   --  FSM states
   --
   --============================================================================
   
   --============================================================================
   --  Multi-use Counter with *2 done flag capablility 
   --
   --============================================================================
   
   
   xhdl2 <= '1' WHEN (((counter(18 DOWNTO 1) = rpma_done_count(17 DOWNTO 0)) AND (gen2ngen1 = '1') AND (counter(0) = '1')) OR ((counter(17 DOWNTO 0) = rpma_done_count(17 DOWNTO 0)) AND (NOT(gen2ngen1) = '1'))) ELSE
   '0';
   xhdl3 <= '1' WHEN (((counter(4 DOWNTO 1) = rauto_deassert_pc_rst_cnt(3 DOWNTO 0)) AND (gen2ngen1 = '1') AND (counter(0) = '1')) OR ((counter(3 DOWNTO 0) = rauto_deassert_pc_rst_cnt(3 DOWNTO 0)) AND (NOT(gen2ngen1) = '1'))) ELSE
   '0';
   xhdl4 <= '1' WHEN (((counter(5 DOWNTO 1) = rauto_pc_en_cnt(4 DOWNTO 0)) AND (gen2ngen1 = '1') AND (counter(0) = '1')) OR ((counter(4 DOWNTO 0) = rauto_pc_en_cnt(4 DOWNTO 0)) AND (NOT(gen2ngen1) = '1'))) ELSE
   '0';
   xhdl5 <= '1' WHEN (((counter(6 DOWNTO 1) = rwait_for_phfifo_cnt(5 DOWNTO 0)) AND (gen2ngen1 = '1') AND (counter(0) = '1')) OR ((counter(5 DOWNTO 0) = rwait_for_phfifo_cnt(5 DOWNTO 0)) AND (NOT(gen2ngen1) = '1'))) ELSE
   '0';
   PROCESS (refclk, rxpcs_rst_int)
VARIABLE  txt : LINE;
   BEGIN
      IF (rxpcs_rst_int = '1') THEN
         counter <=  TRANSPORT "0000000000000000000" AFTER 1* 1 ps;
         counter_done <=  TRANSPORT '0' AFTER 1* 1 ps;
      ELSIF (refclk'EVENT AND refclk = '1') THEN
         IF (reset_count = '1') THEN
            counter <=  TRANSPORT "0000000000000000000" AFTER 1* 1 ps;
            counter_done <=  TRANSPORT '0' AFTER 1* 1 ps;
         ELSE
            counter <=  TRANSPORT counter + "0000000000000000001" AFTER 1* 1 ps;
            IF ((NOT(counter_done)) = '1') THEN
               IF (count_pma_done = '1') THEN
                  counter_done <=  TRANSPORT xhdl2 AFTER 1* 1 ps;
               ELSIF (count_deassert_rst = '1') THEN
                  counter_done <=  TRANSPORT xhdl3 AFTER 1* 1 ps;
               ELSIF (count_enable_pc = '1') THEN
                  counter_done <=  TRANSPORT xhdl4 AFTER 1* 1 ps;
               ELSIF (count_phfifo = '1') THEN
                  counter_done <=  TRANSPORT xhdl5 AFTER 1* 1 ps;
               END IF;
            END IF;
         END IF;
      END IF;
   END PROCESS;
   
   -- if (~count_pma_done)
   -- always @ (posedge clk or posedge reset)
   
   --============================================================================
   --  Control signal output logic
   --
   --============================================================================
   
   pcie_switch <= config_sel_xhdl0 WHEN (rindv_rx = '1') ELSE
                  config_sel_centrl WHEN (rmaster_rx = '1') ELSE
                  config_sel_quad_up WHEN (rmaster_up_rx = '1') ELSE
                  config_sel_quad_down;
   
   --============================================================================
   --  Synchronization, Input & Output Logic
   --
   --============================================================================
   
   PROCESS (refclk, rxpcs_rst_int)
VARIABLE  txt : LINE;
   BEGIN
      IF (rxpcs_rst_int = '1') THEN
         rate_sync1_reg <=  TRANSPORT '0' AFTER 1* 1 ps;
         rate_sync2_reg <=  TRANSPORT '0' AFTER 1* 1 ps;
         rate_int_reg <=  TRANSPORT '0' AFTER 1* 1 ps;
      ELSIF (refclk'EVENT AND refclk = '1') THEN
         rate_sync1_reg <=  TRANSPORT rate AFTER 1* 1 ps;
         rate_sync2_reg <=  TRANSPORT rate_sync1_reg AFTER 1* 1 ps;
         rate_int_reg <=  TRANSPORT rate_sync2_reg AFTER 1* 1 ps;
      END IF;
   END PROCESS;
   
   -- always @ (posedge refclk or posedge reset)
   
   rate_edge <= '1' WHEN (rate_sync2_reg /= rate_int_reg) ELSE
                '0';
   
   -- convert gen2ngen1 to freq_switch
   xhdl6 <= '1' WHEN (gen2ngen1_del /= gen2ngen1) ELSE
                '0';
   PROCESS (refclk, rxpcs_rst_int)
VARIABLE  txt : LINE;
   BEGIN
      IF (rxpcs_rst_int = '1') THEN
         gen2ngen1_del <=  TRANSPORT '0' AFTER 1* 1 ps;
         freq_switch <=  TRANSPORT '0' AFTER 1* 1 ps;
      ELSIF (refclk'EVENT AND refclk = '1') THEN
         gen2ngen1_del <=  TRANSPORT gen2ngen1 AFTER 1* 1 ps;
         freq_switch <=  TRANSPORT xhdl6 AFTER 1* 1 ps;
      END IF;
   END PROCESS;
   
   -- always @ (posedge refclk or posedge reset)
   
   -- config_sel
   PROCESS (refclk, rxpcs_rst_int)
VARIABLE  txt : LINE;
   BEGIN
      IF (rxpcs_rst_int = '1') THEN
         config_sel_xhdl0 <=  TRANSPORT '0' AFTER 1* 1 ps;
      ELSIF (refclk'EVENT AND refclk = '1') THEN
         IF (set_config_sel_reg = '1') THEN
            config_sel_xhdl0 <=  TRANSPORT rate_sync2_reg AFTER 1* 1 ps;
         END IF;
      END IF;
   END PROCESS;
   
   -- always @ (posedge refclk or posedge reset)
   
   --============================================================================
   --  Auto Speed Negotiation State Machine
   --
   --============================================================================
   --   
   
   PROCESS (refclk, rxpcs_rst_int)
VARIABLE  txt : LINE;
   BEGIN
      IF (rxpcs_rst_int = '1') THEN
         cs_xhdl1 <=  TRANSPORT int2bin(WAIT_RATE_CHANGE, 4) AFTER 1* 1 ps;
      ELSIF (refclk'EVENT AND refclk = '1') THEN
         cs_xhdl1 <=  TRANSPORT next_state AFTER 1* 1 ps;
      END IF;
   END PROCESS;
   
   -- always @ (posedge refclk or posedge reset)
   
   PROCESS (cs_xhdl1, rate_edge, rauto_speed_ena, rphfifo_regmode_rx, freq_switch, counter_done, singleorbundle)
VARIABLE  txt : LINE;
   BEGIN
--      IF (cs_xhdl1'EVENT) THEN
         
         next_state <= cs_xhdl1;
         dis_pc_byte <= '0';
         reset_pc_ptrs <= '0';
         set_config_sel_reg <= '0';
         speed_change <= '0';
         reset_count <= '1';
         count_pma_done <= '0';
         count_deassert_rst <= '0';
         count_enable_pc <= '0';
         
         count_phfifo <= '0';
         
         CASE cs_xhdl1 IS
            
            -- case: WAIT_RATE_CHANGE
            
            WHEN "0000" =>
               IF ((rate_edge AND rauto_speed_ena AND singleorbundle) = '1') THEN
                  IF ((NOT(rphfifo_regmode_rx)) = '1') THEN
                     next_state <= int2bin(WAIT_FOR_PHFIFO, 4);
                  ELSE
                     next_state <= int2bin(SET_CONFIG_SEL, 4);
                  END IF;
               END IF;
            
            -- case: WAIT_FOR_PHFIFO

            WHEN "0001" =>
               reset_count <= '0';
               count_phfifo <= '1';
               IF (counter_done = '1') THEN
                  next_state <= int2bin(DISABLE_PC_BYTE, 4);
               END IF;
            
            -- case: DISABLE_PC_BYTE
            
            WHEN "0010" =>
               dis_pc_byte <= '1';
               reset_pc_ptrs <= '1';
               speed_change <= '1';
               next_state <= int2bin(SET_CONFIG_SEL, 4);
            
            -- case: SET_CONFIG_SEL
            
            WHEN "0011" =>
               dis_pc_byte <= '1';
               reset_pc_ptrs <= '1';
               set_config_sel_reg <= '1';
               speed_change <= '1';
               next_state <= int2bin(WAIT_GEN2NGEN1_CHANGE, 4);
            
            -- case: WAIT_GEN2NGEN1_CHANGE
            
            WHEN "0100" =>
               dis_pc_byte <= '1';
               reset_pc_ptrs <= '1';
               speed_change <= '1';
               IF (freq_switch = '1') THEN
                  next_state <= int2bin(WAIT_PMA_DONE_CNTR, 4);
               END IF;
            
            -- case: WAIT_PMA_DONE_CNTR
            
            WHEN "0101" =>
               dis_pc_byte <= '1';
               reset_pc_ptrs <= '1';
               speed_change <= '1';
               reset_count <= '0';
               count_pma_done <= '1';
               IF (counter_done = '1') THEN
                  IF ((NOT(rphfifo_regmode_rx)) = '1') THEN
                     next_state <= int2bin(DEASSERT_PC_PTR_RESET, 4);
                  ELSE
                     next_state <= int2bin(SPEED_CHANGE_DONE, 4);
                  END IF;
               END IF;
            
 	  -- case DEASSERT_PC_PTR_RESET

           WHEN "0110" =>
               dis_pc_byte <= '1';
               speed_change <= '1';
               next_state <= int2bin(WAIT_DEASSERT_RST_CNTR, 4);
            
            -- case: WAIT_DEASSERT_RST_CNTR
            
            WHEN "0111" =>
               dis_pc_byte <= '1';
               speed_change <= '1';
               reset_count <= '0';
               count_deassert_rst <= '1';
               IF (counter_done = '1') THEN
                  next_state <= int2bin(ENABLE_PC_BYTE, 4);
               END IF;
            
            -- case: ENABLE_PC_BYTE:

            WHEN "1000" =>
               speed_change <= '1';
               next_state <= int2bin(WAIT_ENABLE_CNTR, 4);
            
            -- case: WAIT_ENABLE_CNTR:  
    
            WHEN "1001" =>
               speed_change <= '1';
               reset_count <= '0';
               count_enable_pc <= '1';
               IF (counter_done = '1') THEN
                  next_state <= int2bin(SPEED_CHANGE_DONE, 4);
               END IF;
            
            -- case: SPEED_CHANGE_DONE:

            WHEN "1010" =>
               next_state <= int2bin(WAIT_RATE_CHANGE, 4);
            
            -- case: default
            
            WHEN OTHERS =>		-- case(cs)
               dis_pc_byte <= '0';
               reset_pc_ptrs <= '0';
               set_config_sel_reg <= '0';
               speed_change <= '0';
               reset_count <= '1';
               count_pma_done <= '0';
               count_deassert_rst <= '0';
               count_enable_pc <= '0';
               next_state <= int2bin(WAIT_RATE_CHANGE, 4);
         END CASE;
--      END IF;
   END PROCESS;
   
   
END trans;



-- always @ (cs or rate_edge or rauto_speed_ena or rphfifo_regmode_rx or freq_switch or counter_done)


-- auto_speed_neg_centrl
LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
USE ieee.std_logic_unsigned.all;
LIBRARY STD;
USE STD.textio.ALL;
USE work.cycloneiv_hssi_components.all;

ENTITY cycloneiv_hssi_cmu_clk_gating IS
    PORT (
        
        select_n   : IN STD_LOGIC;
        clk1       : IN STD_LOGIC;
        clk2       : IN STD_LOGIC;
        clk1out_n  : OUT STD_LOGIC;
        clk2out_n  : OUT STD_LOGIC
    );
END ENTITY cycloneiv_hssi_cmu_clk_gating;

ARCHITECTURE trans OF cycloneiv_hssi_cmu_clk_gating IS
BEGIN
    
    clk1out_n <= NOT((select_n OR clk1));
    clk2out_n <= NOT((NOT(select_n) OR clk2));
    
END ARCHITECTURE trans;

-- centrl_clk_gating


LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
USE ieee.std_logic_unsigned.all;
LIBRARY STD;
USE STD.textio.ALL;
USE work.cycloneiv_hssi_components.all;

ENTITY cycloneiv_hssi_cmu_clk_ctl IS
   PORT (
      
      pclk_pma           : IN STD_LOGIC;		-- x4 PCLK from PMA CMU
      refclk_dig         : IN STD_LOGIC;		-- External digital clock
      mdc                : IN STD_LOGIC;		-- MDIO input clock
      ser_clk            : IN STD_LOGIC;		-- Serial clock
      ser_mode           : IN STD_LOGIC;		-- Serial shift configuration mode
      scan_mode          : IN STD_LOGIC;		-- Scan mode
      scan_clk           : IN STD_LOGIC;		-- Scan mode
      rfreerun_centrl    : IN STD_LOGIC;		-- REFCLK_OUT free running enable CRAM
      rcentrl_clk_sel    : IN STD_LOGIC;		-- REFCLK_PMA global clock selection CRAM
      rrefclk_out_div2   : IN STD_LOGIC;		-- REFCLK_OUT divide by 2 enable CRAM
      hard_reset         : IN STD_LOGIC;		-- Hard reset input
      txrst              : IN STD_LOGIC;
      
      refclk_pma_out     : OUT STD_LOGIC;		-- Global TX PCS clock
      mdc_b              : OUT STD_LOGIC;		-- Configuration output clock
      refclk_out         : OUT STD_LOGIC;		-- REFCLK_OUT output clk
      rauto_speed_ena    : IN STD_LOGIC;
      rfreq_sel          : IN STD_LOGIC;
      gen2ngen1_bundle   : IN STD_LOGIC
   );
END cycloneiv_hssi_cmu_clk_ctl;

ARCHITECTURE trans OF cycloneiv_hssi_cmu_clk_ctl IS
   
   COMPONENT cycloneiv_hssi_cmu_clk_gating    
   PORT (
        
        select_n   : IN STD_LOGIC;
        clk1       : IN STD_LOGIC;
        clk2       : IN STD_LOGIC;
        clk1out_n  : OUT STD_LOGIC;
        clk2out_n  : OUT STD_LOGIC
    );
   END COMPONENT;

   SIGNAL refclk_pma_int       : STD_LOGIC;
   SIGNAL refclk_out_div2_inv  : STD_LOGIC;
   SIGNAL hard_reset_n         : STD_LOGIC;
   SIGNAL refclk_out_div2      : STD_LOGIC := '1';
   
   SIGNAL gen2ngen1_local_sync : STD_LOGIC;
   SIGNAL dynamic_div2ndiv1    : STD_LOGIC;
  
   SIGNAL clk1out_n    : STD_LOGIC;
   SIGNAL clk2out_n    : STD_LOGIC;
       
   -- Declare intermediate signals for referenced outputs
   SIGNAL refclk_pma_out_xhdl1 : STD_LOGIC;
   SIGNAL refclk_out_xhdl0     : STD_LOGIC;
BEGIN
   -- Drive referenced outputs
   refclk_pma_out <= refclk_pma_out_xhdl1;
   refclk_out <= refclk_out_xhdl0;
   
     
   -- The following assignments need to be replaced with clock buffers
   -- instantiation when the technology is identified later
   
   -- refclk_pma clock selection
   refclk_pma_int <= refclk_dig WHEN (rcentrl_clk_sel = '1') ELSE
                     pclk_pma;
   refclk_pma_out_xhdl1 <= scan_clk WHEN (scan_mode = '1') ELSE
                           refclk_pma_int;
   
   -- refclk_out logic
   -- This register is used to generate divided by two clock. Div by 2 clock starts off high after reset
   refclk_out_div2_inv <= (NOT(refclk_out_div2) OR NOT(gen2ngen1_local_sync)) WHEN ((rauto_speed_ena AND NOT(rfreq_sel)) = '1') ELSE
                          NOT(refclk_out_div2);
   
   hard_reset_n <= '1' WHEN (rfreerun_centrl = '1') ELSE
                   NOT(hard_reset);
   
   PROCESS (hard_reset_n, refclk_pma_out_xhdl1)
VARIABLE  txt : LINE;
   BEGIN
      IF ((NOT(hard_reset_n)) = '1') THEN
         refclk_out_div2 <= '1';
      ELSIF (refclk_pma_out_xhdl1'EVENT AND refclk_pma_out_xhdl1 = '1') THEN
         refclk_out_div2 <= refclk_out_div2_inv;
      END IF;
   END PROCESS;
   
   PROCESS (txrst, refclk_pma_out_xhdl1)
VARIABLE  txt : LINE;
   BEGIN
      IF (txrst = '1') THEN
         gen2ngen1_local_sync <=  TRANSPORT '0' AFTER 1* 1 ps;
      ELSIF (refclk_pma_out_xhdl1'EVENT AND refclk_pma_out_xhdl1 = '1') THEN
         gen2ngen1_local_sync <=  TRANSPORT gen2ngen1_bundle AFTER 1* 1 ps;
      END IF;
   END PROCESS;
   
   dynamic_div2ndiv1 <= rrefclk_out_div2 OR (gen2ngen1_local_sync AND rauto_speed_ena AND NOT(rfreq_sel));
   
   
   
   centrl_clk_gating : cycloneiv_hssi_cmu_clk_gating
      PORT MAP (
        select_n   => dynamic_div2ndiv1,
        clk1       => refclk_pma_out_xhdl1,
        clk2       => refclk_out_div2,
        clk1out_n  => clk1out_n,
        clk2out_n  => clk2out_n
      );
      
   refclk_out_xhdl0 <= NOT (clk1out_n OR clk2out_n);
   
   -- mdc_b clock logic
   mdc_b <= refclk_pma_out_xhdl1 WHEN ((scan_mode = '1') AND (ser_mode = '1')) ELSE
            refclk_pma_out_xhdl1 WHEN ((scan_mode = '1') AND (ser_mode = '0')) ELSE
            ser_clk WHEN ((scan_mode = '0') AND (ser_mode = '1')) ELSE
            mdc WHEN ((scan_mode = '0') AND (ser_mode = '0')) ELSE
            mdc;
   
END trans;



-- centrl_clk_ctl


LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
USE ieee.std_logic_unsigned.all;
LIBRARY STD;
USE STD.textio.ALL;
USE work.cycloneiv_hssi_components.all;

ENTITY cycloneiv_hssi_cmu_rx_ctrl IS
   PORT (
      
      -- =======
      -- inputs
      -- =======
      soft_reset          : IN STD_LOGIC;
      clk_2               : IN STD_LOGIC;
      rx_rd_clk           : IN STD_LOGIC;		-- This replaces PLD_RX_CLK
      rx_wr_clk           : IN STD_LOGIC;		-- divided by 1 or 2 write clock.
      scan_mode           : IN STD_LOGIC;		-- scan enable
      rrxfifo_urst_en     : IN STD_LOGIC;		-- Enable rxfifo_urst
      rxfifo_urst         : IN STD_LOGIC;		-- User reset exclusive to rx_ctrl & below
      rrxphfifopldctl_en  : IN STD_LOGIC;		-- CRAM to enable PLD controlled write/read enable
      pld_wr_dis          : IN STD_LOGIC;		-- PLD write disable
      pld_re              : IN STD_LOGIC;		-- PLD read eanble
      dis_pc_byte         : IN STD_LOGIC;
      -- New MDIO for new bundling scheme and new PCIE features like autospeed
      rauto_speed_ena     : IN STD_LOGIC;
      
      -- =======
      -- outputs
      -- =======
      rx_we_out           : OUT STD_LOGIC;
      wr_enable_out       : OUT STD_LOGIC;
      rd_enable_out       : OUT STD_LOGIC
   );
END cycloneiv_hssi_cmu_rx_ctrl;

ARCHITECTURE trans OF cycloneiv_hssi_cmu_rx_ctrl IS
   
   -- reset signals
   SIGNAL local_soft_reset        : STD_LOGIC;		-- OR of local & global resets. 
   SIGNAL soft_reset_wclk0        : STD_LOGIC;
   SIGNAL soft_reset_wclk1_b4scan : STD_LOGIC;
   SIGNAL soft_reset_wclk1        : STD_LOGIC;		-- reset for fifo_wr_clk
   SIGNAL soft_reset_rclk0        : STD_LOGIC;
   SIGNAL soft_reset_rclk1_b4scan : STD_LOGIC;
   SIGNAL soft_reset_rclk1        : STD_LOGIC;		-- reset for pld_rx_clk
   
   -- Channel zero output should all channel rx_we_in of rx_ctrl
   
   SIGNAL rd_enable0              : STD_LOGIC;
   SIGNAL rd_enable0p5            : STD_LOGIC;
   SIGNAL rd_enable1              : STD_LOGIC;
   SIGNAL pld_wr_dis0             : STD_LOGIC;
   SIGNAL pld_wr_dis1             : STD_LOGIC;
   SIGNAL pld_wr_dis2             : STD_LOGIC;
   SIGNAL pld_wr_dis_edge         : STD_LOGIC;
   SIGNAL wr_enable0              : STD_LOGIC;
   SIGNAL wr_enable0p5            : STD_LOGIC;
   SIGNAL wr_enable1              : STD_LOGIC;
   SIGNAL wr_enable2              : STD_LOGIC;
   SIGNAL rxfifo_en_clk2_0        : STD_LOGIC;
   SIGNAL rxfifo_en_clk2_1        : STD_LOGIC;
   SIGNAL wr_enable_clk2          : STD_LOGIC;
   -- X-HDL generated signals

   SIGNAL xhdl1 : STD_LOGIC;
   SIGNAL xhdl2 : STD_LOGIC;
   
   -- Declare intermediate signals for referenced outputs
   SIGNAL rx_we_out_xhdl0         : STD_LOGIC;
BEGIN
   -- Drive referenced outputs
   rx_we_out <= rx_we_out_xhdl0;
   
   local_soft_reset <= soft_reset OR (rrxfifo_urst_en AND rxfifo_urst);
   
   wr_enable_out <= wr_enable1;
   rd_enable_out <= rd_enable1;
   
   -- generate rx_wr_clk reset
   PROCESS (local_soft_reset, rx_wr_clk)
VARIABLE  txt : LINE;
   BEGIN
      IF (local_soft_reset = '1') THEN
         soft_reset_wclk0 <=  TRANSPORT '1' AFTER 1* 1 ps;
         soft_reset_wclk1_b4scan <=  TRANSPORT '1' AFTER 1* 1 ps;
      ELSIF (rx_wr_clk'EVENT AND rx_wr_clk = '1') THEN
         soft_reset_wclk0 <=  TRANSPORT '0' AFTER 1* 1 ps;
         soft_reset_wclk1_b4scan <=  TRANSPORT soft_reset_wclk0 AFTER 1* 1 ps;
      END IF;
   END PROCESS;
   
   soft_reset_wclk1 <= '0' WHEN (scan_mode = '1') ELSE
                       soft_reset_wclk1_b4scan;
   
   -- generate pld_rx_clk reset
   PROCESS (local_soft_reset, rx_rd_clk)
VARIABLE  txt : LINE;
   BEGIN
      IF (local_soft_reset = '1') THEN
         soft_reset_rclk0 <=  TRANSPORT '1' AFTER 1* 1 ps;
         soft_reset_rclk1_b4scan <=  TRANSPORT '1' AFTER 1* 1 ps;
      ELSIF (rx_rd_clk'EVENT AND rx_rd_clk = '1') THEN
         soft_reset_rclk0 <=  TRANSPORT '0' AFTER 1* 1 ps;
         soft_reset_rclk1_b4scan <=  TRANSPORT soft_reset_rclk0 AFTER 1* 1 ps;
      END IF;
   END PROCESS;
   
   soft_reset_rclk1 <= '0' WHEN (scan_mode = '1') ELSE
                       soft_reset_rclk1_b4scan;
   
   -- write enable, fifo data in
   xhdl1 <= (wr_enable0p5 AND NOT(pld_wr_dis_edge)) WHEN (rrxphfifopldctl_en = '1') ELSE
                       wr_enable0p5;
   PROCESS (rx_wr_clk, soft_reset_wclk1)
VARIABLE  txt : LINE;
   BEGIN
      IF (soft_reset_wclk1 = '1') THEN
         pld_wr_dis0 <=  TRANSPORT '0' AFTER 1* 1 ps;
         pld_wr_dis1 <=  TRANSPORT '0' AFTER 1* 1 ps;
         pld_wr_dis2 <=  TRANSPORT '0' AFTER 1* 1 ps;
         pld_wr_dis_edge <=  TRANSPORT '0' AFTER 1* 1 ps;
         wr_enable0 <=  TRANSPORT '0' AFTER 1* 1 ps;
         wr_enable0p5 <=  TRANSPORT '0' AFTER 1* 1 ps;
         wr_enable1 <=  TRANSPORT '0' AFTER 1* 1 ps;
         wr_enable2 <=  TRANSPORT '0' AFTER 1* 1 ps;
      ELSIF (rx_wr_clk'EVENT AND rx_wr_clk = '1') THEN
         pld_wr_dis0 <=  TRANSPORT pld_wr_dis AFTER 1* 1 ps;
         pld_wr_dis1 <=  TRANSPORT pld_wr_dis0 AFTER 1* 1 ps;
         pld_wr_dis2 <=  TRANSPORT pld_wr_dis1 AFTER 1* 1 ps;
         pld_wr_dis_edge <=  TRANSPORT int2bit((pld_wr_dis2 /= pld_wr_dis1)) AFTER 1* 1 ps;
         wr_enable0 <=  TRANSPORT NOT((rauto_speed_ena AND dis_pc_byte)) AFTER 1* 1 ps;
         wr_enable0p5 <=  TRANSPORT wr_enable0 AFTER 1* 1 ps;
         wr_enable1 <=  TRANSPORT xhdl1 AFTER 1* 1 ps;
         wr_enable2 <=  TRANSPORT wr_enable1 AFTER 1* 1 ps;
      END IF;
   END PROCESS;
   
   -- read enable
   xhdl2 <= (rd_enable0p5 AND pld_re) WHEN (rrxphfifopldctl_en = '1') ELSE
                 rd_enable0p5;
   PROCESS (rx_rd_clk, soft_reset_rclk1)
VARIABLE  txt : LINE;
   BEGIN
      IF (soft_reset_rclk1 = '1') THEN
         rd_enable0 <=  TRANSPORT '0' AFTER 1* 1 ps;
         rd_enable0p5 <=  TRANSPORT '0' AFTER 1* 1 ps;
         rd_enable1 <=  TRANSPORT '0' AFTER 1* 1 ps;
      ELSIF (rx_rd_clk'EVENT AND rx_rd_clk = '1') THEN
         rd_enable0 <=  TRANSPORT NOT((rauto_speed_ena AND dis_pc_byte)) AFTER 1* 1 ps;
         rd_enable0p5 <=  TRANSPORT rd_enable0 AFTER 1* 1 ps;
         rd_enable1 <=  TRANSPORT xhdl2 AFTER 1* 1 ps;
      END IF;
   END PROCESS;
   
   -- byte de-serializer high/low select
   PROCESS (clk_2, soft_reset)
VARIABLE  txt : LINE;
   BEGIN
      IF (soft_reset = '1') THEN
         rx_we_out_xhdl0 <=  TRANSPORT '1' AFTER 1* 1 ps;
         rxfifo_en_clk2_0 <=  TRANSPORT '0' AFTER 1* 1 ps;
         rxfifo_en_clk2_1 <=  TRANSPORT '0' AFTER 1* 1 ps;
         wr_enable_clk2 <=  TRANSPORT '0' AFTER 1* 1 ps;
      ELSIF (clk_2'EVENT AND clk_2 = '1') THEN
         --rxfifo_en_clk2_0 <=  rxfifo_en;
         -- rxfifo_en_clk2_0 <=  1'b1;
         rxfifo_en_clk2_0 <=  TRANSPORT NOT((rauto_speed_ena AND dis_pc_byte)) AFTER 1* 1 ps;
         
         rxfifo_en_clk2_1 <=  TRANSPORT rxfifo_en_clk2_0 AFTER 1* 1 ps;
         IF (rxfifo_en_clk2_1 = '0') THEN
            wr_enable_clk2 <=  TRANSPORT '0' AFTER 1* 1 ps;
         ELSIF (wr_enable_clk2 = '0') THEN
            
            wr_enable_clk2 <=  TRANSPORT wr_enable2 AFTER 1* 1 ps;
         END IF;
         IF (wr_enable_clk2 = '1') THEN
            rx_we_out_xhdl0 <=  TRANSPORT NOT(rx_we_out_xhdl0) AFTER 1* 1 ps;
         ELSE
            rx_we_out_xhdl0 <=  TRANSPORT '0' AFTER 1* 1 ps;
         END IF;
      END IF;
   END PROCESS;
   
END trans;




-- rx_ctrl_centrl

LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
USE ieee.std_logic_unsigned.all;
LIBRARY STD;
USE STD.textio.ALL;
USE work.cycloneiv_hssi_components.all;

ENTITY cycloneiv_hssi_cmu_rxclk_gating IS
    PORT (
        
        select_n           : IN STD_LOGIC;
        clk1               : IN STD_LOGIC;
        clk2               : IN STD_LOGIC;
        clk1out_n          : OUT STD_LOGIC;
        clk2out_n          : OUT STD_LOGIC
    );
END ENTITY cycloneiv_hssi_cmu_rxclk_gating;

ARCHITECTURE trans OF cycloneiv_hssi_cmu_rxclk_gating IS
BEGIN
    
    clk1out_n <= NOT((select_n OR clk1));
    clk2out_n <= NOT((NOT(select_n) OR clk2));
    
END ARCHITECTURE trans;


LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
USE ieee.std_logic_unsigned.all;
LIBRARY STD;
USE STD.textio.ALL;
USE work.cycloneiv_hssi_components.all;

ENTITY cycloneiv_hssi_cmu_rxclk_ctl IS
   PORT (
      
      -- Clock Inputs
      pld_rx_clk              : IN STD_LOGIC;		-- PLD clock from PLD clock trees
      rcvd_clk_pma            : IN STD_LOGIC;		-- local recovered clock
      rcvd_clk0_pma           : IN STD_LOGIC;		-- channel zero recovered clock
      tx_pma_clk              : IN STD_LOGIC;		-- local TX PMA clock
      refclk_pma              : IN STD_LOGIC;		-- Quad based clk from TXPLL
      fref                    : IN STD_LOGIC;
      clklow                  : IN STD_LOGIC;
      
      -- Control Inputs
      scan_mode               : IN STD_LOGIC;		-- Scan mode enable signal
      -- This is the soft_reset for the RX_PCS
      
      -- New Control Inputs
      gen2ngen1               : IN STD_LOGIC;		-- from PMA for PCIexp Gen1/Gen2 datawidth scaling
      gen2ngen1_bundle        : IN STD_LOGIC;		-- from PMA for PCIexp Gen1/Gen2 datawidth scaling in x4 and x8 
      rx_div2_sync_centrl     : IN STD_LOGIC;		-- divided clock from the central channel (x2, x4 mode)
      rx_div2_sync_quad_up    : IN STD_LOGIC;		-- divided clock from quad above (> x4 mode)
      rx_div2_sync_quad_down  : IN STD_LOGIC;		-- divided clock from quad below (> x4 mode)
      
      -- MDIO Inputs
      rrcvd_clk_sel           : IN STD_LOGIC_VECTOR(1 DOWNTO 0);
      rclk_1_sel              : IN STD_LOGIC_VECTOR(1 DOWNTO 0);
      rclk_2_sel              : IN STD_LOGIC_VECTOR(1 DOWNTO 0);
      rrx_rd_clk_sel          : IN STD_LOGIC;		-- Select clock for rx ph comp fifo read side
      rxrst                   : IN STD_LOGIC;
      rindv_rx                : IN STD_LOGIC;		-- Select between XAUI mode or indiv  channel mode
      rdwidth_rx              : IN STD_LOGIC;		-- divide by 1 or 2 before feeding to FIFO write clock
      rfreerun_rx             : IN STD_LOGIC;		-- Select whether divider is permamently enabled (free -running) or divider should be enabled / reset by RX PCS reset
      
      -- New MDIO Inputs
      rauto_speed_ena         : IN STD_LOGIC;		-- auto speed negotiation enable
      rfreq_sel               : IN STD_LOGIC;		-- freq scaling or data width scaling
      rrxpcsclkpwdn           : IN STD_LOGIC;		-- RX clocking power down enable
      rmaster_rx              : IN STD_LOGIC;		-- New bundle mode MDIO, selects master quad
      rmaster_up_rx           : IN STD_LOGIC;		-- New bundle mode MDIO, selects master quad
      rself_sw_en_rx          : IN STD_LOGIC;		-- enables self-switch to have correct /2 clock in all quads in bundle mode
      
      -- Removed Inputs
      --    input          rphfifo_master_sel_rx;  // RX Phase comp. FIFO rx_div2_sync selection CRAM
      --    input          rx_div2_sync_in_ch0;    // Connect from channel zero rx_div2_sync_out
      --    input          rx_div2_sync_in_q0_ch0; // Connect from channel zero rx_div2_sync_out of Master Quad
      
      -- Clock Outputs with CTS
      fref_muxed              : OUT STD_LOGIC;
      clklow_muxed            : OUT STD_LOGIC;
      rcvd_clk                : OUT STD_LOGIC;
      clk_1_b                 : OUT STD_LOGIC;
      clk_2_b                 : OUT STD_LOGIC;
      rx_wr_clk               : OUT STD_LOGIC;		-- drives the rx ph comp fifo write clock tree
      rx_rd_clk               : OUT STD_LOGIC;		-- drives the rx ph comp fifo read clock tree
      
      -- Clock Outputs to PLD, no CTS
      rx_clk                  : OUT STD_LOGIC;		-- drives the PLD clock tree in x1 mode, logically same as rx_wr_clk
      rcvd_clk_pma_b          : OUT STD_LOGIC;		-- debug output clock to PLD
      
      -- New Clock Outputs with CTS
      clk_2_b_raw             : OUT STD_LOGIC;		-- same as clk_2_b, but with no clock gating
      rx_wr_clk_raw           : OUT STD_LOGIC;		-- same as rx_wr_clk, but with no clock gating
      rx_rd_clk_raw           : OUT STD_LOGIC;		-- same as rx_rd_clk, but with no clock gating
      
      -- Control Outputs
      rx_div2_sync_out        : OUT STD_LOGIC		-- inverted /2 clock.  not used w/new bundling scheme. (left for safety)
   );
END cycloneiv_hssi_cmu_rxclk_ctl;

ARCHITECTURE trans OF cycloneiv_hssi_cmu_rxclk_ctl IS
   COMPONENT cycloneiv_hssi_cmu_rxclk_gating
        PORT (
            select_n                : IN STD_LOGIC;
            clk1                    : IN STD_LOGIC;
            clk2                    : IN STD_LOGIC;
            clk1out_n               : OUT STD_LOGIC;
            clk2out_n               : OUT STD_LOGIC
        );
    END COMPONENT;
      
   SIGNAL rx_clk_2_by2           : STD_LOGIC := '1';
   SIGNAL gen2ngen1_local_sync   : STD_LOGIC;
   SIGNAL counter                : STD_LOGIC_VECTOR(1 DOWNTO 0);
   
   SIGNAL rx_div2_sync           : STD_LOGIC;
   SIGNAL rx_rst_n               : STD_LOGIC;
   SIGNAL rrcvd_clk_sel_int      : STD_LOGIC_VECTOR(1 DOWNTO 0);
   SIGNAL rclk_1_sel_int         : STD_LOGIC_VECTOR(1 DOWNTO 0);
   SIGNAL rclk_2_sel_int         : STD_LOGIC_VECTOR(1 DOWNTO 0);
   SIGNAL dynamic_div2ndiv1      : STD_LOGIC;
   SIGNAL gen2ngen1_local        : STD_LOGIC;
   SIGNAL rrxpcsclkpwdn_nscan    : STD_LOGIC;
   SIGNAL rx_div2_this_quad      : STD_LOGIC;
   SIGNAL rx_div2_this_channel   : STD_LOGIC;
   SIGNAL rx_div2_other_quad     : STD_LOGIC;
   SIGNAL force_master           : STD_LOGIC;
   
    SIGNAL select_div1_n          : STD_LOGIC;
    SIGNAL clk1out_n              : STD_LOGIC;
    SIGNAL clk2out_n              : STD_LOGIC;
    
   -- Declare intermediate signals for referenced outputs
   SIGNAL rx_wr_clk_xhdl3        : STD_LOGIC;
   SIGNAL clk_2_b_raw_xhdl0      : STD_LOGIC;
   SIGNAL rx_wr_clk_raw_xhdl4    : STD_LOGIC;
   SIGNAL rx_rd_clk_raw_xhdl2    : STD_LOGIC;
   SIGNAL rx_div2_sync_out_xhdl1 : STD_LOGIC;
BEGIN
   -- Drive referenced outputs
   rx_wr_clk <= rx_wr_clk_xhdl3;
   clk_2_b_raw <= clk_2_b_raw_xhdl0;
   rx_wr_clk_raw <= rx_wr_clk_raw_xhdl4;
   rx_rd_clk_raw <= rx_rd_clk_raw_xhdl2;
   rx_div2_sync_out <= rx_div2_sync_out_xhdl1;
   
   -- Old bundle logic:
   -- Select between the local synchronization signal or the global synchronization signal
   --assign rx_div2_sync = rindv_rx ? rx_div2_sync_out : rx_div2_sync_in;
   -- assign 	  rx_div2_sync = (rphfifo_master_sel_rx == 1'b0) ? rx_div2_sync_in_q0_ch0 :
   -- 				 (rindv_rx == 1'b0) ? rx_div2_sync_in_ch0 : 
   -- 				 (rauto_speed_ena & ~rfreq_sel) ? (rx_div2_sync_out | ~gen2ngen1_local_sync) : rx_div2_sync_out;
   
   PROCESS (rxrst, clk_2_b_raw_xhdl0)
VARIABLE  txt : LINE;
   BEGIN
      IF (rxrst = '1') THEN
         counter <=  TRANSPORT "00" AFTER 1* 1 ps;
      ELSIF (clk_2_b_raw_xhdl0'EVENT AND clk_2_b_raw_xhdl0 = '1') THEN
         IF (((rauto_speed_ena AND NOT(rfreq_sel) AND rself_sw_en_rx) AND NOT(force_master)) = '1') THEN
            counter <=  TRANSPORT counter + "01" AFTER 1* 1 ps;
         END IF;
      END IF;
   END PROCESS;
   
   force_master <= '1' WHEN ((counter = "11") AND ((rauto_speed_ena AND NOT(rfreq_sel) AND rself_sw_en_rx) = '1')) ELSE
                   '0';
   
   rx_div2_sync <= rx_div2_this_quad WHEN ((rmaster_rx OR force_master) = '1') ELSE
                   rx_div2_other_quad;
   rx_div2_this_quad <= rx_div2_this_channel WHEN ((rindv_rx OR force_master) = '1') ELSE
                        rx_div2_sync_centrl;
   rx_div2_this_channel <= (rx_div2_sync_out_xhdl1 OR NOT(gen2ngen1_local_sync)) WHEN ((rauto_speed_ena AND NOT(rfreq_sel)) = '1') ELSE
                           rx_div2_sync_out_xhdl1;
   rx_div2_other_quad <= rx_div2_sync_quad_up WHEN (rmaster_up_rx = '1') ELSE
                         rx_div2_sync_quad_down;
   
   gen2ngen1_local <= gen2ngen1_bundle WHEN (rindv_rx = '0') ELSE
                      gen2ngen1;
   
   PROCESS (rxrst, clk_2_b_raw_xhdl0)
VARIABLE  txt : LINE;
   BEGIN
      IF (rxrst = '1') THEN
         gen2ngen1_local_sync <=  TRANSPORT '0' AFTER 1* 1 ps;
      ELSIF (clk_2_b_raw_xhdl0'EVENT AND clk_2_b_raw_xhdl0 = '1') THEN
         gen2ngen1_local_sync <=  TRANSPORT gen2ngen1_local AFTER 1* 1 ps;
      END IF;
   END PROCESS;
   
   dynamic_div2ndiv1 <= rdwidth_rx OR (gen2ngen1_local_sync AND rauto_speed_ena AND NOT(rfreq_sel));
   
   -- Reset for Divide-by-2 FF and synchronization FF's for clock gating
   rx_rst_n <= '1' WHEN (rfreerun_rx = '1') ELSE
               NOT(rxrst);
   
   rrxpcsclkpwdn_nscan <= rrxpcsclkpwdn AND NOT(scan_mode);
   
   -- clocks are assigned below in the order in which they appear in the out flowing data path
   -- RCVD_CLK selection
   rrcvd_clk_sel_int <= "01" WHEN (scan_mode = '1') ELSE
                        rrcvd_clk_sel;
   rcvd_clk <= '1' WHEN (rrxpcsclkpwdn_nscan = '1') ELSE
               rcvd_clk_pma WHEN (rrcvd_clk_sel_int = "00") ELSE
               refclk_pma WHEN (rrcvd_clk_sel_int = "01") ELSE
               tx_pma_clk WHEN (rrcvd_clk_sel_int = "10") ELSE
               rcvd_clk_pma WHEN (rrcvd_clk_sel_int = "11") ELSE
               rcvd_clk_pma;
   
   -- CLK_1 seleciton
   rclk_1_sel_int <= "01" WHEN (scan_mode = '1') ELSE
                     rclk_1_sel;
   clk_1_b <= '1' WHEN (rrxpcsclkpwdn_nscan = '1') ELSE
              rcvd_clk_pma WHEN (rclk_1_sel_int = "00") ELSE
              refclk_pma WHEN (rclk_1_sel_int = "01") ELSE
              tx_pma_clk WHEN (rclk_1_sel_int = "10") ELSE
              rcvd_clk0_pma WHEN (rclk_1_sel_int = "11") ELSE
              rcvd_clk_pma;
   
   -- CLK_2 selection
   rclk_2_sel_int <= "10" WHEN (scan_mode = '1') ELSE
                     rclk_2_sel;
   clk_2_b_raw_xhdl0 <= rcvd_clk_pma WHEN (rclk_2_sel_int = "00") ELSE
                        tx_pma_clk WHEN (rclk_2_sel_int = "01") ELSE
                        refclk_pma WHEN (rclk_2_sel_int = "10") ELSE
                        rcvd_clk_pma;
   --change made for S3GX to remove pld_rx_clk from mux input 
   --(rclk_2_sel_int == 2'b10) ? refclk_pma : 
   --(rclk_2_sel_int == 2'b11) ? pld_rx_clk : rcvd_clk_pma;
   
   clk_2_b <= '1' WHEN (rrxpcsclkpwdn_nscan = '1') ELSE
              clk_2_b_raw_xhdl0;
   
   -- This register is used to generate divided by two clock. Div by 2 clock starts off high after reset
   -- No #1 on this FF as it generates a clock
   PROCESS (rx_rst_n, clk_2_b_raw_xhdl0)
VARIABLE  txt : LINE;
   BEGIN
      IF ((NOT(rx_rst_n)) = '1') THEN
         rx_clk_2_by2 <= '1';
      ELSIF (clk_2_b_raw_xhdl0'EVENT AND clk_2_b_raw_xhdl0 = '1') THEN
         rx_clk_2_by2 <= rx_div2_sync;
      END IF;
   END PROCESS;
   
   rx_div2_sync_out_xhdl1 <= NOT(rx_clk_2_by2);
   
   -- RX FIFO write clock: could be fast or divided by 2
   -- old code:
   -- assign rx_wr_clk = ((rdwidth_rx == 1'b0) || scan_mode) ? clk_2_b_raw : rx_clk_2_by2;
   
   select_div1_n <= NOT((scan_mode OR NOT(dynamic_div2ndiv1)));
   
   rxclk_gating : cycloneiv_hssi_cmu_rxclk_gating
      PORT MAP (
            select_n   => select_div1_n,
            clk1       => clk_2_b_raw_xhdl0,
            clk2       => rx_clk_2_by2,
            clk1out_n  => clk1out_n,
            clk2out_n  => clk2out_n
        );
    
   rx_wr_clk_raw_xhdl4 <= NOT((clk1out_n OR clk2out_n));
   
   rx_wr_clk_xhdl3 <= '1' WHEN (rrxpcsclkpwdn_nscan = '1') ELSE
                      rx_wr_clk_raw_xhdl4;
   
   -- RX FIFO read clock
   rx_rd_clk_raw_xhdl2 <= rx_wr_clk_raw_xhdl4 WHEN ((scan_mode OR int2bit((rrx_rd_clk_sel = '0'))) = '1') ELSE
                          pld_rx_clk;
   rx_rd_clk <= '1' WHEN (rrxpcsclkpwdn_nscan = '1') ELSE
                rx_rd_clk_raw_xhdl2;
   
   -- RX clock out
   rx_clk <= rx_wr_clk_xhdl3;		-- drives PLD clock tree
   
   -- Recovered clock for debugging
   rcvd_clk_pma_b <= rcvd_clk_pma;		-- Goes out to PLD as debug clock. This clock may or may not be routed out to PLD fabric. TBD
   
   fref_muxed <= refclk_pma WHEN (scan_mode = '1') ELSE
                 '1' WHEN (rrxpcsclkpwdn = '1') ELSE
                 fref;
   clklow_muxed <= refclk_pma WHEN (scan_mode = '1') ELSE
                   '1' WHEN (rrxpcsclkpwdn = '1') ELSE
                   clklow;
   
END trans;




-- rxclk_ctl_centrl


LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
USE ieee.std_logic_unsigned.all;
LIBRARY STD;
USE STD.textio.ALL;
USE work.cycloneiv_hssi_components.all;

ENTITY cycloneiv_hssi_cmu_tx_ctrl IS
    PORT (
      
      -- ======
      -- inputs
      -- ======
      soft_reset          : IN STD_LOGIC;		-- Reset
      fifo_wr_clk         : IN STD_LOGIC;		-- Used to be wr_clk_pos
      fifo_rd_clk         : IN STD_LOGIC;		-- Coming from txclk_xg_ctl 
      refclk_b_in         : IN STD_LOGIC;		-- The local reference clock used by the internal
      scan_mode           : IN STD_LOGIC;		-- scan enable
      rtxfifo_urst_en     : IN STD_LOGIC;		-- user reset CRAM enable
      txfifo_urst         : IN STD_LOGIC;		-- user reset 
      rtxphfifopldctl_en  : IN STD_LOGIC;		-- CRAM to enable PLD controlled write/read enable
      pld_we              : IN STD_LOGIC;		-- PLD phase comp. fifo we, level active
      pld_rd_dis          : IN STD_LOGIC;		-- PLD phase comp. fifo rd dis, edge active
      dis_pc_byte         : IN STD_LOGIC;
      -- New MDIO for new bundling scheme and new PCIE features like autospeed
      rauto_speed_ena     : IN STD_LOGIC;
      
      -- =======
      -- outputs
      -- =======
      wr_enable_out       : OUT STD_LOGIC;		-- ch0 wr_enable1 output for X4/X8 mode
      rd_enable_out       : OUT STD_LOGIC;		-- ch0 rd_enable1 output for X4/X8 mode
      fifo_select_out     : OUT STD_LOGIC		-- New output for Rev.B 
   );
END cycloneiv_hssi_cmu_tx_ctrl;

ARCHITECTURE trans OF cycloneiv_hssi_cmu_tx_ctrl IS
   
   SIGNAL wr_enable0                 : STD_LOGIC;
   SIGNAL wr_enable0p5               : STD_LOGIC;
   SIGNAL wr_enable1                 : STD_LOGIC;
   SIGNAL rd_enable0                 : STD_LOGIC;
   SIGNAL rd_enable0p5               : STD_LOGIC;
   SIGNAL rd_enable1                 : STD_LOGIC;
   SIGNAL rd_enable2                 : STD_LOGIC;
   
   SIGNAL soft_reset_local           : STD_LOGIC;
   SIGNAL soft_reset_wclk0           : STD_LOGIC;
   SIGNAL soft_reset_wclk1_b4scan    : STD_LOGIC;
   SIGNAL soft_reset_wclk1           : STD_LOGIC;
   SIGNAL soft_reset_rclk0           : STD_LOGIC;
   SIGNAL soft_reset_rclk1_b4scan    : STD_LOGIC;
   SIGNAL soft_reset_rclk1           : STD_LOGIC;
   
   SIGNAL pld_rd_dis0                : STD_LOGIC;
   SIGNAL pld_rd_dis1                : STD_LOGIC;
   SIGNAL pld_rd_dis2                : STD_LOGIC;
   SIGNAL pld_rd_dis_edge            : STD_LOGIC;
   
   SIGNAL txfifo_en_refclk0          : STD_LOGIC;
   SIGNAL txfifo_en_refclk1          : STD_LOGIC;
   SIGNAL rd_enable_sync_refclk_b_in : STD_LOGIC;
   -- X-HDL generated signals

   SIGNAL xhdl1 : STD_LOGIC;
   SIGNAL xhdl2 : STD_LOGIC;
   
   -- Declare intermediate signals for referenced outputs
   SIGNAL fifo_select_out_xhdl0      : STD_LOGIC;
BEGIN
   -- Drive referenced outputs
   fifo_select_out <= fifo_select_out_xhdl0;
   
   wr_enable_out <= wr_enable1;
   rd_enable_out <= rd_enable1;
   
   soft_reset_local <= soft_reset OR (rtxfifo_urst_en AND txfifo_urst);
   
   -- synchronize reset input (in refclk_b domain)
   PROCESS (soft_reset_local, fifo_wr_clk)
VARIABLE  txt : LINE;
   BEGIN
      IF (soft_reset_local = '1') THEN
         soft_reset_wclk0 <=  TRANSPORT '1' AFTER 1* 1 ps;
         soft_reset_wclk1_b4scan <=  TRANSPORT '1' AFTER 1* 1 ps;
      ELSIF (fifo_wr_clk'EVENT AND fifo_wr_clk = '1') THEN
         soft_reset_wclk0 <=  TRANSPORT '0' AFTER 1* 1 ps;
         soft_reset_wclk1_b4scan <=  TRANSPORT soft_reset_wclk0 AFTER 1* 1 ps;
      END IF;
   END PROCESS;
   -- always @ (posedge soft_reset_local or posedge fifo_wr_clk)
   
   soft_reset_wclk1 <= '0' WHEN (scan_mode = '1') ELSE
                       soft_reset_wclk1_b4scan;
   
   -- synchronize reset input (in refclk_b domain) and balance it with fifo_wr_clk reset
   PROCESS (soft_reset_local, fifo_rd_clk)
VARIABLE  txt : LINE;
   BEGIN
      IF (soft_reset_local = '1') THEN
         soft_reset_rclk0 <=  TRANSPORT '1' AFTER 1* 1 ps;
         soft_reset_rclk1_b4scan <=  TRANSPORT '1' AFTER 1* 1 ps;
      ELSIF (fifo_rd_clk'EVENT AND fifo_rd_clk = '1') THEN
         soft_reset_rclk0 <=  TRANSPORT '0' AFTER 1* 1 ps;
         soft_reset_rclk1_b4scan <=  TRANSPORT soft_reset_rclk0 AFTER 1* 1 ps;
      END IF;
   END PROCESS;
   -- always @ (posedge soft_reset_local or posedge fifo_rd_clk)
   
   soft_reset_rclk1 <= '0' WHEN (scan_mode = '1') ELSE
                       soft_reset_rclk1_b4scan;
   
   -- write enable
   xhdl1 <= (wr_enable0p5 AND pld_we) WHEN (rtxphfifopldctl_en = '1') ELSE
                       wr_enable0p5;
   PROCESS (soft_reset_wclk1, fifo_wr_clk)
VARIABLE  txt : LINE;
   BEGIN
      IF (soft_reset_wclk1 = '1') THEN
         wr_enable0 <=  TRANSPORT '0' AFTER 1* 1 ps;
         wr_enable0p5 <=  TRANSPORT '0' AFTER 1* 1 ps;
         wr_enable1 <=  TRANSPORT '0' AFTER 1* 1 ps;
      ELSIF (fifo_wr_clk'EVENT AND fifo_wr_clk = '1') THEN
         wr_enable0 <=  TRANSPORT NOT((rauto_speed_ena AND dis_pc_byte)) AFTER 1* 1 ps;
         wr_enable0p5 <=  TRANSPORT wr_enable0 AFTER 1* 1 ps;
         wr_enable1 <=  TRANSPORT xhdl1 AFTER 1* 1 ps;
      END IF;
   END PROCESS;
   -- always @ (posedge soft_reset_wclk1 or posedge fifo_wr_clk)
   
   -- read enable & 
   -- read enable sync (for byte serializer output enable)
   
   xhdl2 <= (rd_enable0p5 AND NOT(pld_rd_dis_edge)) WHEN (rtxphfifopldctl_en = '1') ELSE
                 rd_enable0p5;
   PROCESS (soft_reset_rclk1, fifo_rd_clk)
VARIABLE  txt : LINE;
   BEGIN
      IF (soft_reset_rclk1 = '1') THEN
         pld_rd_dis0 <=  TRANSPORT '0' AFTER 1* 1 ps;
         pld_rd_dis1 <=  TRANSPORT '0' AFTER 1* 1 ps;
         pld_rd_dis2 <=  TRANSPORT '0' AFTER 1* 1 ps;
         pld_rd_dis_edge <=  TRANSPORT '0' AFTER 1* 1 ps;
         rd_enable0 <=  TRANSPORT '0' AFTER 1* 1 ps;
         rd_enable0p5 <=  TRANSPORT '0' AFTER 1* 1 ps;
         rd_enable1 <=  TRANSPORT '0' AFTER 1* 1 ps;
         rd_enable2 <=  TRANSPORT '0' AFTER 1* 1 ps;
      ELSIF (fifo_rd_clk'EVENT AND fifo_rd_clk = '1') THEN
         pld_rd_dis0 <=  TRANSPORT pld_rd_dis AFTER 1* 1 ps;
         pld_rd_dis1 <=  TRANSPORT pld_rd_dis0 AFTER 1* 1 ps;
         pld_rd_dis2 <=  TRANSPORT pld_rd_dis1 AFTER 1* 1 ps;
         pld_rd_dis_edge <=  TRANSPORT int2bit((pld_rd_dis2 /= pld_rd_dis1)) AFTER 1* 1 ps;
         rd_enable0 <=  TRANSPORT NOT((rauto_speed_ena AND dis_pc_byte)) AFTER 1* 1 ps;
         rd_enable0p5 <=  TRANSPORT rd_enable0 AFTER 1* 1 ps;
         rd_enable1 <=  TRANSPORT xhdl2 AFTER 1* 1 ps;
         
         rd_enable2 <=  TRANSPORT rd_enable1 AFTER 1* 1 ps;
      END IF;
   END PROCESS;
   -- always @ (posedge soft_reset_rclk1 or posedge fifo_rd_clk)
   
   -- byte serializer high/low select
   PROCESS (soft_reset, refclk_b_in)
VARIABLE  txt : LINE;
   BEGIN
      IF (soft_reset = '1') THEN
         rd_enable_sync_refclk_b_in <=  TRANSPORT '0' AFTER 1* 1 ps;
         txfifo_en_refclk0 <=  TRANSPORT '0' AFTER 1* 1 ps;
         txfifo_en_refclk1 <=  TRANSPORT '0' AFTER 1* 1 ps;
         fifo_select_out_xhdl0 <=  TRANSPORT '0' AFTER 1* 1 ps;
      ELSIF (refclk_b_in'EVENT AND refclk_b_in = '1') THEN
         txfifo_en_refclk0 <=  TRANSPORT NOT((rauto_speed_ena AND dis_pc_byte)) AFTER 1* 1 ps;
         
         txfifo_en_refclk1 <=  TRANSPORT txfifo_en_refclk0 AFTER 1* 1 ps;
         IF (txfifo_en_refclk1 = '0') THEN
            rd_enable_sync_refclk_b_in <=  TRANSPORT '0' AFTER 1* 1 ps;
         ELSIF (rd_enable_sync_refclk_b_in = '0') THEN
            
            rd_enable_sync_refclk_b_in <=  TRANSPORT rd_enable2 AFTER 1* 1 ps;
         END IF;
         IF (rd_enable_sync_refclk_b_in = '1') THEN
            fifo_select_out_xhdl0 <=  TRANSPORT NOT(fifo_select_out_xhdl0) AFTER 1* 1 ps;
         ELSE
            fifo_select_out_xhdl0 <=  TRANSPORT '0' AFTER 1* 1 ps;
         END IF;
      END IF;
   END PROCESS;
   
END trans;


-- always @ (posedge soft_reset or posedge refclk_b_in)


-- tx_ctrl_centrl

LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
USE ieee.std_logic_unsigned.all;
LIBRARY STD;
USE STD.textio.ALL;
USE work.cycloneiv_hssi_components.all;

ENTITY cycloneiv_hssi_cmu_txclk_gating IS
    PORT (
        
        select_n                : IN STD_LOGIC;
        clk1                    : IN STD_LOGIC;
        clk2                    : IN STD_LOGIC;
        clk1out_n               : OUT STD_LOGIC;
        clk2out_n               : OUT STD_LOGIC
    );
END ENTITY cycloneiv_hssi_cmu_txclk_gating;

ARCHITECTURE trans OF cycloneiv_hssi_cmu_txclk_gating IS
BEGIN
    
    clk1out_n <= NOT((select_n OR clk1));
    clk2out_n <= NOT((NOT(select_n) OR clk2));
    
END ARCHITECTURE trans;

LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
USE ieee.std_logic_unsigned.all;
LIBRARY STD;
USE STD.textio.ALL;
USE work.cycloneiv_hssi_components.all;

ENTITY cycloneiv_hssi_cmu_txclk_ctl IS
   PORT (
      
      -- Clock Inputs
      pld_tx_clk              : IN STD_LOGIC;		-- PLD clock from PLD clock trees, the transmit clock from XGMII.
      refclk_pma              : IN STD_LOGIC;		-- Quad based clk from TXPLL
      txpma_local_clk         : IN STD_LOGIC;		-- Local channel TX PMA clock.
      
      -- Control Inputs
      txrst                   : IN STD_LOGIC;		-- reset for the tx_pcs
      scan_mode               : IN STD_LOGIC;		-- Scan mode enable signal for selecting scan_clk from refclk_pma
      
      -- New Control Inputs
      gen2ngen1               : IN STD_LOGIC;		-- from PMA for PCIexp Gen1/Gen2 datawidth scaling
      gen2ngen1_bundle        : IN STD_LOGIC;		-- from PMA for PCIexp Gen1/Gen2 datawidth scaling in x4 and x8
      tx_div2_sync_centrl     : IN STD_LOGIC;		-- divided clock from the central channel (x2, x4 mode)
      tx_div2_sync_quad_up    : IN STD_LOGIC;		-- divided clock from quad above (> x4 mode)
      tx_div2_sync_quad_down  : IN STD_LOGIC;		-- divided clock from quad below (> x4 mode)
      
      -- MDIO Inputs
      rindv_tx                : IN STD_LOGIC;		-- Selects between indiv chan. mode and bundled mode
      rtxwrclksel             : IN STD_LOGIC;		-- Selects which clock writes into FIFO
      rtxrdclksel             : IN STD_LOGIC;		-- Selects which clock reads from FIFO and also clocks reest of TX logic
      rdwidth_tx              : IN STD_LOGIC;		-- divide by 1 or 2 before feeding to FIFO read clock
      rfreerun_tx             : IN STD_LOGIC;		-- Select whether divider is permamently enabled (free -running) or  divider should be enabled / reset by TX PCS reset  
      
      -- New MDIO Inputs
      rauto_speed_ena         : IN STD_LOGIC;		-- auto speed negotiation enable
      rfreq_sel               : IN STD_LOGIC;		-- freq scaling or data width scaling
      rtxpcsclkpwdn           : IN STD_LOGIC;		-- TX clocking power down enable
      rmaster_tx              : IN STD_LOGIC;		-- New bundle mode MDIO, selects master quad
      rmaster_up_tx           : IN STD_LOGIC;		-- New bundle mode MDIO, selects master quad
      rself_sw_en_tx          : IN STD_LOGIC;		-- enables self-switch to have correct /2 clock in all quads in bundle mode
      
      -- Removed Inputs
      -- input        tx_div2_sync_in_ch0;    // from the channel zero tx_div2_sync_out
      -- input        tx_div2_sync_in_q0_ch0; // From channel0 of Master Quad
      -- input        rphfifo_master_sel_tx;  // TX Phase comp. FIFO tx_div2_sync selection CRAM
      
      -- Clock Outputs wtih CTS
      refclk_b                : OUT STD_LOGIC;		-- Drives the tx channel clock
      wr_clk_pos              : OUT STD_LOGIC;		-- Drives tx phase comp fifo write side
      fifo_rd_clk             : OUT STD_LOGIC;		-- Drives tx phase comp fifo read side
      
      -- Clock Outputs to PLD, w/o CTS
      tx_clk_out              : OUT STD_LOGIC;		-- Drives to the PLD clock tree -- unconnected
      
      -- New Clock Outputs with CTS
      refclk_b_raw            : OUT STD_LOGIC;		-- same as refclk_b, but with no clock gating
      wr_clk_pos_raw          : OUT STD_LOGIC;		-- same as wr_clk_pos, but with no clock gating
      fifo_rd_clk_raw         : OUT STD_LOGIC;		-- same as fifo_rd_clk, but with no clock gating
      
      -- Control Outputs
      tx_div2_sync_out        : OUT STD_LOGIC		-- Synchronizes the divided by two clock
   );
END cycloneiv_hssi_cmu_txclk_ctl;

ARCHITECTURE trans OF cycloneiv_hssi_cmu_txclk_ctl IS
    COMPONENT cycloneiv_hssi_cmu_txclk_gating IS
        PORT (
            select_n                : IN STD_LOGIC;
            clk1                    : IN STD_LOGIC;
            clk2                    : IN STD_LOGIC;
            clk1out_n               : OUT STD_LOGIC;
            clk2out_n               : OUT STD_LOGIC
        );
    END COMPONENT;
      
   SIGNAL fifo_rd_clk_by2        : STD_LOGIC := '1';
   SIGNAL gen2ngen1_local_sync   : STD_LOGIC;
   SIGNAL counter                : STD_LOGIC_VECTOR(1 DOWNTO 0);
   
   SIGNAL tx_rst_n               : STD_LOGIC;
   SIGNAL tx_div2_sync           : STD_LOGIC;
   SIGNAL dynamic_div2ndiv1      : STD_LOGIC;
   SIGNAL gen2ngen1_local        : STD_LOGIC;
   SIGNAL tx_div2_this_quad      : STD_LOGIC;
   SIGNAL tx_div2_this_channel   : STD_LOGIC;
   SIGNAL tx_div2_other_quad     : STD_LOGIC;
   SIGNAL force_master           : STD_LOGIC;
   SIGNAL rtxpcsclkpwdn_nscan    : STD_LOGIC;
    
    SIGNAL select_div1_n          : STD_LOGIC;
    SIGNAL clk1out_n              : STD_LOGIC;
    SIGNAL clk2out_n              : STD_LOGIC;
   
   -- Declare intermediate signals for referenced outputs
   SIGNAL fifo_rd_clk_xhdl0      : STD_LOGIC;
   SIGNAL refclk_b_raw_xhdl2     : STD_LOGIC;
   SIGNAL wr_clk_pos_raw_xhdl4   : STD_LOGIC;
   SIGNAL fifo_rd_clk_raw_xhdl1  : STD_LOGIC;
   SIGNAL tx_div2_sync_out_xhdl3 : STD_LOGIC;
BEGIN
   -- Drive referenced outputs
   fifo_rd_clk <= fifo_rd_clk_xhdl0;
   refclk_b_raw <= refclk_b_raw_xhdl2;
   wr_clk_pos_raw <= wr_clk_pos_raw_xhdl4;
   fifo_rd_clk_raw <= fifo_rd_clk_raw_xhdl1;
   tx_div2_sync_out <= tx_div2_sync_out_xhdl3;
   
   
   -- Old bundle logic:   
   -- Select between the local synchronization signal or the global synchronization signal (either from Channel0 or 
   -- Channel0 of Master Quad
   --assign tx_div2_sync = rindv_tx ? tx_div2_sync_out : tx_div2_sync_in;
   -- assign 	tx_div2_sync = (rphfifo_master_sel_tx == 1'b0) ? tx_div2_sync_in_q0_ch0 :
   --                            (rindv_tx == 1'b0) ? tx_div2_sync_in_ch0 : 
   --                            (rauto_speed_ena & ~rfreq_sel) ? (tx_div2_sync_out | ~gen2ngen1_local_sync) : tx_div2_sync_out;
   --
   
   PROCESS (txrst, refclk_b_raw_xhdl2)
VARIABLE  txt : LINE;
   BEGIN
      IF (txrst = '1') THEN
         counter <=  TRANSPORT "00" AFTER 1* 1 ps;
      ELSIF (refclk_b_raw_xhdl2'EVENT AND refclk_b_raw_xhdl2 = '1') THEN
         IF (((rauto_speed_ena AND NOT(rfreq_sel) AND rself_sw_en_tx) AND NOT(force_master)) = '1') THEN
            counter <=  TRANSPORT counter + "01" AFTER 1* 1 ps;
         END IF;
      END IF;
   END PROCESS;
   
   force_master <= '1' WHEN ((counter = "11") AND ((rauto_speed_ena AND NOT(rfreq_sel) AND rself_sw_en_tx) = '1')) ELSE
                   '0';
   
   tx_div2_sync <= tx_div2_this_quad WHEN ((rmaster_tx OR force_master) = '1') ELSE
                   tx_div2_other_quad;
   tx_div2_this_quad <= tx_div2_this_channel WHEN ((rindv_tx OR force_master) = '1') ELSE
                        tx_div2_sync_centrl;
   tx_div2_this_channel <= (tx_div2_sync_out_xhdl3 OR NOT(gen2ngen1_local_sync)) WHEN ((rauto_speed_ena AND NOT(rfreq_sel)) = '1') ELSE
                           tx_div2_sync_out_xhdl3;
   tx_div2_other_quad <= tx_div2_sync_quad_up WHEN (rmaster_up_tx = '1') ELSE
                         tx_div2_sync_quad_down;
   
   gen2ngen1_local <= gen2ngen1_bundle WHEN (rindv_tx = '0') ELSE
                      gen2ngen1;
   
   PROCESS (txrst, refclk_b_raw_xhdl2)
VARIABLE  txt : LINE;
   BEGIN
      IF (txrst = '1') THEN
         gen2ngen1_local_sync <=  TRANSPORT '0' AFTER 1* 1 ps;
      ELSIF (refclk_b_raw_xhdl2'EVENT AND refclk_b_raw_xhdl2 = '1') THEN
         gen2ngen1_local_sync <=  TRANSPORT gen2ngen1_local AFTER 1* 1 ps;
      END IF;
   END PROCESS;
   
   dynamic_div2ndiv1 <= rdwidth_tx OR (gen2ngen1_local_sync AND rauto_speed_ena AND NOT(rfreq_sel));
   
   -- Reset for Divide-by-2 FF
   tx_rst_n <= '1' WHEN (rfreerun_tx = '1') ELSE
               NOT(txrst);
   
   rtxpcsclkpwdn_nscan <= rtxpcsclkpwdn AND NOT(scan_mode);
   
   -- Full speed clock for TX PCS
   refclk_b_raw_xhdl2 <= refclk_pma WHEN ((scan_mode OR rtxrdclksel) = '1') ELSE
                         txpma_local_clk;
   
   refclk_b <= '1' WHEN (rtxpcsclkpwdn_nscan = '1') ELSE
               refclk_b_raw_xhdl2;
   
   -- Divide-by-2 FF
   PROCESS (tx_rst_n, refclk_b_raw_xhdl2)
VARIABLE  txt : LINE;
   BEGIN
      IF ((NOT(tx_rst_n)) = '1') THEN
         fifo_rd_clk_by2 <= '1';
      ELSIF (refclk_b_raw_xhdl2'EVENT AND refclk_b_raw_xhdl2 = '1') THEN
         fifo_rd_clk_by2 <= tx_div2_sync;		-- local divided clock
      END IF;
   END PROCESS;
   
   tx_div2_sync_out_xhdl3 <= NOT(fifo_rd_clk_by2);
   
   -- TX FIFO read clock: could be fast or divided by 2
   -- old code:
   -- assign fifo_rd_clk = ((rdwidth_tx == 1'b0) || scan_mode) ? refclk_b_raw : fifo_rd_clk_by2;
   
    select_div1_n <= NOT((scan_mode OR NOT(dynamic_div2ndiv1)));
    
    txclk_gating : cycloneiv_hssi_cmu_txclk_gating
        PORT MAP (
            select_n   => select_div1_n,
            clk1       => refclk_b_raw_xhdl2,
            clk2       => fifo_rd_clk_by2,
            clk1out_n  => clk1out_n,
            clk2out_n  => clk2out_n
        );
    
   fifo_rd_clk_raw_xhdl1 <= NOT((clk1out_n OR clk2out_n));
      
   fifo_rd_clk_xhdl0 <= '1' WHEN (rtxpcsclkpwdn_nscan = '1') ELSE
                        fifo_rd_clk_raw_xhdl1;
   
   -- TX FIFO write clock: used internal clock when in BIST or scan or HIP
   wr_clk_pos_raw_xhdl4 <= fifo_rd_clk_raw_xhdl1 WHEN ((scan_mode OR rtxwrclksel) = '1') ELSE
                           pld_tx_clk;
   wr_clk_pos <= '1' WHEN (rtxpcsclkpwdn_nscan = '1') ELSE
                 wr_clk_pos_raw_xhdl4;
   
   -- TX Clock Out
   tx_clk_out <= fifo_rd_clk_xhdl0;		-- drives PLD clock tree
   
END trans;




-- txclk_ctl_cenrtl


LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
USE ieee.std_logic_unsigned.all;
LIBRARY STD;
USE STD.textio.ALL;
USE work.cycloneiv_hssi_components.all;

ENTITY cycloneiv_hssi_cmu_dprio_bit IS
   PORT (
      
      reset        : IN STD_LOGIC;		-- reset
      clk          : IN STD_LOGIC;		-- clock
      sig_in       : IN STD_LOGIC;		-- signal input
      ext_in       : IN STD_LOGIC;		-- external input port
      serial_mode  : IN STD_LOGIC;		-- serial shift mode enable  
      si           : IN STD_LOGIC;		-- scan input
      shift        : IN STD_LOGIC;		-- 1'b1=shift in data from si into scan flop
      -- 1'b0=load data from sig_in into scan flop
      mdio_dis     : IN STD_LOGIC;		-- 1'b1=choose ext_in to the sig_out mux
      -- 1'b0=choose so to the sign_out mux
      sig_out      : OUT STD_LOGIC;		-- signal output
      so           : OUT STD_LOGIC		-- scan output
   );
END cycloneiv_hssi_cmu_dprio_bit;

ARCHITECTURE trans OF cycloneiv_hssi_cmu_dprio_bit IS
   
   SIGNAL cram_int : STD_LOGIC;
   SIGNAL set_int  : STD_LOGIC;
   
   -- Declare intermediate signals for referenced outputs
   SIGNAL so_xhdl0 : STD_LOGIC;
BEGIN
   -- Drive referenced outputs
   so <= so_xhdl0;
   
   -- select signal output
   sig_out <= (so_xhdl0 AND NOT(shift)) WHEN (serial_mode = '1') ELSE
              (cram_int);
   cram_int <= (ext_in) WHEN (mdio_dis = '1') ELSE
               (so_xhdl0);
   
   -- Set signal for the flop
   set_int <= '0' WHEN (shift = '1' OR reset = '1') ELSE
              ext_in;
   
   -- scan flop
   PROCESS (reset, set_int, clk)
VARIABLE  txt : LINE;
   BEGIN
      IF (reset = '1') THEN
         so_xhdl0 <= '0';
      ELSIF (set_int = '1') THEN
         so_xhdl0 <= '1';
      ELSIF (clk'EVENT AND clk = '1') THEN
         IF ((shift AND serial_mode) = '1') THEN
            so_xhdl0 <= si;
         ELSE
            
            so_xhdl0 <= sig_in;
         END IF;
      END IF;
   END PROCESS;
   
END trans;




LIBRARY ieee;
USE ieee.std_logic_1164.all;
USE ieee.std_logic_arith.all;
USE ieee.std_logic_unsigned.all;
LIBRARY STD;
USE STD.textio.ALL;
USE work.cycloneiv_hssi_components.all;

ENTITY cycloneiv_hssi_cmu_dprio_bit_pma IS
   PORT (
      
      reset          : IN STD_LOGIC;		-- reset
      clk            : IN STD_LOGIC;		-- clock
      sig_in         : IN STD_LOGIC;		-- signal input
      ext_in         : IN STD_LOGIC;		-- external input port
      serial_mode    : IN STD_LOGIC;		-- serial shift mode enable  
      si             : IN STD_LOGIC;		-- scan input
      shift          : IN STD_LOGIC;		-- 1'b1=shift in data from si into scan flop
      -- 1'b0=load data from sig_in into scan flop
      mdio_dis       : IN STD_LOGIC;		-- 1'b1=choose ext_in to the sig_out mux
      -- 1'b0=choose so to the sign_out mux
      pma_cram_test  : IN STD_LOGIC;		--1'b1: choose the previous output of this register
      --1'b0: choose either si or input from DPRIO SM (sig_in)
      sig_out        : OUT STD_LOGIC;		-- signal output
      so             : OUT STD_LOGIC		-- scan output
   );
END cycloneiv_hssi_cmu_dprio_bit_pma;

ARCHITECTURE trans OF cycloneiv_hssi_cmu_dprio_bit_pma IS
   
   SIGNAL cram_int      : STD_LOGIC;
   SIGNAL set_int       : STD_LOGIC;
   
   -- Declare intermediate signals for referenced outputs
   SIGNAL sig_out_xhdl0 : STD_LOGIC;
   SIGNAL so_xhdl1      : STD_LOGIC;
BEGIN
   -- Drive referenced outputs
   sig_out <= sig_out_xhdl0;
   so <= so_xhdl1;
   
   -- select signal output
   sig_out_xhdl0 <= (so_xhdl1 AND NOT(shift)) WHEN (serial_mode = '1') ELSE
                    (cram_int);
   cram_int <= (ext_in) WHEN (mdio_dis = '1') ELSE
               (so_xhdl1);
   
   -- Set signal for the flop
   set_int <= '0' WHEN (shift = '1'OR reset = '1') ELSE
              ext_in;
   
   -- scan flop
   PROCESS (reset, set_int, clk)
VARIABLE  txt : LINE;
   BEGIN
      IF (reset = '1') THEN
         so_xhdl1 <= '0';
      ELSIF (set_int = '1') THEN
         so_xhdl1 <= '1';
      ELSIF (clk'EVENT AND clk = '1') THEN
         IF (pma_cram_test = '1') THEN
            so_xhdl1 <= sig_out_xhdl0;
         ELSIF ((shift AND serial_mode) = '1') THEN
            so_xhdl1 <= si;
         ELSE
            
            so_xhdl1 <= sig_in;
         END IF;
      END IF;
   END PROCESS;
   
END trans;




