   SIGNAL rtx_ob_pdb                : STD_LOGIC;		-- TX Power down CRAM (1: normal operation, 0: power down)
   
   --Serializer - Clock Generation Block (SER-CGB) CRAMs
   SIGNAL rcgb_x_en                 : STD_LOGIC_VECTOR(1 DOWNTO 0);		-- Single channel mode (X1 mode) enable CRAM (individual clock drives individual Serializer)
   SIGNAL rcgb_cmu_sel              : STD_LOGIC;		-- CMU selection CRAM in CLKGENBUF_6G block
   SIGNAL rcgb_m_sel                : STD_LOGIC_VECTOR(1 DOWNTO 0);		-- Division ratio selection CRAM for input clock in CLKGENBU /net/grouse/nobackup F_6G block
   SIGNAL rpma_doublewidth_tx       : STD_LOGIC;		-- TX PCS to TX PMA double data width (16/20) enable CRAM (S2GX RPMA_DOUBLEWIDTH_TX)
   SIGNAL rpmadwidth_tx             : STD_LOGIC;		-- TX PCS to TX PMA data width (8/10)selection CRAM (S2GX RPMADWIDTH_TX)
   SIGNAL rcgb_delay_sel            : STD_LOGIC;		-- Insert 6 gates delay CRAM for CLKMUX in TX channel
   SIGNAL rs_lpbk                   : STD_LOGIC;		-- reverse loop back control CRAM
