   SIGNAL rpclksel                  : STD_LOGIC;		-- 0: select local pclk, 1: select global pclk
   SIGNAL rtx_cgb_pdb               : STD_LOGIC;		-- Power down CRAM for CLKGENBUF, CLKMUX, and Serializer in TX channel (1: normal operation)
   
