   SIGNAL rimpctrl                  : STD_LOGIC;		-- Control calibration bi-direction buffer
   SIGNAL rrx_refclk                : STD_LOGIC;		-- RAM bit to choose RX clock to train CDR
   SIGNAL rpcs_sd_sel               : STD_LOGIC;		-- 0: select analog signal detect output, 1: select digital signal detect output
   
