   SIGNAL radce_adapt               : STD_LOGIC;		-- This signal is used in conjunction with ADCE_PDB
   SIGNAL rrgen_set                 : STD_LOGIC_VECTOR(2 DOWNTO 0);		-- These are the 3 MSB bits controlling the D2A
   SIGNAL rclkdiv                   : STD_LOGIC_VECTOR(3 DOWNTO 0);		-- Effective division ratio for LFCLK and HFCLK
   SIGNAL rhyst_lf                  : STD_LOGIC_VECTOR(2 DOWNTO 0);		-- Sets low-frequency path programmable digital filtering. When set to 000 the digital filter is bypassed.
   SIGNAL rdc_freq                  : STD_LOGIC_VECTOR(1 DOWNTO 0);		-- Sets corner frequency for the DC block.
   SIGNAL rhyst_hf                  : STD_LOGIC_VECTOR(2 DOWNTO 0);		-- Sets high-frequency path programmable digital filtering. When set to 000 the digital filter is bypassed.
   SIGNAL rf_lpf                    : STD_LOGIC_VECTOR(1 DOWNTO 0);		-- Sets corner frequency for the LPF.
   SIGNAL rf_hpf                    : STD_LOGIC_VECTOR(1 DOWNTO 0);		-- Sets corner frequency for the HPF.
   SIGNAL rrgen_vod                 : STD_LOGIC_VECTOR(2 DOWNTO 0);		-- Sets RGEN amplitude
   SIGNAL rrgen_bw                  : STD_LOGIC_VECTOR(1 DOWNTO 0);		-- Sets corner frequency of RGEN.
   SIGNAL rrect_adj                 : STD_LOGIC_VECTOR(1 DOWNTO 0);		-- Sets rectifier leaker and amplifier current.
   SIGNAL rd2a_res                  : STD_LOGIC_VECTOR(1 DOWNTO 0);		-- Sets the D2A resolution. Default is 8 bit resolution. Adaptation time may be faster for lower resolution, but jitter may be increased.
   SIGNAL rlf_os                    : STD_LOGIC_VECTOR(3 DOWNTO 0);		-- These bits are for characterization purposes only. These bits will allow cancellation of systematic offset in the low frequency loop
   SIGNAL rhf_os                    : STD_LOGIC_VECTOR(3 DOWNTO 0);		-- These bits are for characterization purposes only. These bits will allow cancellation of systematic offset in the high frequency loop. 
   SIGNAL radce_rst                 : STD_LOGIC;		-- Presets counters in adaptive engine
   SIGNAL radce_pdb                 : STD_LOGIC;		-- Used in conjunction with RADCE_ADAPT
