   SIGNAL radce_lflck               : STD_LOGIC_VECTOR(14 DOWNTO 0);		-- These bits are used in the adapt_done macro
   SIGNAL radce_digital             : STD_LOGIC_VECTOR(9 DOWNTO 0);		-- Reserved bits
   
