LIBRARY ieee;
USE ieee.std_logic_1164.all;
--USE ieee.std_logic_arith.all;
USE ieee.std_logic_unsigned.all;
LIBRARY STD;
USE STD.textio.ALL;
USE work.cycloneiv_hssi_components.all;

ENTITY cycloneiv_hssi_cmu_dprio_status IS
   GENERIC (
      
      XGXS_STATUS1            : INTEGER := 24580;
      XGXS_STATUS2            : INTEGER := 24581;
      XGXS_LANE_STATUS        : INTEGER := 24582
   );
   PORT (
      mdio_rst                : IN STD_LOGIC;
      mdio_rd                 : IN STD_LOGIC;
      reg_addr                : IN STD_LOGIC_VECTOR(15 DOWNTO 0);
      dev_addr_0              : IN STD_LOGIC;
      mdc                     : IN STD_LOGIC;
      serial_mode             : IN STD_LOGIC;
      ser_shift_load          : IN STD_LOGIC;
      si                      : IN STD_LOGIC;
      mbus_out_ch0            : IN STD_LOGIC_VECTOR(15 DOWNTO 0);
      mbus_out_ch1            : IN STD_LOGIC_VECTOR(15 DOWNTO 0);
      mbus_out_ch2            : IN STD_LOGIC_VECTOR(15 DOWNTO 0);
      mbus_out_ch3            : IN STD_LOGIC_VECTOR(15 DOWNTO 0);
      mbus_out_centrl         : IN STD_LOGIC_VECTOR(15 DOWNTO 0);
      
      -- Status inputs
      align_status            : IN STD_LOGIC;
      sync_status             : IN STD_LOGIC_VECTOR(3 DOWNTO 0);
      xs_link_status          : IN STD_LOGIC;
      rx_local_fault          : IN STD_LOGIC;
      tx_local_fault          : IN STD_LOGIC;
      -- Outputs
      rxs_link_status_set     : OUT STD_LOGIC;
      rtx_rx_local_fault_clr  : OUT STD_LOGIC;
      mbus_out                : OUT STD_LOGIC_VECTOR(15 DOWNTO 0);
      so                      : OUT STD_LOGIC
   );
END cycloneiv_hssi_cmu_dprio_status;

ARCHITECTURE trans OF cycloneiv_hssi_cmu_dprio_status IS
   COMPONENT cycloneiv_hssi_cmu_dprio_bit
      PORT (
         reset                   : IN STD_LOGIC;
         clk                     : IN STD_LOGIC;
         sig_in                  : IN STD_LOGIC;
         ext_in                  : IN STD_LOGIC;
         serial_mode             : IN STD_LOGIC;
         si                      : IN STD_LOGIC;
         shift                   : IN STD_LOGIC;
         mdio_dis                : IN STD_LOGIC;
         sig_out                 : OUT STD_LOGIC;
         so                      : OUT STD_LOGIC
      );
   END COMPONENT;
   
   
   SIGNAL chain                        : STD_LOGIC;
   SIGNAL xs_link_status_rd            : STD_LOGIC;
   SIGNAL tx_rx_local_fault_status_rd  : STD_LOGIC;
   SIGNAL local_fault                  : STD_LOGIC;
   SIGNAL xs_tx_local_fault            : STD_LOGIC;
   SIGNAL xs_rx_local_fault            : STD_LOGIC;
   SIGNAL xgxs_stat1_reg               : STD_LOGIC_VECTOR(15 DOWNTO 0);
   SIGNAL xgxs_stat2_reg               : STD_LOGIC_VECTOR(15 DOWNTO 0);
   SIGNAL xgxs_lane_stat_reg           : STD_LOGIC_VECTOR(15 DOWNTO 0);
   
   -- Declare intermediate signals for referenced outputs
   SIGNAL rxs_link_status_set_xhdl1    : STD_LOGIC;
   SIGNAL rtx_rx_local_fault_clr_xhdl0 : STD_LOGIC;
   SIGNAL so_xhdl2                     : STD_LOGIC;
BEGIN
   -- Drive referenced outputs
   rxs_link_status_set <= rxs_link_status_set_xhdl1;
   rtx_rx_local_fault_clr <= rtx_rx_local_fault_clr_xhdl0;
   so <= so_xhdl2;
   
   -- Status register address parameters
   
   -- XGXS_STATUS1 and XGXS_STATUS2 status registers
   xs_link_status_rd <= mdio_rd AND int2bit(reg_addr = ieee.std_logic_arith.CONV_STD_LOGIC_VECTOR(XGXS_STATUS1, 16));
   tx_rx_local_fault_status_rd <= mdio_rd AND int2bit(reg_addr = ieee.std_logic_arith.CONV_STD_LOGIC_VECTOR(XGXS_STATUS2, 16));
   
   -- Status registers
   local_fault <= tx_local_fault OR rx_local_fault;
   xs_tx_local_fault <= tx_local_fault WHEN (dev_addr_0 = '1') ELSE
                        rx_local_fault;
   xs_rx_local_fault <= rx_local_fault WHEN (dev_addr_0 = '1') ELSE
                        tx_local_fault;
   
   xgxs_stat1_reg <= ("00000000" & local_fault & "0000" & xs_link_status & "10");
   xgxs_stat2_reg <= ("1000" & xs_rx_local_fault & xs_tx_local_fault & "0000000000");
   xgxs_lane_stat_reg <= ("000" & align_status & "11000000" & sync_status);
   
   -- Single control bits
   
   
   xs_link_status_set : cycloneiv_hssi_cmu_dprio_bit
      PORT MAP (
         reset        => mdio_rst,
         clk          => mdc,
         sig_in       => xs_link_status_rd,
         ext_in       => '0',
         serial_mode  => serial_mode,
         si           => si,
         shift        => ser_shift_load,
         mdio_dis     => '0',
         sig_out      => rxs_link_status_set_xhdl1,
         so           => chain
      );
   
   
   
   tx_rx_local_fault_clr : cycloneiv_hssi_cmu_dprio_bit
      PORT MAP (
         reset        => mdio_rst,
         clk          => mdc,
         sig_in       => tx_rx_local_fault_status_rd,
         ext_in       => '0',
         serial_mode  => serial_mode,
         si           => chain,
         shift        => ser_shift_load,
         mdio_dis     => '0',
         sig_out      => rtx_rx_local_fault_clr_xhdl0,
         so           => so_xhdl2
      );
   
      mbus_out <= 
                  xgxs_stat1_reg WHEN      (reg_addr = XGXS_STATUS1)         else 
                  xgxs_stat2_reg WHEN      (reg_addr = XGXS_STATUS2)         else  
                  xgxs_lane_stat_reg WHEN  (reg_addr = XGXS_LANE_STATUS)     else 
                                       -- Muxing for Central PCS registers
                   mbus_out_centrl WHEN    (reg_addr = (X"6000" + X"0000")) else
                   mbus_out_centrl WHEN    (reg_addr = (X"6000" + X"0001")) else
                   mbus_out_centrl WHEN    (reg_addr = (X"6000" + X"0002")) else
                   mbus_out_centrl WHEN    (reg_addr = (X"6000" + X"0003")) else
                                       -- Muxing for CMU PMA registers
                   mbus_out_centrl WHEN    (reg_addr = (X"4800" + X"0000")) else
                   mbus_out_centrl WHEN    (reg_addr = (X"4800" + X"0001")) else
                   mbus_out_centrl WHEN    (reg_addr = (X"4800" + X"0002")) else
                   mbus_out_centrl WHEN    (reg_addr = (X"4800" + X"0003")) else
                   mbus_out_centrl WHEN    (reg_addr = (X"4800" + X"0004")) else
                   mbus_out_centrl WHEN    (reg_addr = (X"4800" + X"0005")) else
                   mbus_out_centrl WHEN    (reg_addr = (X"4800" + X"0006")) else
                   mbus_out_centrl WHEN	   (reg_addr = (X"4800" + X"0007")) else	  
                   mbus_out_centrl WHEN    (reg_addr = (X"4C00" + X"0000")) else
                   mbus_out_centrl WHEN    (reg_addr = (X"4C00" + X"0001")) else
                   mbus_out_centrl WHEN    (reg_addr = (X"4C00" + X"0002")) else
                   mbus_out_centrl WHEN    (reg_addr = (X"4C00" + X"0003")) else
                   mbus_out_centrl WHEN    (reg_addr = (X"4C00" + X"0004")) else                           
                   mbus_out_centrl WHEN    (reg_addr = (X"4C00" + X"0005")) else
