                   mbus_out_centrl WHEN	   (reg_addr = (X"5C00" + X"000C")) else	                                      
                                       -- Muxing for PCS channel0 registers
                   mbus_out_ch0 WHEN       (reg_addr = (X"0000" + X"0000")) else
