-- types ---------------------------------------------------------------
type DPRIO_REG_ARRAY_OF_INT is array (natural range <>) of integer;
type DPRIO_REG_ARRAY_OF_VEC is array (natural range <>) of std_logic_vector(4 downto 0);
type DPRIO_REG_ARRAY_OF_VEC1 is array (natural range <>) of std_logic;
type DPRIO_REG_ARRAY_OF_VEC2 is array (natural range <>) of std_logic_vector(1 downto 0);

-- common functions ----------------------------------------------------
FUNCTION dprio_reg_to_int(arg : IN STD_LOGIC_VECTOR) RETURN INTEGER IS
    VARIABLE result : INTEGER;
BEGIN
    result := 0;
    FOR i IN arg'RANGE LOOP
       IF arg(i) = '1' THEN
           result := result + 2**i;
       END IF;
    END LOOP;
    RETURN result;
END dprio_reg_to_int;
   
---------------------------------------------------------------------------
-- PLL clock selection ----------------------------------------------------  
---------------------------------------------------------------------------

constant PLL_CLOCK_SELECT_CLKREFCLK0        : INTEGER := 0;
constant PLL_CLOCK_SELECT_CLKREFCLK1        : INTEGER := 1;
constant PLL_CLOCK_SELECT_IQ2               : INTEGER := 2;
constant PLL_CLOCK_SELECT_IQ3               : INTEGER := 3;
constant PLL_CLOCK_SELECT_IQ4               : INTEGER := 4;
constant PLL_CLOCK_SELECT_IQ5               : INTEGER := 5;
constant PLL_CLOCK_SELECT_IQ6               : INTEGER := 6;
constant PLL_CLOCK_SELECT_IQ7               : INTEGER := 7;
constant PLL_CLOCK_SELECT_PLD_CLK           : INTEGER := 8;
constant PLL_CLOCK_SELECT_GPLL_CLK          : INTEGER := 9;
constant PLL_CLOCK_SELECT_ERR               : INTEGER := 10;

FUNCTION convert_pll_clock_cram_to_phyport (
    rrefclk_sel : IN STD_LOGIC_VECTOR(1 DOWNTO 0);
    pldiq       : IN STD_LOGIC_VECTOR(1 DOWNTO 0)) RETURN INTEGER IS
    
    VARIABLE res : INTEGER := PLL_CLOCK_SELECT_ERR;
    VARIABLE tmp_in : STD_LOGIC_VECTOR(3 DOWNTO 0) := "0000";
BEGIN
    tmp_in := rrefclk_sel & pldiq;
    if (rrefclk_sel = "00") THEN
        res := PLL_CLOCK_SELECT_CLKREFCLK0; 
    ELSIF (rrefclk_sel = "01") THEN
        res := PLL_CLOCK_SELECT_CLKREFCLK1;
    ELSE
        CASE tmp_in IS
            WHEN "1000" => res := PLL_CLOCK_SELECT_IQ2;
            WHEN "1001" => res := PLL_CLOCK_SELECT_IQ3;
            WHEN "1010" => res := PLL_CLOCK_SELECT_IQ4;
            WHEN "1100" => res := PLL_CLOCK_SELECT_IQ5;
            WHEN "1101" => res := PLL_CLOCK_SELECT_IQ6;
            WHEN "1110" => res := PLL_CLOCK_SELECT_IQ7;
            WHEN "1011" => res := PLL_CLOCK_SELECT_PLD_CLK;
            WHEN "1111" => res := PLL_CLOCK_SELECT_GPLL_CLK; 
            WHEN OTHERS => res := PLL_CLOCK_SELECT_ERR;
         END CASE;
    END IF;
      
    RETURN res;
END convert_pll_clock_cram_to_phyport;

-- input is at most 15 characters
FUNCTION convert_pll_phyport_str_to_phyport_enum (
    phyport_str : IN STRING) RETURN INTEGER IS
    VARIABLE res : INTEGER := 0;
BEGIN
    IF (phyport_str = "iq2") THEN
        res := PLL_CLOCK_SELECT_IQ2;
    ELSIF (phyport_str = "iq3") THEN
        res := PLL_CLOCK_SELECT_IQ3;
    ELSIF (phyport_str = "iq4") THEN
        res := PLL_CLOCK_SELECT_IQ4;
    ELSIF (phyport_str = "iq5") THEN
        res := PLL_CLOCK_SELECT_IQ5;
    ELSIF (phyport_str = "iq6") THEN
        res := PLL_CLOCK_SELECT_IQ6;
    ELSIF (phyport_str = "iq7") THEN
        res := PLL_CLOCK_SELECT_IQ7;
    ELSIF (phyport_str = "refclk0" OR phyport_str = "clkrefclk0") THEN
        res := PLL_CLOCK_SELECT_CLKREFCLK0;
    ELSIF (phyport_str = "refclk1" OR phyport_str = "clkrefclk1") THEN
        res := PLL_CLOCK_SELECT_CLKREFCLK1;
    ELSIF (phyport_str = "pld_clk") THEN
        res := PLL_CLOCK_SELECT_PLD_CLK;
    ELSIF (phyport_str = "gpll_clk") THEN
        res := PLL_CLOCK_SELECT_GPLL_CLK;
    ELSE  -- like "none"
        res := PLL_CLOCK_SELECT_ERR;
    END IF;
         
    RETURN res;
END convert_pll_phyport_str_to_phyport_enum;

