---------------------------------------------------------------------------
-- TX PMA selection -------------------------------------------------------  
---------------------------------------------------------------------------

constant TXPMA_CLKIN_SELECT_X1         : INTEGER := 0;
constant TXPMA_CLKIN_SELECT_X4         : INTEGER := 1;
constant TXPMA_CLKIN_SELECT_XN_TOP     : INTEGER := 2;
constant TXPMA_CLKIN_SELECT_XN_BOTTOM  : INTEGER := 3;
constant TXPMA_CLKIN_SELECT_HT         : INTEGER := 4;
constant TXPMA_CLKIN_SELECT_ERR        : INTEGER := 7;

FUNCTION convert_txpma_clock_cram_to_phyport (
             rcgb_x_en : IN STD_LOGIC_VECTOR(1 DOWNTO 0)) RETURN INTEGER IS
      VARIABLE res : INTEGER := 0;
BEGIN
    CASE rcgb_x_en IS
        WHEN "00"     =>  res := TXPMA_CLKIN_SELECT_X1; 
        WHEN "01"     =>  res := TXPMA_CLKIN_SELECT_X4;
        WHEN "10"     =>  res := TXPMA_CLKIN_SELECT_XN_TOP;
        WHEN "11"     =>  res := TXPMA_CLKIN_SELECT_XN_BOTTOM;
        WHEN OTHERS   =>  res := TXPMA_CLKIN_SELECT_ERR;
    END CASE;
      
    RETURN res;
END convert_txpma_clock_cram_to_phyport;

-- input is at most 20 characters
FUNCTION convert_txpma_phyport_str_to_phyport_enum (
             phyport_str : IN STRING ) RETURN INTEGER IS
             
    VARIABLE res : INTEGER := 0;
BEGIN
    IF (phyport_str = "x1" OR phyport_str = "X1") THEN
        res := TXPMA_CLKIN_SELECT_X1;
    ELSIF (phyport_str = "x4" OR phyport_str = "X4") THEN
        res := TXPMA_CLKIN_SELECT_X4;
    ELSIF (phyport_str = "xn_top" OR phyport_str = "XN_TOP") THEN
        res := TXPMA_CLKIN_SELECT_XN_TOP;
    ELSIF (phyport_str = "xn_bottom" OR phyport_str = "XN_BOTTOM") THEN
        res := TXPMA_CLKIN_SELECT_XN_BOTTOM;
    ELSIF (phyport_str = "hypertransport" OR phyport_str = "HYPERTRANSPORT") THEN
        res := TXPMA_CLKIN_SELECT_HT;
    ELSE  -- like "none"
        res := TXPMA_CLKIN_SELECT_ERR;
    END IF;
         
    RETURN res;
END convert_txpma_phyport_str_to_phyport_enum;

