---------------------------------------------------------------------------
-- PLL0/PLL1 selection ----------------------------------------------------  
---------------------------------------------------------------------------

constant CLKDIV_INCLK_SELECT_PLL0     : INTEGER := 0;
constant CLKDIV_INCLK_SELECT_PLL1     : INTEGER := 1;
constant CLKDIV_INCLK_SELECT_ERR      : INTEGER := 2;

FUNCTION convert_clkdiv_pll_cram_to_phyport (
    rcgb_cmu_sel : IN STD_LOGIC) RETURN INTEGER IS
       
    VARIABLE res : INTEGER := 0;
BEGIN
    CASE rcgb_cmu_sel IS
        WHEN '0'    =>    res := CLKDIV_INCLK_SELECT_PLL0; 
        WHEN '1'    =>    res := CLKDIV_INCLK_SELECT_PLL1; 
        WHEN OTHERS =>    res := CLKDIV_INCLK_SELECT_ERR;
    END CASE;
      
    RETURN res;
END convert_clkdiv_pll_cram_to_phyport;

FUNCTION convert_clkdiv_pll_phyport_str_to_phyport_enum(
    phyport_str : IN STRING) RETURN INTEGER IS

    VARIABLE res : INTEGER := 0;
BEGIN
    IF (phyport_str = "pll0") THEN
        res := CLKDIV_INCLK_SELECT_PLL0;
    ELSIF (phyport_str = "pll1") THEN
        res := CLKDIV_INCLK_SELECT_PLL1;
    ELSE  -- like "none"
        res := CLKDIV_INCLK_SELECT_ERR;
    END IF;
         
    RETURN res;

END convert_clkdiv_pll_phyport_str_to_phyport_enum;

