    pll4_clock_index_to_phyport(2) <= tmp_int;
    tmp_int := convert_pll_phyport_str_to_phyport_enum(pll4_inclk3_logical_to_physical_mapping);
    pll4_clock_index_to_phyport(3) <= tmp_int;
    tmp_int := convert_pll_phyport_str_to_phyport_enum(pll4_inclk4_logical_to_physical_mapping);
    pll4_clock_index_to_phyport(4) <= tmp_int;
    tmp_int := convert_pll_phyport_str_to_phyport_enum(pll4_inclk5_logical_to_physical_mapping);
    pll4_clock_index_to_phyport(5) <= tmp_int;
