    pll5_clock_index_to_phyport(5) <= tmp_int;
    tmp_int := convert_pll_phyport_str_to_phyport_enum(pll5_inclk6_logical_to_physical_mapping);
    pll5_clock_index_to_phyport(6) <= tmp_int;
