    pll5_clock_index_to_phyport(9) <= tmp_int;
      
    init_table := '0';
   END IF;
    
   WAIT; 
END PROCESS;  -- end of initializing tables

-- DPRIO read - logical pll channel
tmp_pll0_clock_select_vec <= pll0_init_pfd_clk_sel WHEN 
                             ( (pll0_init_pfd_clk_sel(0) = '0' OR pll0_init_pfd_clk_sel(0) = '1') AND
                               (pll0_init_pfd_clk_sel(1) = '0' OR pll0_init_pfd_clk_sel(1) = '1') AND
                               (pll0_init_pfd_clk_sel(2) = '0' OR pll0_init_pfd_clk_sel(2) = '1') AND
                               (pll0_init_pfd_clk_sel(3) = '0' OR pll0_init_pfd_clk_sel(3) = '1')) ELSE
                             "0000";
                              
pll0_clock_select  <= dprio_reg_to_int(tmp_pll0_clock_select_vec);
pll0_clock_phyport <= pll0_clock_index_to_phyport(pll0_clock_select);
                            
pll0_clock_cram    <= pll_clock_phyport_to_cram(pll0_clock_phyport);

-- switch to physical pll number
pll0_clock_cram_phy <= pll0_clock_cram WHEN (pll0_logical_to_physical_mapping = 0)  ELSE
                       pll1_clock_cram WHEN (pll1_logical_to_physical_mapping = 0) ELSE
                       pll2_clock_cram WHEN (pll2_logical_to_physical_mapping = 0) ELSE
                       pll3_clock_cram WHEN (pll3_logical_to_physical_mapping = 0) ELSE
                       pll4_clock_cram WHEN (pll4_logical_to_physical_mapping = 0) ELSE
                       pll5_clock_cram WHEN (pll5_logical_to_physical_mapping = 0) ELSE
                       pll0_clock_cram;
                            
pll0_csr_riqclk_sel  <= pll0_clock_cram_phy(1 DOWNTO 0); 
pll0_csr_rrefclk_sel <= pll0_clock_cram_phy(4 DOWNTO 3); 

-- DPRIO write - CRAM on physical 
pll0_clock_phyport_out <= convert_pll_clock_cram_to_phyport(pll0_dp_rrefclk_sel, pll0_dp_riqclk_sel);
       -- but the map is on logic channel 
pll0_clock_phyport_out_logic <= pll0_clock_phyport_out WHEN (pll0_logical_to_physical_mapping = 0) ELSE 
                                pll1_clock_phyport_out WHEN (pll0_logical_to_physical_mapping = 1) ELSE
                                pll2_clock_phyport_out WHEN (pll0_logical_to_physical_mapping = 2) ELSE
                                pll3_clock_phyport_out WHEN (pll0_logical_to_physical_mapping = 3) ELSE
                                pll4_clock_phyport_out WHEN (pll0_logical_to_physical_mapping = 4) ELSE
                                pll5_clock_phyport_out WHEN (pll0_logical_to_physical_mapping = 5) ELSE
                                pll0_clock_phyport_out;

pll0_clock_select_out_logic <=  "0000" WHEN (pll0_clock_index_to_phyport(0) = pll0_clock_phyport_out_logic) ELSE 
                                "0001" WHEN (pll0_clock_index_to_phyport(1) = pll0_clock_phyport_out_logic) ELSE 
                                "0010" WHEN (pll0_clock_index_to_phyport(2) = pll0_clock_phyport_out_logic) ELSE 
                                "0011" WHEN (pll0_clock_index_to_phyport(3) = pll0_clock_phyport_out_logic) ELSE 
                                "0100" WHEN (pll0_clock_index_to_phyport(4) = pll0_clock_phyport_out_logic) ELSE 
                                "0101" WHEN (pll0_clock_index_to_phyport(5) = pll0_clock_phyport_out_logic) ELSE 
                                "0110" WHEN (pll0_clock_index_to_phyport(6) = pll0_clock_phyport_out_logic) ELSE 
                                "0111" WHEN (pll0_clock_index_to_phyport(7) = pll0_clock_phyport_out_logic) ELSE 
