-- TXPMA clock selection --------------------------------------------------  
---------------------------------------------------------------------------

PROCESS  -- initialize the TABLE
  VARIABLE init_table                : STD_LOGIC := '1';  
  VARIABLE tmp_int                   : INTEGER := 0; 
        
  BEGIN
  IF (init_table = '1') THEN
    txpma_clock_phyport_to_cram(TXPMA_CLKIN_SELECT_X1)        <= "00";
    txpma_clock_phyport_to_cram(TXPMA_CLKIN_SELECT_X4)        <= "01";
    txpma_clock_phyport_to_cram(TXPMA_CLKIN_SELECT_XN_TOP)    <= "10";
    txpma_clock_phyport_to_cram(TXPMA_CLKIN_SELECT_XN_BOTTOM) <= "11";
