-- PLL0/PLL1 selection ----------------------------------------------------  
---------------------------------------------------------------------------

PROCESS  -- initialize the TABLE
  VARIABLE init_table                : STD_LOGIC := '1';  
  VARIABLE tmp_int                   : INTEGER := 0; 
        
  BEGIN
  IF (init_table = '1') THEN
    clkdiv_pll_phyport_to_cram(CLKDIV_INCLK_SELECT_PLL0)    <= '0';
    clkdiv_pll_phyport_to_cram(CLKDIV_INCLK_SELECT_PLL1)    <= '1';
    clkdiv_pll_phyport_to_cram(CLKDIV_INCLK_SELECT_ERR)     <= '1';  
      
    tmp_int := convert_clkdiv_pll_phyport_str_to_phyport_enum(clkdiv0_inclk0_logical_to_physical_mapping);
    clkdiv0_pll_index_to_phyport(0) <= tmp_int;
    tmp_int := convert_clkdiv_pll_phyport_str_to_phyport_enum(clkdiv0_inclk1_logical_to_physical_mapping);
    clkdiv0_pll_index_to_phyport(1) <= tmp_int;
      
    tmp_int := convert_clkdiv_pll_phyport_str_to_phyport_enum(clkdiv1_inclk0_logical_to_physical_mapping);
    clkdiv1_pll_index_to_phyport(0) <= tmp_int;
    tmp_int := convert_clkdiv_pll_phyport_str_to_phyport_enum(clkdiv1_inclk1_logical_to_physical_mapping);
    clkdiv1_pll_index_to_phyport(1) <= tmp_int;
      
    tmp_int := convert_clkdiv_pll_phyport_str_to_phyport_enum(clkdiv2_inclk0_logical_to_physical_mapping);
    clkdiv2_pll_index_to_phyport(0) <= tmp_int;
    tmp_int := convert_clkdiv_pll_phyport_str_to_phyport_enum(clkdiv2_inclk1_logical_to_physical_mapping);
    clkdiv2_pll_index_to_phyport(1) <= tmp_int;
      
    tmp_int := convert_clkdiv_pll_phyport_str_to_phyport_enum(clkdiv3_inclk0_logical_to_physical_mapping);
    clkdiv3_pll_index_to_phyport(0) <= tmp_int;
    tmp_int := convert_clkdiv_pll_phyport_str_to_phyport_enum(clkdiv3_inclk1_logical_to_physical_mapping);
    clkdiv3_pll_index_to_phyport(1) <= tmp_int;
      
    tmp_int := convert_clkdiv_pll_phyport_str_to_phyport_enum(clkdiv4_inclk0_logical_to_physical_mapping);
    clkdiv4_pll_index_to_phyport(0) <= tmp_int;
    tmp_int := convert_clkdiv_pll_phyport_str_to_phyport_enum(clkdiv4_inclk1_logical_to_physical_mapping);
    clkdiv4_pll_index_to_phyport(1) <= tmp_int;
      
    tmp_int := convert_clkdiv_pll_phyport_str_to_phyport_enum(clkdiv5_inclk0_logical_to_physical_mapping);
    clkdiv5_pll_index_to_phyport(0) <= tmp_int;
    tmp_int := convert_clkdiv_pll_phyport_str_to_phyport_enum(clkdiv5_inclk1_logical_to_physical_mapping);
    clkdiv5_pll_index_to_phyport(1) <= tmp_int;
      
    init_table := '0';
   END IF;
    
   WAIT; 
END PROCESS;  -- end of initializing tables

-- DPRIO read - logical clkdiv channel
tmp_clkdiv0_pll_select  <= clkdiv0_init_inclk_select WHEN (clkdiv0_init_inclk_select = '0' OR clkdiv0_init_inclk_select = '1') ELSE '0';
