                          clkdiv5_pll_select_out_logic WHEN (tx5_logical_to_physical_mapping = 3) ELSE
                          clkdiv3_pll_select_out_logic;
                               
clkdiv3_dp_inclk_select <= clkdiv3_pll_select_out;  


-- DPRIO read - logical clkdiv channel
tmp_clkdiv4_pll_select  <= clkdiv4_init_inclk_select WHEN (clkdiv4_init_inclk_select = '0' OR clkdiv4_init_inclk_select = '1') ELSE '0';
clkdiv4_pll_select      <= 0 WHEN (tmp_clkdiv4_pll_select = '0') ELSE 1;
clkdiv4_pll_phyport     <= clkdiv4_pll_index_to_phyport(clkdiv4_pll_select);
                            
clkdiv4_pll_cram    <= clkdiv_pll_phyport_to_cram(clkdiv4_pll_phyport); 

-- switch to physical pll number
clkdiv4_pll_cram_phy <= clkdiv0_pll_cram WHEN (tx0_logical_to_physical_mapping = 4) ELSE 
                        clkdiv1_pll_cram WHEN (tx1_logical_to_physical_mapping = 4) ELSE
                        clkdiv2_pll_cram WHEN (tx2_logical_to_physical_mapping = 4) ELSE
                        clkdiv3_pll_cram WHEN (tx3_logical_to_physical_mapping = 4) ELSE
                        clkdiv4_pll_cram WHEN (tx4_logical_to_physical_mapping = 4) ELSE
                        clkdiv5_pll_cram WHEN (tx5_logical_to_physical_mapping = 4) ELSE
                        clkdiv4_pll_cram;
                            
clkdiv4_csr_rcgb_cmu_sel <= clkdiv4_pll_cram_phy; 

-- DPRIO write - CRAM on physical 
clkdiv4_pll_phyport_out <= convert_clkdiv_pll_cram_to_phyport(clkdiv4_dp_rcgb_cmu_sel);
       -- but the map is on logic channel 
clkdiv4_pll_phyport_out_logic <= clkdiv0_pll_phyport_out WHEN (tx4_logical_to_physical_mapping = 0) ELSE 
                                 clkdiv1_pll_phyport_out WHEN (tx4_logical_to_physical_mapping = 1) ELSE
                                 clkdiv2_pll_phyport_out WHEN (tx4_logical_to_physical_mapping = 2) ELSE
                                 clkdiv3_pll_phyport_out WHEN (tx4_logical_to_physical_mapping = 3) ELSE
                                 clkdiv4_pll_phyport_out WHEN (tx4_logical_to_physical_mapping = 4) ELSE
                                 clkdiv5_pll_phyport_out WHEN (tx4_logical_to_physical_mapping = 5) ELSE
                                 clkdiv4_pll_phyport_out;

clkdiv4_pll_select_out_logic <=  '0' WHEN (clkdiv4_pll_index_to_phyport(0) = clkdiv4_pll_phyport_out_logic) ELSE 
                                 '1' WHEN (clkdiv4_pll_index_to_phyport(1) = clkdiv4_pll_phyport_out_logic) ELSE 
                                 '1';
       -- back to physical
clkdiv4_pll_select_out <= clkdiv0_pll_select_out_logic WHEN (tx0_logical_to_physical_mapping = 4) ELSE 
                          clkdiv1_pll_select_out_logic WHEN (tx1_logical_to_physical_mapping = 4) ELSE
                          clkdiv2_pll_select_out_logic WHEN (tx2_logical_to_physical_mapping = 4) ELSE
                          clkdiv3_pll_select_out_logic WHEN (tx3_logical_to_physical_mapping = 4) ELSE
                          clkdiv4_pll_select_out_logic WHEN (tx4_logical_to_physical_mapping = 4) ELSE
                          clkdiv5_pll_select_out_logic WHEN (tx5_logical_to_physical_mapping = 4) ELSE
                          clkdiv4_pll_select_out_logic;
                               
clkdiv4_dp_inclk_select <= clkdiv4_pll_select_out;  


-- DPRIO read - logical clkdiv channel
tmp_clkdiv5_pll_select  <= clkdiv5_init_inclk_select WHEN (clkdiv5_init_inclk_select = '0' OR clkdiv5_init_inclk_select = '1') ELSE '0';
clkdiv5_pll_select      <= 0 WHEN (tmp_clkdiv5_pll_select = '0') ELSE 1;
clkdiv5_pll_phyport     <= clkdiv5_pll_index_to_phyport(clkdiv5_pll_select);
                            
clkdiv5_pll_cram    <= clkdiv_pll_phyport_to_cram(clkdiv5_pll_phyport); 

-- switch to physical pll number
clkdiv5_pll_cram_phy <= clkdiv0_pll_cram WHEN (tx0_logical_to_physical_mapping = 5) ELSE 
                        clkdiv1_pll_cram WHEN (tx1_logical_to_physical_mapping = 5) ELSE
                        clkdiv2_pll_cram WHEN (tx2_logical_to_physical_mapping = 5) ELSE
                        clkdiv3_pll_cram WHEN (tx3_logical_to_physical_mapping = 5) ELSE
                        clkdiv4_pll_cram WHEN (tx4_logical_to_physical_mapping = 5) ELSE
                        clkdiv5_pll_cram WHEN (tx5_logical_to_physical_mapping = 5) ELSE
                        clkdiv5_pll_cram;
                            
clkdiv5_csr_rcgb_cmu_sel <= clkdiv5_pll_cram_phy; 

-- DPRIO write - CRAM on physical 
clkdiv5_pll_phyport_out <= convert_clkdiv_pll_cram_to_phyport(clkdiv5_dp_rcgb_cmu_sel);
       -- but the map is on logic channel 
clkdiv5_pll_phyport_out_logic <= clkdiv0_pll_phyport_out WHEN (tx5_logical_to_physical_mapping = 0) ELSE 
                                 clkdiv1_pll_phyport_out WHEN (tx5_logical_to_physical_mapping = 1) ELSE
                                 clkdiv2_pll_phyport_out WHEN (tx5_logical_to_physical_mapping = 2) ELSE
                                 clkdiv3_pll_phyport_out WHEN (tx5_logical_to_physical_mapping = 3) ELSE
                                 clkdiv4_pll_phyport_out WHEN (tx5_logical_to_physical_mapping = 4) ELSE
                                 clkdiv5_pll_phyport_out WHEN (tx5_logical_to_physical_mapping = 5) ELSE
                                 clkdiv5_pll_phyport_out;

clkdiv5_pll_select_out_logic <=  '0' WHEN (clkdiv5_pll_index_to_phyport(0) = clkdiv5_pll_phyport_out_logic) ELSE 
                                 '1' WHEN (clkdiv5_pll_index_to_phyport(1) = clkdiv5_pll_phyport_out_logic) ELSE 
                                 '1';
       -- back to physical
clkdiv5_pll_select_out <= clkdiv0_pll_select_out_logic WHEN (tx0_logical_to_physical_mapping = 5) ELSE 
                          clkdiv1_pll_select_out_logic WHEN (tx1_logical_to_physical_mapping = 5) ELSE
                          clkdiv2_pll_select_out_logic WHEN (tx2_logical_to_physical_mapping = 5) ELSE
                          clkdiv3_pll_select_out_logic WHEN (tx3_logical_to_physical_mapping = 5) ELSE
                          clkdiv4_pll_select_out_logic WHEN (tx4_logical_to_physical_mapping = 5) ELSE
                          clkdiv5_pll_select_out_logic WHEN (tx5_logical_to_physical_mapping = 5) ELSE
                          clkdiv5_pll_select_out_logic;
                               
clkdiv5_dp_inclk_select <= clkdiv5_pll_select_out;  

END trans;

