         pma_cram_test                        : IN STD_LOGIC;
         ser_shift_load                       : IN STD_LOGIC;
         si                                   : IN STD_LOGIC;
         csr_chnl_in                          : IN STD_LOGIC_VECTOR(831 DOWNTO 0);
         csr_chnl_in_reserved                 : IN STD_LOGIC_VECTOR(15 DOWNTO 0);
         dprio_chnl_id                        : IN STD_LOGIC_VECTOR(3 DOWNTO 0);
         dp_chnl_out                          : OUT STD_LOGIC_VECTOR(831 DOWNTO 0);
         dp_chnl_out_reserved                 : OUT STD_LOGIC_VECTOR(15 DOWNTO 0);
         so                                   : OUT STD_LOGIC;
         mbus_out                             : OUT STD_LOGIC_VECTOR(15 DOWNTO 0)
      );
   END COMPONENT;
   
   COMPONENT cycloneiv_hssi_cmu_dprio_status
      GENERIC (
         XGXS_STATUS1                         : INTEGER := 24580;
         XGXS_STATUS2                         : INTEGER := 24581;
         XGXS_LANE_STATUS                     : INTEGER := 24582
      );
      PORT (
         mdio_rst                             : IN STD_LOGIC;
         mdio_rd                              : IN STD_LOGIC;
         reg_addr                             : IN STD_LOGIC_VECTOR(15 DOWNTO 0);
         dev_addr_0                           : IN STD_LOGIC;
         mdc                                  : IN STD_LOGIC;
         serial_mode                          : IN STD_LOGIC;
         ser_shift_load                       : IN STD_LOGIC;
         si                                   : IN STD_LOGIC;
         mbus_out_ch0                         : IN STD_LOGIC_VECTOR(15 DOWNTO 0);
         mbus_out_ch1                         : IN STD_LOGIC_VECTOR(15 DOWNTO 0);
         mbus_out_ch2                         : IN STD_LOGIC_VECTOR(15 DOWNTO 0);
         mbus_out_ch3                         : IN STD_LOGIC_VECTOR(15 DOWNTO 0);
         mbus_out_centrl                      : IN STD_LOGIC_VECTOR(15 DOWNTO 0);
         align_status                         : IN STD_LOGIC;
         sync_status                          : IN STD_LOGIC_VECTOR(3 DOWNTO 0);
         xs_link_status                       : IN STD_LOGIC;
         rx_local_fault                       : IN STD_LOGIC;
         tx_local_fault                       : IN STD_LOGIC;
         rxs_link_status_set                  : OUT STD_LOGIC;
         rtx_rx_local_fault_clr               : OUT STD_LOGIC;
         mbus_out                             : OUT STD_LOGIC_VECTOR(15 DOWNTO 0);
         so                                   : OUT STD_LOGIC
      );
   END COMPONENT;
   
   COMPONENT cycloneiv_hssi_cmu_dprio_sm
      GENERIC (
         IDLE                                 : INTEGER := 0;
         PREAMBLE                             : INTEGER := 1;
         CONTROL                              : INTEGER := 2;
         TURN_ARND_0                          : INTEGER := 3;
         TURN_ARND_1                          : INTEGER := 4;
         ADDR_DATA                            : INTEGER := 5;
         ADDR_OP                              : INTEGER := 0;
         WR_OP                                : INTEGER := 1;
         RD_INC_OP                            : INTEGER := 2;
         RD_OP                                : INTEGER := 3
      );
      PORT (
         mdc                                  : IN STD_LOGIC;
         mdio_in                              : IN STD_LOGIC;
         reset                                : IN STD_LOGIC;
         opcode                               : IN STD_LOGIC_VECTOR(1 DOWNTO 0);
         valid_addr                           : IN STD_LOGIC;
         cnt_eq_0                             : IN STD_LOGIC;
         shift_in                             : OUT STD_LOGIC;
         shift_out                            : OUT STD_LOGIC;
         latch_ctl                            : OUT STD_LOGIC;
         incr_addr                            : OUT STD_LOGIC;
         mdio_wr                              : OUT STD_LOGIC;
         mdio_rd                              : OUT STD_LOGIC;
         shift_addr                           : OUT STD_LOGIC;
         ld_data                              : OUT STD_LOGIC;
         ld_cnt                               : OUT STD_LOGIC;
         cnt_val                              : OUT STD_LOGIC_VECTOR(4 DOWNTO 0);
         valid_addr_lt                        : OUT STD_LOGIC;
         curr_state                           : OUT STD_LOGIC_VECTOR(2 DOWNTO 0)
      );
   END COMPONENT;
   
   
   -- --------------------------------------------------------------------
   -- status reg ---------------------------------------------------------
   -- --------------------------------------------------------------------
   
   SIGNAL gnd_wire                    : STD_LOGIC;
   SIGNAL vcc_wire                    : STD_LOGIC;
   
   SIGNAL so_status                   : STD_LOGIC;
   SIGNAL rxs_link_status_set         : STD_LOGIC;
   SIGNAL rtx_rx_local_fault_clr      : STD_LOGIC;
   
   -- --------------------------------------------------------------------
   -- interface to channel -----------------------------------------------
   -- --------------------------------------------------------------------
   SIGNAL csr_chnl_in_ch0             : STD_LOGIC_VECTOR(831 DOWNTO 0);		-- CSR inputs
   SIGNAL csr_chnl_in_ch1             : STD_LOGIC_VECTOR(831 DOWNTO 0);		-- CSR inputs
   SIGNAL csr_chnl_in_ch2             : STD_LOGIC_VECTOR(831 DOWNTO 0);		-- CSR inputs
   SIGNAL csr_chnl_in_ch3             : STD_LOGIC_VECTOR(831 DOWNTO 0);		-- CSR inputs
   SIGNAL csr_chnl_in_reserved_ch0  : STD_LOGIC_VECTOR(15 DOWNTO 0);
   SIGNAL csr_chnl_in_reserved_ch1  : STD_LOGIC_VECTOR(15 DOWNTO 0);
   SIGNAL csr_chnl_in_reserved_ch2  : STD_LOGIC_VECTOR(15 DOWNTO 0);
   SIGNAL csr_chnl_in_reserved_ch3  : STD_LOGIC_VECTOR(15 DOWNTO 0);
   
   SIGNAL dprio_chnl_id0              : STD_LOGIC_VECTOR(3 DOWNTO 0);		-- DPRIO channel base address ID
   SIGNAL dprio_chnl_id1              : STD_LOGIC_VECTOR(3 DOWNTO 0);		-- DPRIO channel base address ID
   SIGNAL dprio_chnl_id2              : STD_LOGIC_VECTOR(3 DOWNTO 0);		-- DPRIO channel base address ID
   SIGNAL dprio_chnl_id3              : STD_LOGIC_VECTOR(3 DOWNTO 0);		-- DPRIO channel base address ID
   
   SIGNAL si_ch0                      : STD_LOGIC;
   SIGNAL si_ch1                      : STD_LOGIC;
   SIGNAL si_ch2                      : STD_LOGIC;
   SIGNAL si_ch3                      : STD_LOGIC;
   
   SIGNAL dp_chnl_out_ch0             : STD_LOGIC_VECTOR(831 DOWNTO 0);		-- 
   SIGNAL dp_chnl_out_ch1             : STD_LOGIC_VECTOR(831 DOWNTO 0);		-- 
   SIGNAL dp_chnl_out_ch2             : STD_LOGIC_VECTOR(831 DOWNTO 0);		-- 
   SIGNAL dp_chnl_out_ch3             : STD_LOGIC_VECTOR(831 DOWNTO 0);		-- 
   SIGNAL dp_chnl_out_reserved_ch0    : STD_LOGIC_VECTOR(15 DOWNTO 0);
   SIGNAL dp_chnl_out_reserved_ch1    : STD_LOGIC_VECTOR(15 DOWNTO 0);
   SIGNAL dp_chnl_out_reserved_ch2    : STD_LOGIC_VECTOR(15 DOWNTO 0);
   SIGNAL dp_chnl_out_reserved_ch3    : STD_LOGIC_VECTOR(15 DOWNTO 0);
   
   SIGNAL so_ch0                      : STD_LOGIC;
   SIGNAL so_ch1                      : STD_LOGIC;
   SIGNAL so_ch2                      : STD_LOGIC;
   SIGNAL so_ch3                      : STD_LOGIC;
   
   SIGNAL mbus_out_ch0                : STD_LOGIC_VECTOR(15 DOWNTO 0);
   SIGNAL mbus_out_ch1                : STD_LOGIC_VECTOR(15 DOWNTO 0);
   SIGNAL mbus_out_ch2                : STD_LOGIC_VECTOR(15 DOWNTO 0);
   SIGNAL mbus_out_ch3                : STD_LOGIC_VECTOR(15 DOWNTO 0);
   
   -- --------------------------------------------------------------------
   -- interface to cmu ---------------------------------------------------
   -- --------------------------------------------------------------------
   SIGNAL csr_centrl_in               : STD_LOGIC_VECTOR(703 DOWNTO 0);		-- CSR inputs
   SIGNAL csr_centrl_in_reserved      : STD_LOGIC_VECTOR(31 DOWNTO 0);
   SIGNAL si_centrl                   : STD_LOGIC;
   
   SIGNAL dp_centrl_out               : STD_LOGIC_VECTOR(703 DOWNTO 0);		-- CSR inputs
   SIGNAL dp_centrl_out_reserved      : STD_LOGIC_VECTOR(31 DOWNTO 0);
   SIGNAL mbus_out_centrl             : STD_LOGIC_VECTOR(15 DOWNTO 0);
   SIGNAL so_centrl                   : STD_LOGIC;
   
   -- --------------------------------------------------------------------
   -- new in CYCLONEIV common --------------------------------------------------
   -- --------------------------------------------------------------------
   
   -- input --------------------
   -- PLD dynamic signal for PMA DPRIO cell for coverage for PE/TE
   SIGNAL pma_cram_test               : STD_LOGIC;
   SIGNAL serial_mode                 : STD_LOGIC;
   
   -- unused ports to be moved into reg
   SIGNAL jtag_mode                   : STD_LOGIC;
   SIGNAL jtag_shift_load             : STD_LOGIC;
   SIGNAL jtag_si                     : STD_LOGIC;
   SIGNAL jtag_so                     : STD_LOGIC;		-- wire
   
   -- status signals generated by PCS
   SIGNAL tx_local_fault              : STD_LOGIC;		-- from tx_sm
   SIGNAL rx_local_fault              : STD_LOGIC;		-- from rcv_sm
   SIGNAL xs_link_status              : STD_LOGIC;		-- from rcv_sm
   
   SIGNAL local_fault_ext             : STD_LOGIC;		-- Status signal wire
   SIGNAL xs_link_status_ext          : STD_LOGIC;		-- Status signal wire
   SIGNAL rx_local_fault_ext          : STD_LOGIC;		-- Status signal wire
   SIGNAL tx_local_fault_ext          : STD_LOGIC;		-- Status signal wire
   
   -- interconnect wires --------------------------------------------------
   
   -- wires from addr
   SIGNAL reg_addr                    : STD_LOGIC_VECTOR(15 DOWNTO 0);		-- addr --> reg
   
   -- wires from sm
   SIGNAL shift_addr                  : STD_LOGIC;		-- sm --> addr
   SIGNAL incr_addr                   : STD_LOGIC;		-- sm --> addr
   
   SIGNAL ld_cnt                      : STD_LOGIC;		-- sm --> cnt
   SIGNAL cnt_val                     : STD_LOGIC_VECTOR(4 DOWNTO 0);		-- sm --> cnt
   SIGNAL ld_data                     : STD_LOGIC;		-- sm --> cnt
   
   SIGNAL shift_in                    : STD_LOGIC;		-- sm --> ctl_data
   SIGNAL shift_out                   : STD_LOGIC;		-- sm --> ctl_data
   SIGNAL latch_ctl                   : STD_LOGIC;		-- sm --> ctl_data
   SIGNAL valid_addr_lt               : STD_LOGIC;		-- sm --> ctl_data
   
   SIGNAL mdio_wr                     : STD_LOGIC;		-- sm --> reg         
   SIGNAL mdio_rd                     : STD_LOGIC;		-- sm --> reg         
   
   SIGNAL curr_state                  : STD_LOGIC_VECTOR(2 DOWNTO 0);		-- sm --> top (../../pcs_central_testbus in central_chnnl)
   
   -- wires from cnt
   SIGNAL cnt_eq_0                    : STD_LOGIC;		-- cnt --> sm
   
   -- wires from ctl_data
   SIGNAL mbus_in                     : STD_LOGIC_VECTOR(15 DOWNTO 0);		-- ctl_data --> reg
   SIGNAL valid_addr                  : STD_LOGIC;		-- ctl_data --> sm
   SIGNAL opcode                      : STD_LOGIC_VECTOR(1 DOWNTO 0);		-- ctl_data --> sm
   
   -- ctl_data --> top
   -- ctl_data --> top
   
   -- wires from reg
   SIGNAL mbus_out                    : STD_LOGIC_VECTOR(15 DOWNTO 0);		-- reg --> ctl_data
   
   --wires to reg
   SIGNAL dev_addr_0                  : STD_LOGIC;
   
   -- Declare intermediate signals for referenced outputs
   SIGNAL cmudividerdprioout_xhdl0    : STD_LOGIC_VECTOR(599 DOWNTO 0);
   SIGNAL cmuplldprioout_xhdl1        : STD_LOGIC_VECTOR(1799 DOWNTO 0);
   SIGNAL refclkdividerdprioout_xhdl4 : STD_LOGIC_VECTOR(1 DOWNTO 0);
   SIGNAL rxpcsdprioout_xhdl5         : STD_LOGIC_VECTOR(1599 DOWNTO 0);
   SIGNAL rxpmadprioout_xhdl6         : STD_LOGIC_VECTOR(1199 DOWNTO 0);
   SIGNAL txpcsdprioout_xhdl7         : STD_LOGIC_VECTOR(599 DOWNTO 0);
   SIGNAL txpmadprioout_xhdl8         : STD_LOGIC_VECTOR(1199 DOWNTO 0);
   SIGNAL mdio_out_xhdl3              : STD_LOGIC;
   SIGNAL data_enable_n_xhdl2         : STD_LOGIC;
   SIGNAL rxpmadprioin_int			  : STD_LOGIC_VECTOR(1199 DOWNTO 0);
   SIGNAL cmuplldprioin_int 		  : STD_LOGIC_VECTOR(1799 DOWNTO 0) := (others => '0');
   SIGNAL cmudividerdprioin_int		  : STD_LOGIC_VECTOR(599 DOWNTO 0) := (others => '0');
   
   
BEGIN
   -- Drive referenced outputs
   refclkdividerdprioout <= refclkdividerdprioout_xhdl4;
   rxpcsdprioout <= rxpcsdprioout_xhdl5;
   rxpmadprioout <= rxpmadprioout_xhdl6(1199 DOWNTO 0);
   txpcsdprioout <= txpcsdprioout_xhdl7;
   txpmadprioout <= txpmadprioout_xhdl8;
   mdio_out <= mdio_out_xhdl3;
   data_enable_n <= data_enable_n_xhdl2;
   
   -- primary input/output connections ---------------------------------------
   
   -- outputs
   mdio_curr_st <= curr_state;		-- from SM
   
   -- module instantiatations ------------------------------------------------
   
   		-- from top
   
   mdio_addr_1 : cycloneiv_hssi_cmu_dprio_addr
      PORT MAP (
         reset       => mdio_rst,
         mdc         => mdc,		-- from top
         mdio_in     => mdio_in,		-- from top
         shift_addr  => shift_addr,		-- from sm
         incr_addr   => incr_addr,		-- from sm
         reg_addr    => reg_addr		-- To (16-bit reg addr) reg 
      );
   
   
   
   mdio_cnt_1 : cycloneiv_hssi_cmu_dprio_cnt
      PORT MAP (
         reset     => mdio_rst,
         mdc       => mdc,
         ld_cnt    => ld_cnt,		-- from sm
         cnt_val   => cnt_val,		-- from sm
         cnt_eq_0  => cnt_eq_0		-- to sm
      );
   
   
   
   mdio_sm_1 : cycloneiv_hssi_cmu_dprio_sm
      PORT MAP (
         reset          => mdio_rst,
         mdio_in        => mdio_in,		-- from top                 
         mdc            => mdc,
         opcode         => opcode,		-- from ctl_data
         valid_addr     => valid_addr,		-- from ctl_data
         cnt_eq_0       => cnt_eq_0,		-- from cnt
         shift_addr     => shift_addr,		-- to addr
         incr_addr      => incr_addr,		-- to addr
         mdio_wr        => mdio_wr,		-- to reg
         mdio_rd        => mdio_rd,		-- to reg
         shift_in       => shift_in,		-- to ctl_data
         shift_out      => shift_out,		-- to ctl_data
         latch_ctl      => latch_ctl,		-- to ctl_data
         ld_data        => ld_data,		-- to ctl_data
         valid_addr_lt  => valid_addr_lt,		-- to cnt_data
         ld_cnt         => ld_cnt,		-- to cnt
         cnt_val        => cnt_val,		-- to cnt (5-bit)
         curr_state     => curr_state		-- to top
      );
   
   
   
   mdio_ctl_data_1 : cycloneiv_hssi_cmu_dprio_ctl_data
      PORT MAP (
         reset          => mdio_rst,
         mdc            => mdc,
         mdio_in        => mdio_in,
         shift_in       => shift_in,		-- from sm
         shift_out      => shift_out,		-- frm sm
         ld_data        => ld_data,		-- from sm
         latch_ctl      => latch_ctl,		-- from sm
         port_addr      => port_addr,
         dev_addr       => dev_addr,
         valid_addr_lt  => valid_addr_lt,		-- from sm
         mbus_out       => mbus_out,		-- from reg
         mdio_out       => mdio_out_xhdl3,		-- to top
         mbus_in        => mbus_in,		-- to reg 
         opcode         => opcode,		-- to sm
         valid_addr     => valid_addr,		-- to sm
         data_enable_n  => data_enable_n_xhdl2		-- to top
      );
   
   -- --------------------------------------------------------------------
   -- Status registers and MBUS_OUT muxing for whole QUAD ----------------
   -- --------------------------------------------------------------------
   gnd_wire <= '0';
   vcc_wire <= '1';
   
   dev_addr_0 <= dev_addr(0);
   
   
   
   status_reg : cycloneiv_hssi_cmu_dprio_status
      PORT MAP (
         mdio_rst                => mdio_rst,
         mdio_rd                 => mdio_rd,
         reg_addr                => reg_addr,
         dev_addr_0              => dev_addr(0),
         mdc                     => mdc,
         serial_mode             => gnd_wire,
         ser_shift_load          => '0',
         si                      => '0',
         mbus_out_ch0            => mbus_out_ch0,
         mbus_out_ch1            => mbus_out_ch1,
         mbus_out_ch2            => mbus_out_ch2,
         mbus_out_ch3            => mbus_out_ch3,
         mbus_out_centrl         => mbus_out_centrl,
         align_status            => align_status,
         sync_status             => sync_status,
         xs_link_status          => xs_link_status,
         rx_local_fault          => rx_local_fault,
         tx_local_fault          => tx_local_fault,
         rxs_link_status_set     => rxs_link_status_set,
         rtx_rx_local_fault_clr  => rtx_rx_local_fault_clr,
         mbus_out                => mbus_out,		-- to ctrl_data
         so                      => so_status
      );
   
   -- --------------------------------------------------------------------
   -- common -------------------------------------------------------------
   -- --------------------------------------------------------------------
   pma_cram_test <= '0';
   serial_mode <= '0';
   
   -- --------------------------------------------------------------------
   --  cmu ---------------------------------------------------------------
   -- --------------------------------------------------------------------
   si_centrl <= 'X';
   
   md_reg_centrl : cycloneiv_hssi_cmu_dprio_centrl_top
      PORT MAP (
         mdio_rst        => mdio_rst,		-- from top
         mdio_wr         => mdio_wr,		-- from sm        
         reg_addr        => reg_addr,		-- from addr
         mdc             => mdc,		-- from top  
         mbus_in         => mbus_in,		-- from ctrl_data
         serial_mode     => serial_mode,		-- new: 
         mdio_dis        => mdio_dis,		-- from top
         pma_cram_test   => pma_cram_test,		-- new:
         --                      .dprioload(dprioload),                // from top     
         ser_shift_load  => dprioload,		-- from top 
         si              => si_centrl,		-- new    
         csr_centrl_in   => csr_centrl_in,		-- new
         csr_centrl_in_reserved => csr_centrl_in_reserved,
         --                      .align_status (align_status),         // moved to status_reg_ctrl   
         --                      .sync_status (sync_status),           // moved to status_reg_ctrl
         --                      .mdio_rd(mdio_rd),                    // moved to status_reg_ctrl
         --                      .dev_addr_0 (dev_addr_0),             // moved to status_reg_ctrl
         
         dp_centrl_out   => dp_centrl_out,		-- to top
         dp_centrl_out_reserved => dp_centrl_out_reserved,
         
         so              => so_centrl,		-- to ctrl_data
         mbus_out        => mbus_out_centrl		-- to status_reg
      );
   
   -- --------------------------------------------------------------------
   -- channel ------------------------------------------------------------
   -- --------------------------------------------------------------------
   
   dprio_chnl_id0 <= "0000";
   dprio_chnl_id1 <= "0001";
   dprio_chnl_id2 <= "0010";
   dprio_chnl_id3 <= "0011";
   
   si_ch0 <= 'X';
   si_ch1 <= 'X';
   si_ch2 <= 'X';
   si_ch3 <= 'X';   
   
   md_reg_ch0 : cycloneiv_hssi_cmu_dprio_chnl_top
      PORT MAP (
         mdio_rst        => mdio_rst,		-- from top
         mdio_wr         => mdio_wr,		-- from sm        
         reg_addr        => reg_addr,		-- from addr
         mdc             => mdc,		-- from top  
         mbus_in         => mbus_in,		-- from ctrl_data
         serial_mode     => serial_mode,		-- new: 
         mdio_dis        => mdio_dis,		-- from top
         pma_cram_test   => pma_cram_test,		-- new:
         ser_shift_load  => dprioload,		-- from top 
         si              => si_ch0,		-- new    
         csr_chnl_in     => csr_chnl_in_ch0,		-- new
         csr_chnl_in_reserved => csr_chnl_in_reserved_ch0,
         dprio_chnl_id   => dprio_chnl_id0,		-- new - not in centrl
         
         dp_chnl_out     => dp_chnl_out_ch0,		-- to top
         dp_chnl_out_reserved => dp_chnl_out_reserved_ch0,
         so              => so_ch0,		-- to ctrl_data
         mbus_out        => mbus_out_ch0		-- to status_reg
      );
   
   
   
   md_reg_ch1 : cycloneiv_hssi_cmu_dprio_chnl_top
      PORT MAP (
         mdio_rst        => mdio_rst,		-- from top
         mdio_wr         => mdio_wr,		-- from sm        
         reg_addr        => reg_addr,		-- from addr
         mdc             => mdc,		-- from top  
         mbus_in         => mbus_in,		-- from ctrl_data
         serial_mode     => serial_mode,		-- new: 
         mdio_dis        => mdio_dis,		-- from top
         pma_cram_test   => pma_cram_test,		-- new:
         ser_shift_load  => dprioload,		-- from top 
         si              => si_ch1,		-- new    
         csr_chnl_in     => csr_chnl_in_ch1,		-- new
         csr_chnl_in_reserved => csr_chnl_in_reserved_ch1,
         dprio_chnl_id   => dprio_chnl_id1,		-- new - not in centrl
         
         dp_chnl_out     => dp_chnl_out_ch1,		-- to top
         dp_chnl_out_reserved => dp_chnl_out_reserved_ch1,
         so              => so_ch1,		-- to ctrl_data
         mbus_out        => mbus_out_ch1		-- to status_reg
      );
   
   
   
   md_reg_ch2 : cycloneiv_hssi_cmu_dprio_chnl_top
      PORT MAP (
         mdio_rst        => mdio_rst,		-- from top
         mdio_wr         => mdio_wr,		-- from sm        
         reg_addr        => reg_addr,		-- from addr
         mdc             => mdc,		-- from top  
         mbus_in         => mbus_in,		-- from ctrl_data
         serial_mode     => serial_mode,		-- new: 
         mdio_dis        => mdio_dis,		-- from top
         pma_cram_test   => pma_cram_test,		-- new:
         ser_shift_load  => dprioload,		-- from top 
         si              => si_ch2,		-- new    
         csr_chnl_in     => csr_chnl_in_ch2,		-- new
         csr_chnl_in_reserved => csr_chnl_in_reserved_ch2,
         dprio_chnl_id   => dprio_chnl_id2,		-- new - not in centrl
         
         dp_chnl_out     => dp_chnl_out_ch2,		-- to top
         dp_chnl_out_reserved => dp_chnl_out_reserved_ch2,
         so              => so_ch2,		-- to ctrl_data
         mbus_out        => mbus_out_ch2		-- to status_reg
      );
   
   
   
   md_reg_ch3 : cycloneiv_hssi_cmu_dprio_chnl_top
      PORT MAP (
         mdio_rst        => mdio_rst,		-- from top
         mdio_wr         => mdio_wr,		-- from sm        
         reg_addr        => reg_addr,		-- from addr
         mdc             => mdc,		-- from top  
         mbus_in         => mbus_in,		-- from ctrl_data
         serial_mode     => serial_mode,		-- new: 
         mdio_dis        => mdio_dis,		-- from top
         pma_cram_test   => pma_cram_test,		-- new:
         ser_shift_load  => dprioload,		-- from top 
         si              => si_ch3,		-- new    
         csr_chnl_in     => csr_chnl_in_ch3,		-- new
         csr_chnl_in_reserved => csr_chnl_in_reserved_ch3,
         dprio_chnl_id   => dprio_chnl_id3,		-- new - not in centrl
         
         dp_chnl_out     => dp_chnl_out_ch3,		-- to top
         dp_chnl_out_reserved => dp_chnl_out_reserved_ch3,
