   SIGNAL rxctrl_in_scan_mode               : STD_LOGIC;        -- scan enable
   SIGNAL rxctrl_in_rxfifo_urst             : STD_LOGIC;        -- User reset exclusive to rx_ctrl & below
   SIGNAL rxctrl_in_pld_wr_dis              : STD_LOGIC;        -- PLD write disable
   SIGNAL rxctrl_in_pld_re                  : STD_LOGIC;        -- PLD read eanble
   SIGNAL rxctrl_in_dis_pc_byte             : STD_LOGIC;
   
   SIGNAL rxctrl_out_rx_we_out              : STD_LOGIC;
   SIGNAL rxctrl_out_wr_enable_out          : STD_LOGIC;
   SIGNAL rxctrl_out_rd_enable_out          : STD_LOGIC;
   
   --/////////////////////////////////////////////////////////////////////////
   -- tx_ctl_ctrl --------------------------------------------------------- //
   --/////////////////////////////////////////////////////////////////////////
   SIGNAL txctrl_in_soft_reset              : STD_LOGIC;        -- Reset
   SIGNAL txctrl_in_fifo_wr_clk             : STD_LOGIC;        -- Used to be wr_clk_pos
   SIGNAL txctrl_in_fifo_rd_clk             : STD_LOGIC;        -- Coming from txclk_xg_ctl 
   SIGNAL txctrl_in_refclk_b_in             : STD_LOGIC;        -- The local reference clock used by the internal
   SIGNAL txctrl_in_scan_mode               : STD_LOGIC;        -- scan enable
   SIGNAL txctrl_in_txfifo_urst             : STD_LOGIC;        -- user reset 
   SIGNAL txctrl_in_pld_we                  : STD_LOGIC;        -- PLD phase compwire txctrl_in_ fifo we, level active
   SIGNAL txctrl_in_pld_rd_dis              : STD_LOGIC;        -- PLD phase compwire txctrl_in_ fifo rd dis, edge active
   SIGNAL txctrl_in_dis_pc_byte             : STD_LOGIC;
   
   SIGNAL txctrl_out_wr_enable_out          : STD_LOGIC;        -- ch0 wr_enable1 output for X4/X8 mode
   SIGNAL txctrl_out_rd_enable_out          : STD_LOGIC;        -- ch0 rd_enable1 output for X4/X8 mode
   SIGNAL txctrl_out_fifo_select_out        : STD_LOGIC;        -- New output for Revwire txctrl_in_B 
   
   --/////////////////////////////////////////////////////////////////////////
   -- DSKW SM ------------------------------------------------------------- //
   --/////////////////////////////////////////////////////////////////////////
   
   SIGNAL dskw_curr_st                      : STD_LOGIC_VECTOR(3 DOWNTO 0);
   SIGNAL alignstatus_int                   : STD_LOGIC;        -- feeding to PLD and DPRIO
   
   SIGNAL dskw_sm_clk                       : STD_LOGIC;
   
   --/////////////////////////////////////////////////////////////////////////
   -- TX SM --------------------------------------------------------------- //
   --/////////////////////////////////////////////////////////////////////////
   
   SIGNAL rtx_rx_local_fault_clr_int        : STD_LOGIC;        -- from DPRIO
   SIGNAL rindv_tx_int                      : STD_LOGIC;
   
