   SIGNAL tx_local_fault_det                : STD_LOGIC;        -- output to rx_sm
   SIGNAL tx_local_fault_int                : STD_LOGIC;        -- feeding nowhere
   
   SIGNAL tx_sm_clk                         : STD_LOGIC;
   SIGNAL tx_sm_datain                      : STD_LOGIC_VECTOR(31 DOWNTO 0);
   SIGNAL tx_sm_ctrlin                      : STD_LOGIC_VECTOR(3 DOWNTO 0);
   SIGNAL tx_sm_rdenablesyncin              : STD_LOGIC;
   
   --/////////////////////////////////////////////////////////////////////////
   -- RX SM --------------------------------------------------------------- //
   --/////////////////////////////////////////////////////////////////////////
   
   SIGNAL rindv_rx_int                      : STD_LOGIC;        -- from DPRIO
   SIGNAL rxs_link_status_set_int           : STD_LOGIC;        -- from DPRIO
   SIGNAL xs_link_status_int                : STD_LOGIC;
   
   SIGNAL rx_local_fault_int                : STD_LOGIC;        -- feeding DPRIO
   SIGNAL xlink_status_int                  : STD_LOGIC;        -- feeding DPRIO
   SIGNAL rcv_curr_st                       : STD_LOGIC_VECTOR(1 DOWNTO 0);
   
   SIGNAL rcv_sm_clk                        : STD_LOGIC;
   SIGNAL rcv_sm_decdatavalid               : STD_LOGIC_VECTOR(3 DOWNTO 0);
   SIGNAL rcv_sm_decdata                    : STD_LOGIC_VECTOR(31 DOWNTO 0);
   SIGNAL rcv_sm_decctl                     : STD_LOGIC_VECTOR(3 DOWNTO 0);
   SIGNAL rcv_sm_rxrunningdisp              : STD_LOGIC_VECTOR(3 DOWNTO 0);
   
   --/////////////////////////////////////////////////////////////////////////
   -- DPRIO --------------------------------------------------------------- //
   --/////////////////////////////////////////////////////////////////////////
   
   SIGNAL port_addr                         : STD_LOGIC_VECTOR(4 DOWNTO 0);        -- convert from top parameter
   SIGNAL dev_addr                          : STD_LOGIC_VECTOR(4 DOWNTO 0);        -- convert from top parameter
   SIGNAL mdio_rst                          : STD_LOGIC;
   SIGNAL cmudprioin                        : STD_LOGIC_VECTOR(29 DOWNTO 0);        --local wrt cmu todo: rem
   SIGNAL cmudprioout                       : STD_LOGIC_VECTOR(29 DOWNTO 0);        --local wrt cmu todo: rem
   SIGNAL mdio_curr_st                      : STD_LOGIC_VECTOR(2 DOWNTO 0);
   SIGNAL mdio_in                           : STD_LOGIC;
   
   SIGNAL mdio_rst_reg                      : STD_LOGIC;
   -- X-HDL generated signals

   SIGNAL xhdl13 : STD_LOGIC_VECTOR(7 DOWNTO 0);
   SIGNAL xhdl14 : STD_LOGIC_VECTOR(7 DOWNTO 0);
   SIGNAL xhdl15 : STD_LOGIC_VECTOR(7 DOWNTO 0);
   
   -- Declare intermediate signals for referenced outputs
   SIGNAL cmudividerdprioout_xhdl0          : STD_LOGIC_VECTOR(599 DOWNTO 0);
   SIGNAL cmuplldprioout_xhdl1              : STD_LOGIC_VECTOR(1799 DOWNTO 0);
   SIGNAL enabledeskew_xhdl2                : STD_LOGIC;
   SIGNAL fiforesetrd_xhdl3                 : STD_LOGIC;
   SIGNAL refclkdividerdprioout_xhdl4       : STD_LOGIC_VECTOR(1 DOWNTO 0);
   SIGNAL rxctrlout_xhdl5                   : STD_LOGIC_VECTOR(3 DOWNTO 0);
   SIGNAL rxdataout_xhdl6                   : STD_LOGIC_VECTOR(31 DOWNTO 0);
   SIGNAL rxpcsdprioout_xhdl7               : STD_LOGIC_VECTOR(1599 DOWNTO 0);
   SIGNAL rxpmadprioout_xhdl8               : STD_LOGIC_VECTOR(1199 DOWNTO 0);
   SIGNAL txctrlout_xhdl9                   : STD_LOGIC_VECTOR(3 DOWNTO 0);
   SIGNAL txdataout_xhdl10                  : STD_LOGIC_VECTOR(31 DOWNTO 0);
   SIGNAL txpcsdprioout_xhdl11              : STD_LOGIC_VECTOR(599 DOWNTO 0);
   SIGNAL txpmadprioout_xhdl12              : STD_LOGIC_VECTOR(1199 DOWNTO 0);
BEGIN
          
      ------------------------
      --  Wire Delay Block --
      ------------------------
      WireDelay : BLOCK
      BEGIN
           VitalWireDelay (txphfiforddisable_ipd,txphfiforddisable, tipd_txphfiforddisable);
       bits_txctrl : FOR i in txctrl'RANGE GENERATE
           VitalWireDelay (txctrl_ipd(i),txctrl(i), tipd_txctrl(i));
       END GENERATE;
       bits_rxdatain : FOR i in rxdatain'RANGE GENERATE
           VitalWireDelay (rxdatain_ipd(i),rxdatain(i), tipd_rxdatain(i));
       END GENERATE;
           VitalWireDelay (txclk_ipd,txclk, tipd_txclk);
       bits_syncstatus : FOR i in syncstatus'RANGE GENERATE
           VitalWireDelay (syncstatus_ipd(i),syncstatus(i), tipd_syncstatus(i));
       END GENERATE;
       bits_rxpcsdprioin : FOR i in rxpcsdprioin'RANGE GENERATE
           VitalWireDelay (rxpcsdprioin_ipd(i),rxpcsdprioin(i), tipd_rxpcsdprioin(i));
       END GENERATE;
       bits_txdigitalreset : FOR i in txdigitalreset'RANGE GENERATE
           VitalWireDelay (txdigitalreset_ipd(i),txdigitalreset(i), tipd_txdigitalreset(i));
       END GENERATE;
       bits_txdatain : FOR i in txdatain'RANGE GENERATE
           VitalWireDelay (txdatain_ipd(i),txdatain(i), tipd_txdatain(i));
       END GENERATE;
           VitalWireDelay (scanclk_ipd,scanclk, tipd_scanclk);
           VitalWireDelay (rdenablesync_ipd,rdenablesync, tipd_rdenablesync);
           VitalWireDelay (dpclk_ipd,dpclk, tipd_dpclk);
           VitalWireDelay (rxphfiforeset_ipd,rxphfiforeset, tipd_rxphfiforeset);
       bits_testin : FOR i in testin'RANGE GENERATE
           VitalWireDelay (testin_ipd(i),testin(i), tipd_testin(i));
       END GENERATE;
       bits_rxrunningdisp : FOR i in rxrunningdisp'RANGE GENERATE
           VitalWireDelay (rxrunningdisp_ipd(i),rxrunningdisp(i), tipd_rxrunningdisp(i));
       END GENERATE;
       bits_rxdatavalid : FOR i in rxdatavalid'RANGE GENERATE
           VitalWireDelay (rxdatavalid_ipd(i),rxdatavalid(i), tipd_rxdatavalid(i));
       END GENERATE;
       bits_txpcsdprioin : FOR i in txpcsdprioin'RANGE GENERATE
           VitalWireDelay (txpcsdprioin_ipd(i),txpcsdprioin(i), tipd_txpcsdprioin(i));
       END GENERATE;
           VitalWireDelay (dprioin_ipd,dprioin, tipd_dprioin);
       bits_rxctrl : FOR i in rxctrl'RANGE GENERATE
           VitalWireDelay (rxctrl_ipd(i),rxctrl(i), tipd_rxctrl(i));
       END GENERATE;
       bits_rxanalogreset : FOR i in rxanalogreset'RANGE GENERATE
           VitalWireDelay (rxanalogreset_ipd(i),rxanalogreset(i), tipd_rxanalogreset(i));
       END GENERATE;
           VitalWireDelay (txphfifowrenable_ipd,txphfifowrenable, tipd_txphfifowrenable);
           VitalWireDelay (rxphfifowrdisable_ipd,rxphfifowrdisable, tipd_rxphfifowrdisable);
       bits_rdalign : FOR i in rdalign'RANGE GENERATE
           VitalWireDelay (rdalign_ipd(i),rdalign(i), tipd_rdalign(i));
       END GENERATE;
       bits_fixedclk : FOR i in fixedclk'RANGE GENERATE
           VitalWireDelay (fixedclk_ipd(i),fixedclk(i), tipd_fixedclk(i));
       END GENERATE;
           VitalWireDelay (dpriodisable_ipd,dpriodisable, tipd_dpriodisable);
           VitalWireDelay (rxphfifordenable_ipd,rxphfifordenable, tipd_rxphfifordenable);
           VitalWireDelay (scanmode_ipd,scanmode, tipd_scanmode);
       bits_rxpmadprioin : FOR i in rxpmadprioin'RANGE GENERATE
           VitalWireDelay (rxpmadprioin_ipd(i),rxpmadprioin(i), tipd_rxpmadprioin(i));
       END GENERATE;
       bits_rxdigitalreset : FOR i in rxdigitalreset'RANGE GENERATE
           VitalWireDelay (rxdigitalreset_ipd(i),rxdigitalreset(i), tipd_rxdigitalreset(i));
       END GENERATE;
       bits_adet : FOR i in adet'RANGE GENERATE
           VitalWireDelay (adet_ipd(i),adet(i), tipd_adet(i));
       END GENERATE;
           VitalWireDelay (txcoreclk_ipd,txcoreclk, tipd_txcoreclk);
           VitalWireDelay (txphfiforeset_ipd,txphfiforeset, tipd_txphfiforeset);
           VitalWireDelay (rxcoreclk_ipd,rxcoreclk, tipd_rxcoreclk);
           VitalWireDelay (dprioload_ipd,dprioload, tipd_dprioload);
           VitalWireDelay (quadreset_ipd,quadreset, tipd_quadreset);
           VitalWireDelay (nonuserfromcal_ipd,nonuserfromcal, tipd_nonuserfromcal);
           VitalWireDelay (scanshift_ipd,scanshift, tipd_scanshift);
       bits_txpmadprioin : FOR i in txpmadprioin'RANGE GENERATE
           VitalWireDelay (txpmadprioin_ipd(i),txpmadprioin(i), tipd_txpmadprioin(i));
       END GENERATE;
       bits_rxpowerdown : FOR i in rxpowerdown'RANGE GENERATE
           VitalWireDelay (rxpowerdown_ipd(i),rxpowerdown(i), tipd_rxpowerdown(i));
       END GENERATE;
           VitalWireDelay (recovclk_ipd,recovclk, tipd_recovclk);
      END BLOCK;
          
      ------------------------
      --  Functionality Section --
      ------------------------
   -- Drive referenced outputs
   cmudividerdprioout <= cmudividerdprioout_xhdl0;
   cmuplldprioout <= cmuplldprioout_xhdl1;
   enabledeskew <= enabledeskew_xhdl2;
   fiforesetrd <= fiforesetrd_xhdl3;
   refclkdividerdprioout <= refclkdividerdprioout_xhdl4;
   rxctrlout <= rxctrlout_xhdl5;
   rxdataout <= rxdataout_xhdl6;
   rxpcsdprioout <= rxpcsdprioout_xhdl7;
   rxpmadprioout <= rxpmadprioout_xhdl8;
   txctrlout <= txctrlout_xhdl9;
   txdataout <= txdataout_xhdl10;
   txpcsdprioout <= txpcsdprioout_xhdl11;
   txpmadprioout <= txpmadprioout_xhdl12;
   
   --///////////////////////////////////////////////////////////////////////////
   -- Const wires ------------------------------------------------------------//
   --///////////////////////////////////////////////////////////////////////////
   vcc_wire <= '1';
   gnd_wire <= '0';
  
   -- VITAL Timing

    VITAL : PROCESS(dpclk_in, dprioin_in, dprioout_tim, dpriooe_tim)
    variable Tviol_dprioin_dpclk : std_ulogic := '0';
    variable TimingData_dprioin_dpclk : VitalTimingDataType := VitalTimingDataInit;
    variable dprioout_VitalGlitchData: VitalGlitchDataType;
    variable dpriooe_VitalGlitchData: VitalGlitchDataType;

   BEGIN

       -----------------------
       -- Timing Check Section
       -----------------------

       if (TimingChecksOn) then

               VitalSetupHoldCheck (
                       Violation       => Tviol_dprioin_dpclk,
                       TimingData      => TimingData_dprioin_dpclk,
                       TestSignal      => dprioin_in,
                       TestSignalName  => "DPRIOIN",
                       RefSignal       => dpclk_in,
                       RefSignalName   => "DPCLK",
                       SetUpHigh       => tsetup_dprioin_dpclk_noedge_posedge,
                       SetUpLow        => tsetup_dprioin_dpclk_noedge_posedge,
                       HoldHigh        => thold_dprioin_dpclk_noedge_posedge,
                       HoldLow         => thold_dprioin_dpclk_noedge_posedge,
                       RefTransition   => '/',
                       HeaderMsg       => InstancePath & "/CYCLONEIV_HSSI_CMU",
                       XOn             => XOnChecks,
                       MsgOn           => MsgOnChecks );
       end if;

       ---------------------
       -- Path Delay Section
       ---------------------

       VitalPathDelay01 (
           OutSignal => dprioout,
           OutSignalName => "DPRIOOUT",
           OutTemp => dprioout_tim,
           Paths => (1 => (dpclk_in'last_event, tpd_dpclk_dprioout_posedge, TRUE)),
           GlitchData => dprioout_VitalGlitchData,
           Mode => DefGlitchMode,
           XOn => XOn,
           MsgOn => MsgOn );

       VitalPathDelay01 (
           OutSignal => dpriooe,
           OutSignalName => "DPRIOOE",
           OutTemp => dpriooe_tim,
           Paths => (1 => (dpclk_in'last_event, tpd_dpclk_dpriooe_posedge, TRUE)),
           GlitchData => dpriooe_VitalGlitchData,
           Mode => DefGlitchMode,
           XOn => XOn, 
           MsgOn => MsgOn );

   END PROCESS;
 
   --///////////////////////////////////////////////////////////////////////////
   -- process param ----------------------------------------------------------//
   --///////////////////////////////////////////////////////////////////////////
   PROCESS 
   BEGIN
      init_rauto_deassert_pc_rst_cnt <= int2bin(auto_spd_deassert_ph_fifo_rst_count, 4);
      init_rauto_pc_en_cnt <= int2bin(auto_spd_phystatus_notify_count, 5);
      init_rauto_speed_ena <= mux_select(alpha_tolower(pipe_auto_speed_nego_enable) = ("true"), '1', '0');
      
      init_rclk_1_sel <= mux_select((rx0_clk1_mux_select = ("recvd_clk") OR rx0_clk1_mux_select = ("recovered clock")), "00", mux_select((rx0_clk1_mux_select = ("digital_refclk") OR rx0_clk1_mux_select = ("digital reference clock")), "01", mux_select((rx0_clk1_mux_select = ("local_refclk") OR rx0_clk1_mux_select = ("local reference clock")), "10", mux_select((rx0_clk1_mux_select = ("master_clk") OR rx0_clk1_mux_select = ("master clk") OR rx0_clk1_mux_select = ("master clock")), "11", "ZZ"))));
      init_rclk_2_sel <= mux_select((rx0_clk2_mux_select = ("recvd_clk") OR rx0_clk2_mux_select = ("recovered clock")), "00", mux_select((rx0_clk2_mux_select = ("digital_refclk") OR rx0_clk2_mux_select = ("digital reference clock")), "10", mux_select((rx0_clk2_mux_select = ("local_refclk") OR rx0_clk2_mux_select = ("local reference clock")), "01", mux_select((rx0_clk2_mux_select = ("core_clk") OR rx0_clk2_mux_select = ("core clk") OR rx0_clk2_mux_select = ("core clock")), "11", "ZZ"))));
      init_rdwidth_rx <= mux_select((rx0_use_double_data_mode = ("true")), '1', '0');
      init_rdwidth_tx <= mux_select((tx0_use_double_data_mode = ("true")), '1', '0');
      init_rfreerun_rx <= mux_select((rx0_reset_clock_output_during_digital_reset = ("false")), '1', '0');
      init_rfreerun_tx <= mux_select((tx0_reset_clock_output_during_digital_reset = ("false")), '1', '0');        -- "Data width"
      init_rfreq_sel <= mux_select((pipe_freq_scale_mode = ("data width")), '0', '1');
      init_rindv_rx <= mux_select((rx0_channel_bonding = ("x4") OR rx0_channel_bonding = ("x8") OR alpha_tolower(in_xaui_mode) = ("true")), '0', '1');
      init_rindv_tx <= mux_select((tx0_channel_bonding = ("x4") OR tx0_channel_bonding = ("x8") OR alpha_tolower(in_xaui_mode) = ("true")), '0', '1');
      init_rmaster_rx <= mux_select((alpha_tolower(rx_master_direction) = ("none")), '1', '0');
      init_rmaster_tx <= mux_select((alpha_tolower(tx_master_direction) = ("none")), '1', '0');
      init_rmaster_up_rx <= mux_select((alpha_tolower(rx_master_direction) = ("up")), '1', '0');
      init_rmaster_up_tx <= mux_select((alpha_tolower(tx_master_direction) = ("up")), '1', '0');
      init_rphfifo_regmode_rx <= mux_select((rx0_ph_fifo_reg_mode = ("true")), '1', '0');
      init_rpma_done_count <= "000000000000001111"; -- int2bin(pma_done_count, 18);
      init_rrcvd_clk_sel <= mux_select((rx0_recovered_clk_mux_select = ("recvd_clk") OR rx0_recovered_clk_mux_select = ("recovered clock")), "00", mux_select((rx0_recovered_clk_mux_select = ("digital_refclk") OR rx0_recovered_clk_mux_select = ("digital reference clock")), "01", mux_select((rx0_recovered_clk_mux_select = ("local_refclk") OR rx0_recovered_clk_mux_select = ("local reference clock")), "10", "ZZ")));
      init_rrx_rd_clk_sel <= mux_select((rx0_rd_clk_mux_select = ("core_clk") OR rx0_rd_clk_mux_select = ("core clk") OR rx0_rd_clk_mux_select = ("core clock")), '1', '0');
      init_rrxfifo_urst_en <= mux_select((rx0_ph_fifo_reset_enable = ("true")), '1', '0');
      init_rrxpcsclkpwdn <= mux_select((rx0_clk_pd_enable = ("true")), '1', '0');
      init_rrxphfifopldctl_en <= mux_select((rx0_ph_fifo_user_ctrl_enable = ("true")), '1', '0');
      init_rself_sw_en_rx <= mux_select((alpha_tolower(rx0_auto_spd_self_switch_enable) = ("true")), '1', '0');
      init_rself_sw_en_tx <= mux_select((alpha_tolower(tx0_auto_spd_self_switch_enable) = ("true")), '1', '0');
      init_rtxpcsclkpwdn <= mux_select((tx0_clk_pd_enable = ("true")), '1', '0');
      init_rtxphfifopldctl_en <= mux_select((tx0_ph_fifo_user_ctrl_enable = ("true")), '1', '0');        -- TxFifo Rd clock 1=refclk_pma, 0=local_refclk_pma
      init_rtxrdclksel <= mux_select((tx0_rd_clk_mux_select = ("central")), '1', '0');
      init_rtxwrclksel <= mux_select((tx0_wr_clk_mux_select = ("int_clk") OR tx0_wr_clk_mux_select = ("int clk") OR tx0_wr_clk_mux_select = ("internal clock")), '1', '0');        -- TxFifo Write clk. 1=int_clk; 0=pld_tx_clk
      
      -- cram used in centrl_clk_ctl but not in WYS
      init_scan_mode <= '0';        -- REFCLK_OUT free running enable CRAM
      
      -- cycloneiv_new
      init_rfreerun_centrl <=  mux_select((coreclk_out_gated_by_quad_reset = ("true")), '0', '1');  -- flipped
      init_rcentrl_clk_sel <= mux_select((select_refclk_dig = ("true")), '1', '0');      
      init_rrefclk_out_div2 <= mux_select((use_coreclk_out_post_divider = ("true")), '1', '0');
      
      IF (tx0_ph_fifo_reset_enable = "true") THEN
          init_rtxfifo_urst_en <= '1';
      ELSE
          init_rtxfifo_urst_en <= '0';
      END IF;
      
      -- ww12_RTL
      IF (alpha_tolower(rx_xaui_sm_backward_compatible_enable) = "true") THEN
          init_rxaui_s2gx_en_rx  <= '1';
      ELSE
          init_rxaui_s2gx_en_rx  <= '0';
      END IF;
      
      IF (alpha_tolower(tx_xaui_sm_backward_compatible_enable) = "true") THEN
          init_rxaui_s2gx_en_tx  <= '1';
      ELSE
          init_rxaui_s2gx_en_tx  <= '0';
      END IF;
      
      init_rwait_for_phfifo_cnt <= "100000"; -- todo

      --init_in_xaui_mode <= '0';
      init_in_xaui_mode <= mux_select((alpha_tolower(in_xaui_mode) = ("true") OR alpha_tolower(use_deskew_fifo) = ("true")), '1', '0');
      
      WAIT;
   END PROCESS;
   
   --///////////////////////////////////////////////////////////////////////////
   -- CRAM -------------------------------------------------------------------//
   --///////////////////////////////////////////////////////////////////////////
   cram_rauto_deassert_pc_rst_cnt <= init_rauto_deassert_pc_rst_cnt;
   cram_rauto_pc_en_cnt           <= init_rauto_pc_en_cnt;
   cram_rauto_speed_ena <= init_rauto_speed_ena;
   cram_rclk_1_sel <= init_rclk_1_sel;
   cram_rclk_2_sel <= init_rclk_2_sel;
   cram_rdwidth_rx <= init_rdwidth_rx;
   cram_rdwidth_tx <= init_rdwidth_tx;
   cram_rfreerun_rx <= init_rfreerun_rx;
   cram_rfreerun_tx <= init_rfreerun_tx;
   cram_rfreq_sel <= init_rfreq_sel;
   cram_rindv_rx <= init_rindv_rx;
   cram_rindv_tx <= init_rindv_tx;
   cram_rmaster_rx <= init_rmaster_rx;
   cram_rmaster_tx <= init_rmaster_tx;
   cram_rmaster_up_rx <= init_rmaster_up_rx;
   cram_rmaster_up_tx <= init_rmaster_up_tx;
   cram_rphfifo_regmode_rx <= init_rphfifo_regmode_rx;
   cram_rpma_done_count <= init_rpma_done_count;
   cram_rrcvd_clk_sel <= init_rrcvd_clk_sel;
   cram_rrx_rd_clk_sel <= init_rrx_rd_clk_sel;
   cram_rrxfifo_urst_en <= init_rrxfifo_urst_en;
   cram_rrxpcsclkpwdn <= init_rrxpcsclkpwdn;
   cram_rrxphfifopldctl_en <= init_rrxphfifopldctl_en;
   cram_rself_sw_en_rx <= init_rself_sw_en_rx;
   cram_rself_sw_en_tx <= init_rself_sw_en_tx;
   cram_rtxpcsclkpwdn <= init_rtxpcsclkpwdn;
   cram_rtxphfifopldctl_en <= init_rtxphfifopldctl_en;
   cram_rtxrdclksel <= init_rtxrdclksel;
   cram_rtxwrclksel <= init_rtxwrclksel;
   cram_scan_mode <= init_scan_mode;
   
   -- cram used in centrl_clk_ctl but not in WYS
   cram_rfreerun_centrl <= init_rfreerun_centrl;
   cram_rcentrl_clk_sel <= init_rcentrl_clk_sel;
   cram_rrefclk_out_div2 <= init_rrefclk_out_div2;
   
   cram_rtxfifo_urst_en <= init_rtxfifo_urst_en;    -- used in txctrl

   -- ww12_RTL
   cram_rxaui_s2gx_en_rx  <= init_rxaui_s2gx_en_rx;
   cram_rxaui_s2gx_en_tx  <= init_rxaui_s2gx_en_tx;
   cram_rwait_for_phfifo_cnt <= init_rwait_for_phfifo_cnt;
   
   --///////////////////////////////////////////////////////////////////////////
   -- INPUT Filtering --------------------------------------------------------//
   --///////////////////////////////////////////////////////////////////////////
   
   dpclk_in <= '1' WHEN (dpclk = '1') ELSE
               '0';
   dpriodisable_in <= '0' WHEN (dpriodisable = '0') ELSE
                      '1';
   dprioin_in <= dprioin; 
   
   dprioload_in <= '1' WHEN (dprioload = '1') ELSE
                   '0';
   fixedclk_in(0) <= '1' WHEN (fixedclk(0) = '1') ELSE
                     '0';
   fixedclk_in(1) <= '1' WHEN (fixedclk(1) = '1') ELSE
                     '0';
   fixedclk_in(2) <= '1' WHEN (fixedclk(2) = '1') ELSE
                     '0';
   fixedclk_in(3) <= '1' WHEN (fixedclk(3) = '1') ELSE
                     '0';
   fixedclk_in(4) <= '0'; -- cycloneiv_modify
   fixedclk_in(5) <= '0'; -- cycloneiv_modify
   
   --assign quadenable_in        = (quadenable  === 1'b0)      ? 1'b0 : 1'b1;
   quadreset_in <= '1' WHEN (quadreset = '1') ELSE
                   '0';
   rxanalogreset_in(0) <= '1' WHEN (rxanalogreset(0) = '1') ELSE
                          '0';
   rxanalogreset_in(1) <= '1' WHEN (rxanalogreset(1) = '1') ELSE
                          '0';
   rxanalogreset_in(2) <= '1' WHEN (rxanalogreset(2) = '1') ELSE
                          '0';
   rxanalogreset_in(3) <= '1' WHEN (rxanalogreset(3) = '1') ELSE
                          '0';
   rxanalogreset_in(4) <= '0'; -- cycloneiv_modify
   rxanalogreset_in(5) <= '0'; -- cycloneiv_modify
   
   rxclk_in <= '1' WHEN (rxclk = '1') ELSE
               '0';
   rxdigitalreset_in(0) <= '1' WHEN (rxdigitalreset(0) = '1') ELSE
                           '0';
   rxdigitalreset_in(1) <= '1' WHEN (rxdigitalreset(1) = '1') ELSE
                           '0';
   rxdigitalreset_in(2) <= '1' WHEN (rxdigitalreset(2) = '1') ELSE
                           '0';
   rxdigitalreset_in(3) <= '1' WHEN (rxdigitalreset(3) = '1') ELSE
                           '0';
   rxpowerdown_in(0) <= '0' WHEN (rxpowerdown(0) = '1') ELSE        --inverted
                        '1';
   rxpowerdown_in(1) <= '0' WHEN (rxpowerdown(1) = '1') ELSE        --inverted
                        '1';
   rxpowerdown_in(2) <= '0' WHEN (rxpowerdown(2) = '1') ELSE        --inverted
                        '1';
   rxpowerdown_in(3) <= '0' WHEN (rxpowerdown(3) = '1') ELSE        --inverted
                        '1';
   rxpowerdown_in(4) <= '1';    --inverted -- cycloneiv_modify
   rxpowerdown_in(5) <= '1';    --inverted -- cycloneiv_modify
   
   txclk_in <= '1' WHEN (txclk = '1') ELSE
               '0';
   txdigitalreset_in(0) <= '1' WHEN (txdigitalreset(0) = '1') ELSE
                           '0';
   txdigitalreset_in(1) <= '1' WHEN (txdigitalreset(1) = '1') ELSE
                           '0';
   txdigitalreset_in(2) <= '1' WHEN (txdigitalreset(2) = '1') ELSE
                           '0';
   txdigitalreset_in(3) <= '1' WHEN (txdigitalreset(3) = '1') ELSE
                           '0';
   txpllreset_in(0) <= '1' WHEN (txpllreset(0) = '1') ELSE
                       '0';
   txpllreset_in(1) <= '1' WHEN (txpllreset(1) = '1') ELSE
                       '0';
   
   -- new one added in ww47
   rateswitch_in <= rateswitch;
   rateswitchdonein_in <= rateswitchdonein;
   rxcoreclk_in <= rxcoreclk;
   rxphfifordenable_in <= rxphfifordenable;
   rxphfiforeset_in <= rxphfiforeset;
   rxphfifowrdisable_in <= rxphfifowrdisable;
   scanclk_in <= '1' WHEN (scanclk = '1') ELSE
                 '0';
   scanin_in <= "00000000000000000000001" WHEN (scanin = "00000000000000000000001") ELSE
                "00000000000000000000000";
   scanmode_in <= '1' WHEN (scanmode = '1') ELSE
                  '0';
   scanshift_in <= '1' WHEN (scanshift = '1') ELSE
                   '0';
   txcoreclk_in <= txcoreclk;
   txphfiforddisable_in <= txphfiforddisable;
   txphfiforeset_in <= txphfiforeset;
   txphfifowrenable_in <= txphfifowrenable;
   
   --///////////////////////////////////////////////////////////////////////////
   -- TIMING -- TCO/TSU/HOLD                                                  //
   --///////////////////////////////////////////////////////////////////////////
   
   dprioout <= dprioout_tim;
   dpriooe <= dpriooe_tim;
   
   --/////////////////////////////////////////////////////////////////////////
   -- quad_reset inst ----------------------------------------------------- //
   --/////////////////////////////////////////////////////////////////////////
   
   qr_in_entest <= '0';        -- Test mode control from Control block
   qr_in_plniotri <= '1';        -- PLL output enable
   qr_in_npor <= '1';        -- Power on reset
   qr_in_frzreg <= '0';        -- Freeze register during power-up
   qr_in_pllurst <= '1' WHEN (quadreset_in = '1') ELSE        -- PLL user reset
                    '0';
   
   -- enable corresponding port by default in simulation
   qr_cram_rpllurst <= '1';        -- Gating CRAM for PLLURST
   qr_cram_rpowerdown <= '0';        -- Quad power down CRAM
   qr_cram_rreset <= '0';        -- Quad reset CRAM - scan_mode ? 1'b0 : rreset;
   
   -- new in ww47 ----------------------------------------------------
   
   -- CMU0/1 reset - moved rx_pll, rx_pma and tx_pma resets to chnl reset [4:5] 
   -- but kept CMU_PLL (LC_PLL) resets in Quadreset 
   qr_in_rxurstcmu <= txpllreset_in;
   qr_in_ucmurx_pdb <= "00";
   
   -- CMU qr_cram_reset CRAMs
   qr_cram_rrxurstcmu <= "11";        -- Gating CRAM for dynamic signal rxurstcmu
   qr_cram_rrx_cmu_rst <= "00";        -- TXPLL / RXPLL reset
   
   -- CMU powerdown CRAMs
   qr_cram_rclk_pdb <= "00";        --generating cmu0/1_clk_pdb
   qr_cram_rcmu_powdnr <= "00";
   qr_cram_rcmu_cru_pdb <= "11";
   qr_cram_rcmu_urx_pdb <= "11";
   qr_cram_rcmu_rx_ib_pdb <= "11";
   qr_cram_rcmu_powdnt <= "00";
   qr_cram_rcmu_tx_ob_pdb <= "11";
   qr_cram_rcmu_tx_cgb_pdb <= "11";
   qr_cram_rcmu_rx_det_pdb <= "11";
   
   -- Moved cmu0/cmu1 reset/powerdown out to channel reset
   -- still controls cmu_pll/cmu_clk_divider and hardreset
   
   
   quad_reset_1 : cycloneiv_hssi_cmu_quad_reset
      PORT MAP (
         entest               => qr_in_entest,
         plniotri             => qr_in_plniotri,
         npor                 => qr_in_npor,
         frzreg               => qr_in_frzreg,
         pllurst              => qr_in_pllurst,
         rpllurst             => qr_cram_rpllurst,
         rreset               => qr_cram_rreset,
         rpowerdown           => qr_cram_rpowerdown,
         
         -- CMU reset inputs
         rxurstcmu            => qr_in_rxurstcmu,
         -- CMU reset CRAMs
         rrxurstcmu           => qr_cram_rrxurstcmu,
         rrx_cmu_rst          => qr_cram_rrx_cmu_rst,
         -- CMU powerdown inputs
         ucmurx_pdb           => qr_in_ucmurx_pdb,
         -- CMU powerdown CRAMs
         rclk_pdb             => qr_cram_rclk_pdb,
         rcmu_powdnr          => qr_cram_rcmu_powdnr,
         rcmu_cru_pdb         => qr_cram_rcmu_cru_pdb,
         rcmu_urx_pdb         => qr_cram_rcmu_urx_pdb,
         rcmu_rx_ib_pdb       => qr_cram_rcmu_rx_ib_pdb,
         rcmu_powdnt          => qr_cram_rcmu_powdnt,
         rcmu_tx_ob_pdb       => qr_cram_rcmu_tx_ob_pdb,
         rcmu_tx_cgb_pdb      => qr_cram_rcmu_tx_cgb_pdb,
         rcmu_rx_det_pdb      => qr_cram_rcmu_rx_det_pdb,
         -- CMU reset outputs
         cmu0_rxpma_rstb      => qr_out_cmu0_rxpma_rstb,
         cmu0_txpma_rstb      => qr_out_cmu0_txpma_rstb,
         cmu0_cru_rstb        => qr_out_cmu0_cru_rstb,
         cmu1_rxpma_rstb      => qr_out_cmu1_rxpma_rstb,
         cmu1_txpma_rstb      => qr_out_cmu1_txpma_rstb,
         cmu1_cru_rstb        => qr_out_cmu1_cru_rstb,
         -- CMU powerdown outputs
         cmu0_rx_pdb          => qr_out_cmu0_rx_pdb,
         cmu0_cru_pdb         => qr_out_cmu0_cru_pdb,
         cmu0_clk_pdb         => qr_out_cmu0_clk_pdb,
         cmu0_tx_pdb          => qr_out_cmu0_tx_pdb,
         cmu0_cgb_pdb         => qr_out_cmu0_cgb_pdb,
         cmu0_rx_det_pdb      => qr_out_cmu0_rx_det_pdb,
         cmu1_rx_pdb          => qr_out_cmu1_rx_pdb,
         cmu1_cru_pdb         => qr_out_cmu1_cru_pdb,
         cmu1_clk_pdb         => qr_out_cmu1_clk_pdb,
         cmu1_tx_pdb          => qr_out_cmu1_tx_pdb,
         cmu1_cgb_pdb         => qr_out_cmu1_cgb_pdb,
         cmu1_rx_det_pdb      => qr_out_cmu1_rx_det_pdb,
         -- Other outputs
         mdio_rst             => qr_out_mdio_rst,
         hard_reset           => qr_out_hard_reset,
         soft_reset_all_hssi  => qr_out_soft_reset_all_hssi
      );
   
   --/////////////////////////////////////////////////////////////////////////
   -- chnl_reset inst ----------------------------------------------------- //
   --/////////////////////////////////////////////////////////////////////////
   
   chr_in_hard_reset <= qr_out_hard_reset;        -- hardreset signal
   chr_in_soft_reset_all_hssi <= qr_out_soft_reset_all_hssi;        -- soft reset for all channel
   chr_in_rreset <= qr_cram_rreset;        -- Quad reset CRAM
   chr_in_rpowerdown <= qr_cram_rpowerdown;        -- Quad power down CRAM
   
   -- Channel Reset inputs
   chr_in_rxurstpma <= rxanalogreset_in;        -- RX PMA user reset
   chr_in_rxurstpcs <= rxdigitalreset_in;        -- RX PCS user reset
   chr_in_txurstpcs <= txdigitalreset_in;        -- TX PCS user reset
   
   -- Channel Reset CRAMs
   chr_in_rpowdnr <= '0';        -- RX channel power down CRAM
   chr_in_rpowdnt <= '0';        -- TX channel power down CRAM
   chr_in_rrxurstpcs <= '1';        -- Gating CRAM for RXURSTPCS
   chr_in_rtxurstpcs <= '1';        -- Gating CRAM for TXURSTPCS
   chr_in_rrxurstpma <= '1';        -- Gating CRAM for RXURSTPMA
   chr_in_rrx_cru_rst <= '0';        -- Channel RX PLL reset CRAMs
   chr_in_radce_rst <= '0';        -- Channel Adaptive block reset CRAMs
   
   -- Powerdown inputs
   chr_in_urx_pdb <= rxpowerdown_in;        -- RX user powerdown signal
   
   -- Powerdown CRAMs - active low
   chr_in_rurx_pdb <= '1';        -- Gating CRAM for urx_pdb signals
   chr_in_radce_pdb <= '1';        -- Adaptive block powerdown CRAMs
   chr_in_rrx_ib_pdb <= '1';        -- RX Input buffer and PLL powerdown CRAMs
   chr_in_rtx_ob_pdb <= '1';        -- TX Output buffer powerdown CRAMs
   chr_in_rtx_cgb_pdb <= '1';        -- TX clock generator powerdown CRAMs
   chr_in_rrx_cru_pdb <= '1';        -- RX PLL powerdown CRAMs
   
   -- PIPE Inputs
   chr_in_rtx_pipe_en <= '0';        -- PIPE enable CRAMs
   --todo: revisit - signal from tx_PIPE_INTERFACE_TOP
   chr_in_p0_state <= '0';        -- PIPE P0 state indicators
   chr_in_p0s_state <= '0';        -- PIPE P0S state indicators
   chr_in_p2_state <= '0';        -- PIPE P2 state indicators
   
   -- Channel-based reset logic (for both PCS and PMA channel)                          
