         txpma_rstb           => chr_out_txpma_rstb(4),
         rxpcs_rst            => dummy_wire,
         txpcs_rst            => dummy_wire,
         cru_rstb             => chr_out_cru_rstb(4),
         adce_rstb            => dummy_wire,
         adce_pdb             => dummy_wire,
         cru_pdb              => chr_out_cru_pdb(4),
         rx_pdb               => chr_out_rx_pdb(4),
         tx_pdb               => chr_out_tx_pdb(4),
         cgb_pdb              => chr_out_cgb_pdb(4),
         rx_det_pdb           => chr_out_rx_det_pdb(4)
      );
   -- channel 5
   
   cmu1_reset : cycloneiv_hssi_cmu_chnl_reset
      PORT MAP (
         hard_reset           => chr_in_hard_reset,
         soft_reset_all_hssi  => chr_in_soft_reset_all_hssi,
         rreset               => chr_in_rreset,
         rpowerdown           => chr_in_rpowerdown,
         rxurstpma            => chr_in_rxurstpma(5),
         rxurstpcs            => gnd_wire,
         txurstpcs            => gnd_wire,
         rpowdnr              => chr_in_rpowdnr,
         rpowdnt              => chr_in_rpowdnt,
         rrxurstpcs           => chr_in_rrxurstpcs,
         rtxurstpcs           => chr_in_rtxurstpcs,
         rrxurstpma           => chr_in_rrxurstpma,
         rrx_cru_rst          => chr_in_rrx_cru_rst,
         radce_rst            => chr_in_radce_rst,
         urx_pdb              => chr_in_urx_pdb(5),
         rurx_pdb             => chr_in_rurx_pdb,
         radce_pdb            => chr_in_radce_pdb,
         rrx_ib_pdb           => chr_in_rrx_ib_pdb,
         rtx_ob_pdb           => chr_in_rtx_ob_pdb,
         rtx_cgb_pdb          => chr_in_rtx_cgb_pdb,
         rrx_cru_pdb          => chr_in_rrx_cru_pdb,
         rtx_pipe_en          => chr_in_rtx_pipe_en,
         p0_state             => chr_in_p0_state,
         p0s_state            => chr_in_p0s_state,
         p2_state             => chr_in_p2_state,
         
         rxpma_rstb           => chr_out_rxpma_rstb(5),
         txpma_rstb           => chr_out_txpma_rstb(5),
         rxpcs_rst            => dummy_wire,
         txpcs_rst            => dummy_wire,
         cru_rstb             => chr_out_cru_rstb(5),
         adce_rstb            => dummy_wire,
         adce_pdb             => dummy_wire,
         cru_pdb              => chr_out_cru_pdb(5),
         rx_pdb               => chr_out_rx_pdb(5),
         tx_pdb               => chr_out_tx_pdb(5),
         cgb_pdb              => chr_out_cgb_pdb(5),
         rx_det_pdb           => chr_out_rx_det_pdb(5)
      );
   
   --/////////////////////////////////////////////////////////////////////////
   -- centrl_clk_ctl ------------------------------------------------------ //
   --/////////////////////////////////////////////////////////////////////////
   
   refclk_pma_out <= centrlclk_ctl_out_refclk_pma_out;        -- txclk_in <= pclk/digitalrefclkout
   mdc_b <= centrlclk_ctl_out_mdc_b;        -- dpclk_in;
   
   -- refclk_out is moved to (cmu) clock_divider atom:
   -- it has /2 and gen2ngen1 bundle logic and rfreq_sel control
   
   centrlclk_ctl_in_pclk_pma <= txclk_in;        --todo: WYS to add x4 PCLK from PMA CMU
   centrlclk_ctl_in_refclk_dig <= txclk_in;        --todo: External digital clock - moved to cmu_clock_divider
   centrlclk_ctl_in_mdc <= dpclk_in;        -- MDIO input clock
   centrlclk_ctl_in_ser_clk <= '0';        -- Serial clock
   centrlclk_ctl_in_ser_mode <= '0';        -- Serial shift configuration mode
   centrlclk_ctl_in_scan_mode <= scanmode_in;        -- Scan mode
   centrlclk_ctl_in_scan_clk <= scanclk_in;        -- Scan mode
   centrlclk_ctl_in_hard_reset <= qr_out_hard_reset;        -- Hard reset input
   centrlclk_ctl_in_txrst <= txrst_int;
   
   centrlclk_ctl_in_gen2ngen1_bundle <= rateswitchdonein_in;
   
   mcmu_centrlclk_ctl : cycloneiv_hssi_cmu_clk_ctl
      PORT MAP (
         pclk_pma          => centrlclk_ctl_in_pclk_pma,
         refclk_dig        => centrlclk_ctl_in_refclk_dig,
         mdc               => centrlclk_ctl_in_mdc,
         ser_clk           => centrlclk_ctl_in_ser_clk,
         ser_mode          => centrlclk_ctl_in_ser_mode,
         scan_mode         => centrlclk_ctl_in_scan_mode,
         scan_clk          => centrlclk_ctl_in_scan_clk,
         rfreerun_centrl   => cram_rfreerun_centrl,
         rcentrl_clk_sel   => cram_rcentrl_clk_sel,
         rrefclk_out_div2  => cram_rrefclk_out_div2,
         hard_reset        => centrlclk_ctl_in_hard_reset,
         txrst             => centrlclk_ctl_in_txrst,
         rauto_speed_ena   => cram_rauto_speed_ena,
         rfreq_sel         => cram_rfreq_sel,
         gen2ngen1_bundle  => centrlclk_ctl_in_gen2ngen1_bundle,
         
         refclk_pma_out    => centrlclk_ctl_out_refclk_pma_out,
         mdc_b             => centrlclk_ctl_out_mdc_b,
         refclk_out        => centrlclk_ctl_out_refclk_out
      );
   
   --/////////////////////////////////////////////////////////////////////////
   -- rxclk_ctl_ctrl inst ------------------------------------------------- //
   --/////////////////////////////////////////////////////////////////////////
   
   -- for S2GX portion
   clk_1_b <= rxclk_ctl_out_clk_1_b;        --recovclk - from ch0 of recover_clk
   clk_2_b <= rxclk_ctl_out_clk_2_b;        --rxclk_in - masterclk in XAUI, not work for other x4
   
   -- for CYCLONEIV bundling - 
   -- - copy rx_ch0 clocking select info here to generate FIFO_bundle_ptrs_centrl
   rxclk_ctl_in_pld_rx_clk <= rxcoreclk_in;
   rxclk_ctl_in_rcvd_clk0_pma <= recovclk;
   rxclk_ctl_in_refclk_pma <= centrlclk_ctl_out_refclk_pma_out;
   rxclk_ctl_in_scan_mode <= scanmode_in;
   rxclk_ctl_in_gen2ngen1_bundle <= rateswitchdonein_in;
   rxclk_ctl_in_rx_div2_sync_centrl <= rxclk_ctl_out_rx_div2_sync_out;
   rxclk_ctl_in_rxrst <= txrst_int;        -- from centrl_reset                 
   
   mcmu_rxclk_ctl : cycloneiv_hssi_cmu_rxclk_ctl
      PORT MAP (
         pld_rx_clk              => rxclk_ctl_in_pld_rx_clk,
         rcvd_clk_pma            => gnd_wire,
         rcvd_clk0_pma           => rxclk_ctl_in_rcvd_clk0_pma,
         tx_pma_clk              => gnd_wire,
         refclk_pma              => rxclk_ctl_in_refclk_pma,
         fref                    => gnd_wire,
         clklow                  => gnd_wire,
         scan_mode               => rxclk_ctl_in_scan_mode,
         gen2ngen1               => rxclk_ctl_in_gen2ngen1_bundle,   -- ww35.2008 gnd_wire,
         gen2ngen1_bundle        => rxclk_ctl_in_gen2ngen1_bundle,
         rx_div2_sync_centrl     => rxclk_ctl_in_rx_div2_sync_centrl,
         rx_div2_sync_quad_up    => gnd_wire,
         rx_div2_sync_quad_down  => gnd_wire,
         rrcvd_clk_sel           => cram_rrcvd_clk_sel,
         rclk_1_sel              => cram_rclk_1_sel,
         rclk_2_sel              => cram_rclk_2_sel,
         rrx_rd_clk_sel          => cram_rrx_rd_clk_sel,
         
         rxrst                   => rxclk_ctl_in_rxrst,
         
         rindv_rx                => vcc_wire,   -- ww35.2008 cram_rindv_rx,
         rdwidth_rx              => cram_rdwidth_rx,
         rfreerun_rx             => cram_rfreerun_rx,
         rauto_speed_ena         => cram_rauto_speed_ena,
         rfreq_sel               => cram_rfreq_sel,
         rrxpcsclkpwdn           => gnd_wire,
         rmaster_rx              => vcc_wire,   -- ww35.2008 cram_rmaster_rx,
         rmaster_up_rx           => cram_rmaster_up_rx,
         rself_sw_en_rx          => gnd_wire,
         
         fref_muxed              => rxclk_ctl_out_fref_muxed,
         clklow_muxed            => rxclk_ctl_out_clklow_muxed,
         rcvd_clk                => rxclk_ctl_out_rcvd_clk,
         clk_1_b                 => rxclk_ctl_out_clk_1_b,
         clk_2_b                 => rxclk_ctl_out_clk_2_b,
         rx_wr_clk               => rxclk_ctl_out_rx_wr_clk,
         rx_rd_clk               => rxclk_ctl_out_rx_rd_clk,
         rx_clk                  => rxclk_ctl_out_rx_clk,
         rcvd_clk_pma_b          => rxclk_ctl_out_rcvd_clk_pma_b,
         clk_2_b_raw             => rxclk_ctl_out_clk_2_b_raw,
         rx_wr_clk_raw           => rxclk_ctl_out_rx_wr_clk_raw,
         rx_rd_clk_raw           => rxclk_ctl_out_rx_rd_clk_raw,
         rx_div2_sync_out        => rxclk_ctl_out_rx_div2_sync_out
      );
   
   --/////////////////////////////////////////////////////////////////////////
   -- txclk_ctl_centrl inst ------------------------------------------------- //
   --/////////////////////////////////////////////////////////////////////////
   -- s2gx style
   refclk_b <= refclk_pma_out;        -- output to centrl_reset and TX_SM
   
   -- CYCLONEIV for bundling
   txclk_ctl_in_pld_tx_clk <= txcoreclk_in;
   txclk_ctl_in_refclk_pma <= centrlclk_ctl_out_refclk_pma_out;
   txclk_ctl_in_txrst <= txrst_int;
   txclk_ctl_in_scan_mode <= scanmode_in;
   txclk_ctl_in_gen2ngen1_bundle <= rateswitchdonein_in;
   txclk_ctl_in_tx_div2_sync_centrl <= txclk_ctl_out_tx_div2_sync_out;
   
   -- Clock selection logic and muxes for refclk_b
   
   mcmu_txclk_ctl : cycloneiv_hssi_cmu_txclk_ctl
      PORT MAP (
         pld_tx_clk              => txclk_ctl_in_pld_tx_clk,
         refclk_pma              => txclk_ctl_in_refclk_pma,
         txpma_local_clk         => gnd_wire,
         txrst                   => txclk_ctl_in_txrst,
         scan_mode               => txclk_ctl_in_scan_mode,
         gen2ngen1               => txclk_ctl_in_gen2ngen1_bundle, -- ww35.2008 gnd_wire,
         gen2ngen1_bundle        => txclk_ctl_in_gen2ngen1_bundle,
         tx_div2_sync_centrl     => txclk_ctl_out_tx_div2_sync_out,
         tx_div2_sync_quad_up    => gnd_wire,
         tx_div2_sync_quad_down  => gnd_wire,
         rindv_tx                => vcc_wire,  -- ww35.2008 cram_rindv_tx,
         rtxwrclksel             => cram_rtxwrclksel,
         rtxrdclksel             => cram_rtxrdclksel,
         rdwidth_tx              => cram_rdwidth_tx,
         rfreerun_tx             => cram_rfreerun_tx,
         rauto_speed_ena         => cram_rauto_speed_ena,
         rfreq_sel               => cram_rfreq_sel,
         rtxpcsclkpwdn           => gnd_wire,
         rmaster_tx              => vcc_wire,  -- ww35.2008 cram_rmaster_tx,
         rmaster_up_tx           => cram_rmaster_up_tx,
         rself_sw_en_tx          => gnd_wire,
         
         refclk_b                => txclk_ctl_out_refclk_b,
         wr_clk_pos              => txclk_ctl_out_wr_clk_pos,
         fifo_rd_clk             => txclk_ctl_out_fifo_rd_clk,
         tx_clk_out              => txclk_ctl_out_tx_clk_out,
         refclk_b_raw            => txclk_ctl_out_refclk_b_raw,
         wr_clk_pos_raw          => txclk_ctl_out_wr_clk_pos_raw,
         fifo_rd_clk_raw         => txclk_ctl_out_fifo_rd_clk_raw,
         tx_div2_sync_out        => txclk_ctl_out_tx_div2_sync_out
      );
   
   --/////////////////////////////////////////////////////////////////////////
   -- centrl_reset -------------------------------------------------------- //
   --/////////////////////////////////////////////////////////////////////////
   
   PROCESS (qr_out_hard_reset, clk_2_b)
VARIABLE  txt : LINE;
   BEGIN
      IF (qr_out_hard_reset = '1') THEN
         rxrst_sync2 <= '1';
         rxrst_sync1 <= '1';
      ELSIF (clk_2_b'EVENT AND clk_2_b = '1') THEN
         rxrst_sync2 <=  TRANSPORT rxrst_sync1 AFTER 1 ps;
         rxrst_sync1 <= chr_out_rxpcs_rst(0);
      END IF;
   END PROCESS;
   
   
   PROCESS (qr_out_hard_reset, refclk_b)
VARIABLE  txt : LINE;
   BEGIN
      IF (qr_out_hard_reset = '1') THEN
         txrst_sync2 <= '1';
         txrst_sync1 <= '1';
      ELSIF (refclk_b'EVENT AND refclk_b = '1') THEN
         txrst_sync2 <=  TRANSPORT txrst_sync1 AFTER 1 ps;
         txrst_sync1 <= chr_out_txpcs_rst(0);
      END IF;
   END PROCESS;
   
   
   txrst_int <= txrst_sync2;
   rxrst_int <= rxrst_sync2;
   
   --/////////////////////////////////////////////////////////////////////////
   -- auto_speed_neg ------------------------------------------------------ //
   --/////////////////////////////////////////////////////////////////////////
   
   auto_in_refclk <= rxclk_ctl_out_clk_2_b;
   auto_in_rxpcs_rst_int <= rxrst_int;
   auto_in_rate <= rateswitch_in;        -- high gen2 and low gen1 
   auto_in_gen2ngen1 <= rateswitchdonein_in;
   auto_in_config_sel_centrl <= auto_out_config_sel;
   auto_in_config_sel_quad_up <= '0';
   auto_in_config_sel_quad_down <= '0';
   auto_in_singleorbundle <= (NOT(cram_rindv_rx) AND cram_rmaster_rx);
   
   mcmu_auto : cycloneiv_hssi_cmu_auto_speed_neg
      PORT MAP (
         refclk                     => auto_in_refclk,
         rxpcs_rst_int              => auto_in_rxpcs_rst_int,
         rate                       => auto_in_rate,
         gen2ngen1                  => auto_in_gen2ngen1,
         config_sel_centrl          => auto_in_config_sel_centrl,
         config_sel_quad_up         => auto_in_config_sel_quad_up,
         config_sel_quad_down       => auto_in_config_sel_quad_down,
         rindv_rx                   => cram_rindv_rx,
         rmaster_rx                 => cram_rmaster_rx,
         rmaster_up_rx              => cram_rmaster_up_rx,
         rauto_speed_ena            => cram_rauto_speed_ena,
         singleorbundle             => auto_in_singleorbundle,
         rphfifo_regmode_rx         => cram_rphfifo_regmode_rx,
         rpma_done_count            => cram_rpma_done_count,
         rauto_deassert_pc_rst_cnt  => cram_rauto_deassert_pc_rst_cnt,
         rauto_pc_en_cnt            => cram_rauto_pc_en_cnt,
         rwait_for_phfifo_cnt       => cram_rwait_for_phfifo_cnt,         
         config_sel                 => auto_out_config_sel,
         pcie_switch                => auto_out_pcie_switch,
         speed_change               => auto_out_speed_change,
         dis_pc_byte                => auto_out_dis_pc_byte,
         reset_pc_ptrs              => auto_out_reset_pc_ptrs,
         cs                         => auto_out_cs
      );
   
   --/////////////////////////////////////////////////////////////////////////
   -- rx_ctl_ctrl --------------------------------------------------------- //
   --/////////////////////////////////////////////////////////////////////////
   rxctrl_in_soft_reset <= rxrst_int;        -- from centrl_reset
   rxctrl_in_clk_2 <= rxclk_ctl_out_clk_2_b;
   rxctrl_in_rx_rd_clk <= rxclk_ctl_out_rx_rd_clk;
   rxctrl_in_rx_wr_clk <= rxclk_ctl_out_rx_wr_clk;
   rxctrl_in_scan_mode <= scanmode_in;
   rxctrl_in_rxfifo_urst <= rxphfiforeset_in;
   rxctrl_in_pld_wr_dis <= rxphfifowrdisable_in;
   rxctrl_in_pld_re <= rxphfifordenable_in;
   rxctrl_in_dis_pc_byte <= auto_out_dis_pc_byte;
   
   mcmu_rx_ctrl : cycloneiv_hssi_cmu_rx_ctrl
      PORT MAP (
         soft_reset          => rxctrl_in_soft_reset,
         clk_2               => rxctrl_in_clk_2,
         rx_rd_clk           => rxctrl_in_rx_rd_clk,
         rx_wr_clk           => rxctrl_in_rx_wr_clk,
         scan_mode           => rxctrl_in_scan_mode,
         rrxfifo_urst_en     => cram_rrxfifo_urst_en,
         rxfifo_urst         => rxctrl_in_rxfifo_urst,
         rrxphfifopldctl_en  => cram_rrxphfifopldctl_en,
         pld_wr_dis          => rxctrl_in_pld_wr_dis,
         pld_re              => rxctrl_in_pld_re,
         dis_pc_byte         => rxctrl_in_dis_pc_byte,
         rauto_speed_ena     => cram_rauto_speed_ena,
         
         rx_we_out           => rxctrl_out_rx_we_out,
         wr_enable_out       => rxctrl_out_wr_enable_out,
         rd_enable_out       => rxctrl_out_rd_enable_out
      );
   
   --/////////////////////////////////////////////////////////////////////////
   -- rx_ctl_ctrl --------------------------------------------------------- //
   --/////////////////////////////////////////////////////////////////////////
   txctrl_in_soft_reset <= txrst_int;
   txctrl_in_fifo_wr_clk <= txclk_ctl_out_wr_clk_pos;
   txctrl_in_fifo_rd_clk <= txclk_ctl_out_fifo_rd_clk;
   txctrl_in_refclk_b_in <= txclk_ctl_out_refclk_b;
   txctrl_in_scan_mode <= scanmode_in;
   txctrl_in_txfifo_urst <= txphfiforeset_in;
   txctrl_in_pld_we <= txphfifowrenable_in;
   txctrl_in_pld_rd_dis <= txphfiforddisable_in;
   txctrl_in_dis_pc_byte <= auto_out_dis_pc_byte;
   
   mcmu_tx_ctrl : cycloneiv_hssi_cmu_tx_ctrl
      PORT MAP (
         soft_reset          => txctrl_in_soft_reset,
         fifo_wr_clk         => txctrl_in_fifo_wr_clk,
         fifo_rd_clk         => txctrl_in_fifo_rd_clk,
         refclk_b_in         => txctrl_in_refclk_b_in,
         scan_mode           => txctrl_in_scan_mode,
         rtxfifo_urst_en     => cram_rtxfifo_urst_en,
         txfifo_urst         => txctrl_in_txfifo_urst,
         rtxphfifopldctl_en  => cram_rtxphfifopldctl_en,
         pld_we              => txctrl_in_pld_we,
         pld_rd_dis          => txctrl_in_pld_rd_dis,
         dis_pc_byte         => txctrl_in_dis_pc_byte,
         rauto_speed_ena     => cram_rauto_speed_ena,
         
         wr_enable_out       => txctrl_out_wr_enable_out,
         rd_enable_out       => txctrl_out_rd_enable_out,
         fifo_select_out     => txctrl_out_fifo_select_out
      );
   
   
   --/////////////////////////////////////////////////////////////////////////
   -- instantiate DSKW SM ------------------------------------------------- //
   --/////////////////////////////////////////////////////////////////////////
   
   dskw_sm_clk <= clk_1_b WHEN (init_in_xaui_mode = '1') ELSE
                  '0';
   
   --.clk_1        (clk_1_b),
   xhdl13 <= ("1111" & adet);
   xhdl14 <= ("1111" & rdalign);
   xhdl15 <= ("1111" & syncstatus);
   dskw_sm_1 : cycloneiv_hssi_dskw_sm
      PORT MAP (
         soft_reset      => rxrst_int,
         clk_1           => dskw_sm_clk,
         octal_mode      => '0',
         align_det_sync  => xhdl13,
         rd_align        => xhdl14,
         sync_status     => xhdl15,
         align_status    => alignstatus_int,
         enable_deskew   => enabledeskew_xhdl2,
         fifo_reset_rd   => fiforesetrd_xhdl3,
         curr_state      => dskw_curr_st
      );
   
   --/////////////////////////////////////////////////////////////////////////
   -- instantiate TX SM --------------------------------------------------- //
   --/////////////////////////////////////////////////////////////////////////
   
   tx_sm_clk <= refclk_b WHEN (init_in_xaui_mode = '1') ELSE
                '0';
   tx_sm_datain <= txdatain WHEN (init_in_xaui_mode = '1') ELSE
                   "00000000000000000000000000000000";
   tx_sm_ctrlin <= txctrl WHEN (init_in_xaui_mode = '1') ELSE
                   "0000";
   tx_sm_rdenablesyncin <= rdenablesync WHEN (init_in_xaui_mode = '1') ELSE
                           '0';
   
   rtx_rx_local_fault_clr_int <= '0';
   rindv_tx_int <= '0';        -- tx sm just sends K when set
   
   tx_sm_1 : cycloneiv_hssi_tx_sm
      PORT MAP (
         tx_clk              => tx_sm_clk,
         --.tx_clk             (refclk_b),
         soft_reset          => txrst_int,
         indv                => rindv_tx_int,
         tx_data             => tx_sm_datain,
         --.tx_data            (txdatain),
         tx_ctl              => tx_sm_ctrlin,
         --.tx_ctl             (txctrl),
         rd_enable_sync      => tx_sm_rdenablesyncin,
         --.rd_enable_sync     (rdenablesync), 
         tx_local_fault_clr  => gnd_wire,        --shared with tx_sm
         sm_data             => txdataout_xhdl10,
         sm_ctl              => txctrlout_xhdl9,
         tx_local_fault_det  => tx_local_fault_det,        -- to rcv_sm
         tx_local_fault      => tx_local_fault_int,
         curr_state          => tx_curr_st,
         rxaui_s2gx_en       => cram_rxaui_s2gx_en_tx         
      );
   
   --/////////////////////////////////////////////////////////////////////////
   -- instantiate RX SM --------------------------------------------------- //
   --/////////////////////////////////////////////////////////////////////////
   
   rcv_sm_clk <= clk_2_b WHEN (init_in_xaui_mode = '1') ELSE
                 '0';
   rcv_sm_decdatavalid <= rxdatavalid WHEN (init_in_xaui_mode = '1') ELSE
                          "0001";
   rcv_sm_decdata <= rxdatain WHEN (init_in_xaui_mode = '1') ELSE
                     "00000000000000000000000000000000";
   rcv_sm_decctl <= rxctrl WHEN (init_in_xaui_mode = '1') ELSE
                    "0000";
   rcv_sm_rxrunningdisp <= rxrunningdisp WHEN (init_in_xaui_mode = '1') ELSE
                           "0000";
   
   rindv_rx_int <= '0';
   rxs_link_status_set_int <= '0';
   
   rcv_sm_1 : cycloneiv_hssi_rcv_sm
      PORT MAP (
         clk_2               => rcv_sm_clk,
         soft_reset          => rxrst_int,
         indv                => rindv_rx_int,
         dec_data_valid      => rcv_sm_decdatavalid,
         dec_data            => rcv_sm_decdata,
         dec_ctl             => rcv_sm_decctl,
         running_disp        => rcv_sm_rxrunningdisp,
         rx_local_fault_clr  => gnd_wire,        --shared with tx_sm
         xs_link_status_set  => gnd_wire,
         tx_local_fault_det  => tx_local_fault_det,        -- from tx_sm
         rx_data_rs          => rxdataout_xhdl6,
         rx_ctl_rs           => rxctrlout_xhdl5,
         rx_local_fault      => rx_local_fault_int,
         xs_link_status      => xs_link_status_int,
         curr_state          => rcv_curr_st,
         rxaui_s2gx_en       => cram_rxaui_s2gx_en_rx         
      );
   
   --/////////////////////////////////////////////////////////////////////////
   -- instantiate DPRIO_CONTROL_TOP --------------------------------------- //
   --/////////////////////////////////////////////////////////////////////////
   
   port_addr <= int2bin(portaddr, 5) - "00001";        --port_address-1;   int (1-based into 0-based) to 5'b conversion
   dev_addr <= int2bin(devaddr, 5) - "00001";        --device_address-1; int (1-based into 0-based)to 5'b conversion
   
   mdio_in <= dprioin_in;
   mdio_rst <= mdio_rst_reg;        -- ~(plniotri & ~entest & npor);
   PROCESS 
   BEGIN
      mdio_rst_reg <= '1';
      WAIT FOR 1000 ps;
      mdio_rst_reg <= '0';
      WAIT;
   END PROCESS;
   
   cmudprioin <= "00000000000000000000000000000X";
   
   control_top_0 : cycloneiv_hssi_cmu_dprio_top
      GENERIC MAP (
     
         rx0_logical_to_physical_mapping             => rx0_logical_to_physical_mapping,
         rx1_logical_to_physical_mapping             => rx1_logical_to_physical_mapping,
         rx2_logical_to_physical_mapping             => rx2_logical_to_physical_mapping,
         rx3_logical_to_physical_mapping             => rx3_logical_to_physical_mapping,
         tx0_logical_to_physical_mapping             => tx0_logical_to_physical_mapping,
         tx1_logical_to_physical_mapping             => tx1_logical_to_physical_mapping,
         tx2_logical_to_physical_mapping             => tx2_logical_to_physical_mapping,
         tx3_logical_to_physical_mapping             => tx3_logical_to_physical_mapping,
         
         sim_dump_dprio_internal_reg_at_time  => sim_dump_dprio_internal_reg_at_time,
         sim_dump_filename                    => sim_dump_filename
      )
      PORT MAP (
         refclkdividerdprioin   => refclkdividerdprioin,
         rxpcsdprioin           => rxpcsdprioin,
         rxpmadprioin           => rxpmadprioin,
         txpcsdprioin           => txpcsdprioin,
         txpmadprioin           => txpmadprioin,
         refclkdividerdprioout  => refclkdividerdprioout_xhdl4,
         rxpcsdprioout          => rxpcsdprioout_xhdl7,
         rxpmadprioout          => rxpmadprioout_xhdl8,
         txpcsdprioout          => txpcsdprioout_xhdl11,
         txpmadprioout          => txpmadprioout_xhdl12,
         sync_status            => syncstatus,
         align_status           => alignstatus_int,
         dprioload              => dprioload_in,
         mdio_in                => mdio_in,
         mdc                    => dpclk_in,
         port_addr              => port_addr,
         dev_addr               => dev_addr,
         mdio_dis               => dpriodisable_in,
         mdio_rst               => mdio_rst,
         mdio_out               => dprioout_tim,
         data_enable_n          => dpriooe_tim,
         mdio_curr_st           => mdio_curr_st
      );
   
   --/////////////////////////////////////////////////////////////////////////
   -- establish outputs --------------------------------------------------- //
   --/////////////////////////////////////////////////////////////////////////
   
   alignstatus <= alignstatus_int;        -- from dskw_sm
   dpriodisableout <= dpriodisable_in;        -- from top
   digitaltestout <= "000000000X";        -- 10 Test ports
   
   -- reset and powerdown - everything turns into Active High ---------------
   pllresetout <= ( (NOT(qr_out_cmu1_cru_rstb) OR NOT(qr_out_cmu1_rxpma_rstb)) & (NOT(qr_out_cmu0_cru_rstb) OR NOT(qr_out_cmu0_rxpma_rstb)) );
   quadresetout <= qr_out_hard_reset;
   
   rxadceresetout <= NOT(chr_out_adce_rstb);
   rxanalogresetout <= NOT(chr_out_rxpma_rstb(3 DOWNTO 0));
   rxcruresetout <= (NOT(chr_out_cru_rstb)) OR (NOT(chr_out_rxpma_rstb));
   rxdigitalresetout <= chr_out_rxpcs_rst;
   txanalogresetout <= NOT(chr_out_txpma_rstb(3 DOWNTO 0));
   txdigitalresetout <= chr_out_txpcs_rst;
   
   clkdivpowerdn <= (NOT(qr_out_cmu1_cgb_pdb) & NOT(qr_out_cmu0_cgb_pdb));
   pllpowerdn <= (NOT(qr_out_cmu1_cru_pdb) & NOT(qr_out_cmu0_cru_pdb));
   
   rxadcepowerdown <= NOT(chr_out_adce_pdb);
   rxcrupowerdown <= NOT(chr_out_cru_pdb(3 DOWNTO 0));
   rxibpowerdown <= NOT(chr_out_rx_pdb(3 DOWNTO 0));   -- cycloneiv_modify
   txdetectrxpowerdown <= NOT(chr_out_rx_det_pdb(3 DOWNTO 0));
   txdividerpowerdown <= NOT(chr_out_cgb_pdb(3 DOWNTO 0));
   txobpowerdown <= NOT(chr_out_tx_pdb(3 DOWNTO 0));   -- cycloneiv_modify
   
   -- ww47_out
   autospdx4configsel <= auto_out_config_sel;
   autospdx4rateswitchout <= auto_out_pcie_switch;
   autospdx4spdchg <= auto_out_speed_change;
   phfifiox4ptrsreset <= auto_out_reset_pc_ptrs;
   rxphfifox4byteselout <= rxctrl_out_rx_we_out;
   rxphfifox4wrclkout <= rxclk_ctl_out_rx_div2_sync_out;
   rxphfifox4rdenableout <= rxctrl_out_rd_enable_out;
   rxphfifox4wrenableout <= rxctrl_out_wr_enable_out;
   scanout <= "ZZZZZZZZZZZZZZZZZZZZZZZ";
   txphfifox4byteselout <= txctrl_out_fifo_select_out;
   txphfifox4rdclkout <= txclk_ctl_out_tx_div2_sync_out;
   txphfifox4rdenableout <= txctrl_out_rd_enable_out;
   txphfifox4wrenableout <= txctrl_out_wr_enable_out;

---------------------------------------------------------------------------
-- Cyclone IV GX specific ------------------------------------------------------
--       - refclkout, coreclkout generations                             --
---------------------------------------------------------------------------

coreclkout_div2_clkin <= refclkout_tmp AND cram_rrefclk_out_div2; 
coreclkout_div2_reset <= refclkout_tmp AND ( NOT cram_rfreerun_centrl); 

PROCESS(coreclkout_div2_clkin, coreclkout_div2_reset)
BEGIN
    IF (coreclkout_div2_reset'EVENT AND coreclkout_div2_reset = '1')THEN
        coreclkout_div2_clkout <= '0';
    ELSIF (coreclkout_div2_clkin'EVENT AND coreclkout_div2_clkin = '1') THEN
        coreclkout_div2_clkout <= (NOT coreclkout_div2_clkout);
    END IF;
END PROCESS;


refclkout_tmp  <= refclkdig WHEN (cram_rcentrl_clk_sel = '1') ELSE txclk;

refclkout  <= refclkout_tmp;
coreclkout <= coreclkout_div2_clkout WHEN (cram_rrefclk_out_div2 = '1') ELSE refclkout_tmp;  
 
END trans;


