LIBRARY IEEE;
USE IEEE.std_logic_1164.ALL;

USE WORK.cycloneiv_hssi_components.ALL;
USE IEEE.VITAL_Timing.all;
USE IEEE.VITAL_Primitives.all;

ENTITY cycloneiv_hssi_calibration_block IS
    GENERIC (    
          --  generic control parameters  --
       MsgOn                   : Boolean := DefGlitchMsgOn;
       XOn                     : Boolean := DefGlitchXOn;
       MsgOnChecks             : Boolean := DefMsgOnChecks;
       XOnChecks               : Boolean := DefXOnChecks;
       InstancePath            : String := "*";
       TimingChecksOn          : Boolean := True;
          --  tipd  :interconnect path delays --
       tipd_clk                : VitalDelayType01 := DefpropDelay01;
        lpm_type                       :  string  := "cycloneiv_hssi_calibration_block";    
        cont_cal_mode                  :  string  := "false";    
        enable_rx_cal_tw               :  string  := "false";    
        enable_tx_cal_tw               :  string  := "false";
        migrated_from_prev_family      :  string  := "false";
        rtest                          :  string  := "false";            
        rx_cal_wt_value                :  integer := 0;    
        send_rx_cal_status             :  string  := "true";
        tx_cal_wt_value                :  integer := 1);   
    PORT (
        clk                            : IN std_logic := '0';   
        powerdn                        : IN std_logic := '0'; 
        testctrl                       : IN std_logic := '0';           
        calibrationstatus              : OUT std_logic_vector(4 DOWNTO 0);
        nonusertocmu                   : OUT std_logic
        );   
END cycloneiv_hssi_calibration_block;

ARCHITECTURE sim_calib_arch OF cycloneiv_hssi_calibration_block IS

    SIGNAL calibrationstatus_xhdl1  :  std_logic_vector(4 DOWNTO 0) := "11111";   

BEGIN
    calibrationstatus <= calibrationstatus_xhdl1;

END sim_calib_arch;
